// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/// @title ConstantVariablesUpgradeable
/// @notice Contract storing vault configuration (upgradeable version)
/// @dev Replaces immutable variables with storage variables for proxy compatibility
abstract contract ConstantVariablesUpgradeable is Initializable {
    /**
     * |
     * |        Storage Variables          |
     * |__________________________________
     */
    /// @dev Admin address (MPC signer)
    address internal _admin;

    /// @dev Position NFT contract
    address internal _positionNFT;

    /// @dev Oracle contract (SurgeOracle)
    address internal _oracle;

    /// @dev Liquidity Pool contract
    address internal _liquidityPool;

    /**
     * |
     * |        Constant Variables         |
     * |__________________________________
     */
    /// @dev BTC decimals (8)
    uint8 internal constant BTC_DECIMALS = 8;

    /// @dev Stable decimals (6 for USDC)
    uint8 internal constant STABLE_DECIMALS = 6;

    /**
     * |
     * |           Bit Masks               |
     * |__________________________________
     */
    uint256 internal constant X16 = 0xFFFF;
    uint256 internal constant X32 = 0xFFFFFFFF;
    uint256 internal constant X64 = 0xFFFFFFFFFFFFFFFF;
    uint256 internal constant X128 = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;

    /**
     * |
     * |           Precision               |
     * |__________________________________
     */
    /// @dev Oracle precision (1e27)
    uint256 internal constant ORACLE_PRECISION = 1e27;

    /// @dev BTC precision (1e8)
    uint256 internal constant BTC_PRECISION = 1e8;

    /// @dev Basis points precision (10000 = 100%)
    uint256 internal constant BASIS_POINTS = 10000;

    /**
     * |
     * |           Initializer             |
     * |__________________________________
     */
    /// @dev Initializes the contract configuration
    /// @param admin_ Admin address
    /// @param positionNFT_ Position NFT contract address
    /// @param oracle_ Oracle contract address
    /// @param liquidityPool_ Liquidity pool contract address
    function __ConstantVariables_init(address admin_, address positionNFT_, address oracle_, address liquidityPool_)
        internal
        onlyInitializing
    {
        _admin = admin_;
        _positionNFT = positionNFT_;
        _oracle = oracle_;
        _liquidityPool = liquidityPool_;
    }

    /**
     * |
     * |          View Functions           |
     * |__________________________________
     */
    /// @notice Get admin address
    function ADMIN() public view returns (address) {
        return _admin;
    }

    /// @notice Get position NFT address
    function POSITION_NFT() public view returns (address) {
        return _positionNFT;
    }

    /// @notice Get oracle address
    function ORACLE() public view returns (address) {
        return _oracle;
    }

    /// @notice Get liquidity pool address
    function LIQUIDITY_POOL() public view returns (address) {
        return _liquidityPool;
    }

    /// @dev Reserved storage gap for future upgrades
    uint256[46] private __gap;
}

