// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

/// @title Events
/// @notice Contract defining all vault events
contract Events {
    /// @notice Emitted when a new loan is created
    event LogLoanCreated(
        uint256 indexed nftId,
        address indexed user,
        uint256 collateralSats,
        uint256 debtStable,
        address indexed token,
        bytes32 btcPubkey
    );

    /// @notice Emitted when debt is repaid
    event LogDebtRepaid(uint256 indexed nftId, uint256 amount, uint256 remainingDebt);

    /// @notice Emitted when user borrows more
    event LogBorrowMore(uint256 indexed nftId, uint256 additionalDebt, uint256 totalDebt);

    /// @notice Emitted when collateral is added
    event LogCollateralAdded(uint256 indexed nftId, uint256 additionalSats, uint256 totalCollateral);

    /// @notice Emitted when collateral is refreshed (adjusted up or down) during an exit block update
    event LogCollateralRefreshed(uint256 indexed nftId, int256 collateralDiff, uint256 newTotalCollateral);

    /// @notice Emitted when collateral withdrawal is requested (pending off-chain BTC release)
    event LogCollateralWithdrawalRequested(uint256 indexed nftId, uint256 withdrawSats, bytes32 btcPubkey);

    /// @notice Emitted when collateral withdrawal is confirmed (after BTC release)
    event LogCollateralWithdrawn(uint256 indexed nftId, uint256 withdrawnSats, uint256 remainingCollateral);

    /// @notice Emitted when collateral withdrawal is cancelled (off-chain BTC release failed)
    event LogCollateralWithdrawalCancelled(uint256 indexed nftId, uint256 withdrawSats);

    /// @notice Emitted when liquidation is triggered (off-chain needs to act)
    event LogLiquidationTriggered(
        uint256 indexed nftId,
        uint256 collateralSats,
        uint256 debtStable,
        uint256 liqPenalty,
        uint256 collateralToLiquidate
    );

    /// @notice Emitted when liquidation is completed
    event LogLiquidation(uint256 indexed nftId, uint256 debtRepaid, uint256 collateralLiquidated);

    /// @notice Emitted when relayer status is updated
    event LogRelayerSet(address indexed relayer, bool status);

    /// @notice Emitted when vault parameters are updated
    event LogVaultParamsUpdated(uint256 minCR, uint256 liqThreshold, uint256 liqPenalty);

    /// @notice Emitted when admin transfer is proposed
    event LogAdminTransferProposed(address indexed currentAdmin, address indexed proposedAdmin);

    /// @notice Emitted when admin transfer is accepted
    event LogAdminTransferAccepted(address indexed previousAdmin, address indexed newAdmin);

    /// @notice Emitted when auction house is set
    event LogAuctionHouseSet(address indexed auctionHouse);

    /// @notice Emitted when auction is finalized
    event LogAuctionFinalized(uint256 indexed nftId, uint256 collateralSold, uint256 debtRepaid);

    /// @notice Emitted when positions are migrated from old VaultManager
    event LogPositionsMigrated(
        uint256[] nftIds, address indexed oldVaultManager, uint256 totalCollateral, uint256 totalDebt
    );

    /// @notice Emitted when a position switches to a different market
    event LogMarketSwitched(uint256 indexed nftId, uint256 oldMarketId, uint256 newMarketId);

    /// @notice Emitted when checkHealth is called on a healthy position
    event LogHealthChecked(uint256 indexed nftId, uint256 positionCR);

    /// @notice Emitted when a new pause manager is proposed
    event LogPauseManagerProposed(address indexed currentPauseManager, address indexed proposedPauseManager);

    /// @notice Emitted when pause manager transfer is accepted
    event LogPauseManagerAccepted(address indexed previousPauseManager, address indexed newPauseManager);

    /// @notice Emitted when a position is marked delinquent (exit block reached)
    event LogDelinquencyTriggered(
        uint256 indexed nftId,
        uint256 collateralSats,
        uint256 liveDebt,
        uint256 liqPenaltyBps,
        uint256 collateralToSeize
    );

    /// @notice Emitted when a position owner requests a credit line extension
    event LogCreditLineExtendRequested(uint256 indexed nftId, address indexed requester);

    /// @notice Emitted when admin sets or updates the exit block for a position
    event LogPositionExitBlockUpdated(uint256 indexed nftId, uint256 newExitBlock, bool reactivated);

    /// @notice Emitted when admin updates the delinquent buffer
    event LogDelinquentBufferSet(int256 buffer);

    /// @notice Emitted when admin updates the buyer discount
    event LogBuyerDiscountSet(uint256 discountBps);

    /// @notice Emitted when admin updates the extension LTV buffer
    event LogExtensionLtvBufferSet(uint256 bufferBps);

    /// @notice Emitted when admin updates the liquidation penalty
    event LogLiquidationPenaltySet(uint256 liqPenaltyBps);

    /// @notice Emitted when admin updates the liquidity pool address
    event LogLiquidityPoolSet(address newLP);

    /// @notice Emitted when admin updates the old liquidity pool address
    event LogOldLiquidityPoolSet(address oldLP);

    /// @notice Emitted when admin updates the old vault manager address
    event LogOldVaultManagerSet(address oldVaultManager);

    /// @notice Emitted when admin updates the oracle address
    event LogOracleSet(address newOracle);

    /// @notice Emitted when admin updates the position borrow cap
    event LogPositionBorrowCapSet(uint256 cap);

    /// @notice Emitted when admin marks positions as legacy
    event LogLegacyPositionsSet(uint256[] nftIds);

    /// @notice Emitted when the inline finalizeMarketDust call fails (best-effort) on the last
    ///         repay/liquidation of a market — the debt still closes; admin must retry the finalize.
    event LogMarketDustFinalizeDeferred(uint256 indexed marketId);
}

