// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {Variables} from "./Variables.sol";
import {ConstantVariablesUpgradeable} from "./ConstantVariablesUpgradeable.sol";
import {Events} from "./Events.sol";
import {ErrorTypes} from "../libraries/ErrorTypes.sol";

/// @title HelpersUpgradeable
/// @notice Helper methods for vault operations (upgradeable version)
abstract contract HelpersUpgradeable is Initializable, Variables, ConstantVariablesUpgradeable, Events {
    /// @dev Initializes the helpers contract
    function __Helpers_init(address admin_, address positionNFT_, address oracle_, address liquidityPool_)
        internal
        onlyInitializing
    {
        __ConstantVariables_init(admin_, positionNFT_, oracle_, liquidityPool_);
    }

    /**
     * |
     * |              Errors               |
     * |__________________________________
     */
    error SurgeVaultError(uint256 errorId_);

    /**
     * |
     * |            Modifiers              |
     * |__________________________________
     */
    modifier onlyAdmin() {
        address admin = currentAdmin == address(0) ? _admin : currentAdmin;
        if (msg.sender != admin) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyAdmin);
        }
        _;
    }

    modifier onlyRelayer() {
        if (!relayers[msg.sender]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyRelayer);
        }
        _;
    }

    modifier nonReentrant() {
        if (vaultVars & 1 == 1) {
            revert SurgeVaultError(ErrorTypes.VaultManager__AlreadyEntered);
        }
        vaultVars = vaultVars | 1;
        _;
        vaultVars = vaultVars & ~uint256(1);
    }

    /**
     * |
     * |          Helper Functions         |
     * |__________________________________
     */

    /// @notice Calculate collateral ratio for a position
    function _calculateCollateralRatio(uint256 collateralSats_, uint256 debtStable_, uint256 btcPrice_)
        internal
        pure
        returns (uint256 cr_)
    {
        if (debtStable_ == 0) return type(uint256).max;
        uint256 collateralValue = (collateralSats_ * btcPrice_) / BTC_PRECISION;
        cr_ = collateralValue / (debtStable_ * 1e5);
    }

    /// @notice Check if collateral ratio is sufficient
    function _checkCollateralRatio(uint256 collateralSats_, uint256 debtStable_, uint256 btcPrice_, uint256 minCR_)
        internal
        pure
    {
        uint256 cr = _calculateCollateralRatio(collateralSats_, debtStable_, btcPrice_);
        if (cr < minCR_ * 1e12) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidCollateralRatio);
        }
    }

    /// @notice Get BTC price from oracle for operations
    function _getOraclePrice() internal view returns (uint256 price_) {
        (bool success, bytes memory data) = _oracle.staticcall(abi.encodeWithSignature("getExchangeRateOperate()"));

        if (!success || data.length == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidOracle);
        }

        price_ = abi.decode(data, (uint256));

        if (price_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidOracle);
        }
    }

    /// @notice Get BTC price from oracle for liquidations
    function _getOraclePriceLiquidate() internal view returns (uint256 price_) {
        (bool success, bytes memory data) = _oracle.staticcall(abi.encodeWithSignature("getExchangeRateLiquidate()"));

        if (!success || data.length == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidOracle);
        }

        price_ = abi.decode(data, (uint256));

        if (price_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidOracle);
        }
    }

    /// @notice Update vault totals
    function _updateVaultTotals(int256 collateralDelta_, int256 debtDelta_) internal {
        uint256 vars = vaultVars;

        if (collateralDelta_ != 0) {
            uint256 totalColl = (vars >> 1) & X64;
            if (collateralDelta_ > 0) {
                totalColl += uint256(collateralDelta_);
            } else {
                totalColl -= uint256(-collateralDelta_);
            }
            vars = (vars & ~(X64 << 1)) | (totalColl << 1);
        }

        if (debtDelta_ != 0) {
            uint256 totalDebt = (vars >> 65) & X64;
            if (debtDelta_ > 0) {
                totalDebt += uint256(debtDelta_);
            } else {
                totalDebt -= uint256(-debtDelta_);
            }
            vars = (vars & ~(X64 << 65)) | (totalDebt << 65);
        }

        vaultVars = vars;
    }

    /// @notice Pack position base data
    function _packPositionData(uint256 collateralSats_, uint256 debtStable_, uint256 tickCount_)
        internal
        view
        returns (uint256 packed_)
    {
        packed_ = 1 // isActive
            | (collateralSats_ << 1) | (debtStable_ << 65) | (block.timestamp << 129) | (tickCount_ << 193);
    }

    /// @notice Unpack position base data
    function _unpackPositionData(uint256 packed_)
        internal
        pure
        returns (bool isActive_, uint256 collateralSats_, uint256 debtStable_, uint256 lastUpdate_, uint256 tickCount_)
    {
        isActive_ = (packed_ & 1) == 1;
        collateralSats_ = (packed_ >> 1) & X64;
        debtStable_ = (packed_ >> 65) & X64;
        lastUpdate_ = (packed_ >> 129) & X64;
        tickCount_ = (packed_ >> 193) & 0xFF;
    }

    /// @notice Pack tick position data
    function _packTickPosition(int24 tick_, uint256 collateralSats_, uint256 debtStable_)
        internal
        view
        returns (uint256 packed_)
    {
        packed_ = 1 // isActive
            | ((uint256(uint24(tick_)) & 0xFFFFFF) << 1) | (collateralSats_ << 25) | (debtStable_ << 89)
            | (block.timestamp << 153);
    }

    /// @notice Unpack tick position data
    function _unpackTickPosition(uint256 packed_)
        internal
        pure
        returns (bool isActive_, int24 tick_, uint256 collateralSats_, uint256 debtStable_, uint256 createdAt_)
    {
        isActive_ = (packed_ & 1) == 1;
        tick_ = int24(uint24((packed_ >> 1) & 0xFFFFFF));
        collateralSats_ = (packed_ >> 25) & X64;
        debtStable_ = (packed_ >> 89) & X64;
        createdAt_ = (packed_ >> 153) & X64;
    }

    /// @notice Get vault parameters
    /// @return liqPenalty_ Liquidation penalty
    function _getVaultParams() internal view returns (uint256 liqPenalty_) {
        uint256 vars = vaultVars;
        liqPenalty_ = (vars >> 193) & X16;
    }

    /**
     * |
     * |       Tick-Based Helpers          |
     * |__________________________________
     */

    /// @notice Calculate tick from collateral ratio
    function _getTickAtRatio(uint256 collateralSats_, uint256 debtStable_, uint256 btcPrice_)
        internal
        pure
        returns (int24 tick_)
    {
        if (debtStable_ == 0) return type(int24).max;

        uint256 cr = _calculateCollateralRatio(collateralSats_, debtStable_, btcPrice_);
        int256 tickValue = int256(cr) - 12500;
        tickValue = tickValue * 100;

        int24 maxTick = type(int24).max;
        int24 minTick = type(int24).min;

        if (tickValue > int256(int24(maxTick))) {
            tick_ = maxTick;
        } else if (tickValue < int256(int24(minTick))) {
            tick_ = minTick;
        } else {
            tick_ = int24(tickValue);
        }
    }

    /// @notice Initialize or update tick data
    function _updateTickData(int256 tick_, int256 debtDelta_) internal returns (uint256 tickData_) {
        tickData_ = tickData[tick_];
        uint256 totalDebt = (tickData_ >> 1) & X64;

        if (debtDelta_ > 0) {
            totalDebt += uint256(debtDelta_);
        } else if (debtDelta_ < 0) {
            uint256 dec = uint256(-debtDelta_);
            totalDebt = totalDebt > dec ? totalDebt - dec : 0;
        }

        tickData_ = ((tickData_ & 1) | (totalDebt << 1));
        tickData[tick_] = tickData_;
    }

    /**
     * |
     * |       Interest Helpers            |
     * |__________________________________
     */

    /// @notice Calculate accrued interest for a position
    /// @dev Virtual function - override in VaultManagerUpgradeable to use positionMarket mapping
    function _calculatePositionInterest(uint256 nftId_) internal view virtual returns (uint256 interest_) {
        uint256 packed = positionData[nftId_];
        if (packed == 0) return 0;

        (,, uint256 debtStable, uint256 lastUpdate,) = _unpackPositionData(packed);

        if (debtStable == 0) return 0;

        uint256 timeElapsed = block.timestamp - lastUpdate;
        if (timeElapsed == 0) return 0;

        // Default to market 0 for base implementation (old single-market behavior)
        uint256 marketId = 0;

        (bool success, bytes memory data) =
            _liquidityPool.staticcall(abi.encodeWithSignature("getMarketBorrowRate(uint256)", marketId));

        if (!success || data.length == 0) return 0;
        uint256 borrowRateBps = abi.decode(data, (uint256));

        interest_ = (debtStable * borrowRateBps * timeElapsed) / (10000 * 365 days);
    }

    /// @notice Get live debt from borrow shares (overridden in VaultManagerUpgradeable)
    /// @dev Returns 0 in base implementation; new positions use shares × LP.borrowExchangeRate
    function _getCurrentDebtFromShares(
        uint256 /*nftId_*/
    )
        internal
        view
        virtual
        returns (uint256)
    {
        return 0;
    }

    /// @notice Get position debt including accrued interest
    function _getDebtWithInterest(uint256 nftId_) internal view returns (uint256 totalDebt_) {
        uint256 packed = positionData[nftId_];
        if (packed == 0) return 0;

        uint256 sharesDebt = _getCurrentDebtFromShares(nftId_);
        if (sharesDebt > 0) return sharesDebt;

        (,, uint256 debtStable,,) = _unpackPositionData(packed);
        uint256 interest = _calculatePositionInterest(nftId_);

        totalDebt_ = debtStable + interest;
    }

    /// @notice Update position with accrued interest
    function _accruePositionInterest(uint256 nftId_) internal virtual returns (uint256 newDebt_) {
        uint256 interest = _calculatePositionInterest(nftId_);

        if (interest > 0) {
            uint256 packed = positionData[nftId_];
            (bool isActive, uint256 collateralSats, uint256 debtStable,, uint256 tickCount) =
                _unpackPositionData(packed);

            newDebt_ = debtStable + interest;

            positionData[nftId_] = (isActive ? 1 : 0) | (collateralSats << 1) | (newDebt_ << 65)
                | (block.timestamp << 129) | (tickCount << 193);

            _updateVaultTotals(0, int256(interest));
        } else {
            uint256 packed = positionData[nftId_];
            (bool isActive, uint256 collateralSats, uint256 debtStable,, uint256 tickCount) =
                _unpackPositionData(packed);

            newDebt_ = debtStable;

            positionData[nftId_] = (isActive ? 1 : 0) | (collateralSats << 1) | (debtStable << 65)
                | (block.timestamp << 129) | (tickCount << 193);
        }
    }

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;
}

src/common/Variables.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

/// @title Variables
/// @notice Contract storing vault state variables
///
/// @dev ┌─────────────────────────────────────────────────────────────────────────────────────┐
///      │  STORAGE LAYOUT FROZEN — DO NOT APPEND, REORDER, RESIZE, OR INSERT ANY VARIABLE HERE.  │
///      └─────────────────────────────────────────────────────────────────────────────────────┘
///      This contract occupies storage slots 0–12 and, unlike every other module in the chain, has
///      NO trailing `__gap`. It is a base of the LIVE, already-deployed `VaultManagerUpgradeable`
///      proxy, and in the C3 linearization it sits directly before `ConstantVariablesUpgradeable`
///      (whose `_admin` lands at slot 13). Any change to this contract's layout — including
///      appending a variable OR adding a `__gap` now — shifts `_admin`, `_positionNFT`, `_oracle`,
///      and `_liquidityPool` down, corrupting admin/oracle/liquidity-pool resolution on the live
///      proxy. If `currentAdmin` was never rotated, `onlyAdmin` resolves to `_admin == address(0)`
///      and the protocol is left with no functioning admin (recoverable only via the ProxyAdmin
///      owner). A `__gap` cannot be retrofitted here because all downstream storage sits below it.
///
///      To add new vault state: append to `VaultManagerUpgradeable` instead — it reserves a
///      trailing `uint256[30] __gap` for exactly this purpose. The CI storage-layout regression
///      check (scripts/check-storage-layout.sh, run in .github/workflows/test.yml) will fail the
///      build if this layout ever shifts.
contract Variables {
    /**
     * |
     * |        Storage Variables          |
     * |__________________________________
     */
    /// @notice vaultVars (256 bits packed)
    /// Bit 0: reentrancy guard
    /// Bits 1-64: totalCollateralSats
    /// Bits 65-128: totalDebtStable
    /// Bits 129-160: minCollateralRatioBps (125% = 12500)
    /// Bits 161-192: liqThresholdBps (112% = 11200)
    /// Bits 193-208: liqPenaltyBps (8% = 800)
    uint256 internal vaultVars;

    /// @notice Position base data (256 bits packed per NFT)
    /// Bit 0: isActive
    /// Bits 1-64: totalCollateralSats
    /// Bits 65-128: totalDebtStable
    /// Bits 129-192: lastUpdateTimestamp
    /// Bits 193-200: tickPositionCount (number of tick positions)
    mapping(uint256 => uint256) internal positionData;

    /// @notice Individual tick positions for each NFT
    /// nftId => tickIndex => tickPositionData (256 bits packed)
    /// Bit 0: isActive
    /// Bits 1-24: tick (int24)
    /// Bits 25-88: collateralSats (64 bits)
    /// Bits 89-152: debtStable (64 bits)
    /// Bits 153-216: createdAt timestamp
    mapping(uint256 => mapping(uint256 => uint256)) internal tickPositions;

    /// @notice Tick data for managing liquidation paths
    /// tick => tickData (stores total liquidity, debt factor, etc.)
    mapping(int256 => uint256) internal tickData;

    /// @notice Tick ID data for tracking liquidation history
    /// tick => (tickId / 3) => packed data for 3 tick IDs
    mapping(int256 => mapping(uint256 => uint256)) internal tickId;

    /// @notice Branch data for merged liquidation paths
    /// branchId => branchData
    mapping(uint256 => uint256) internal branchData;

    /// @notice Current branch ID counter
    uint256 internal currentBranchId;

    /// @notice Token address borrowed for each position (USDC, USDT, DAI, etc.)
    /// nftId => token address
    mapping(uint256 => address) public positionToken;

    /// @notice Loan expiry timestamp for each position (BTC script time lock)
    /// nftId => expiry timestamp
    mapping(uint256 => uint256) public loanExpiry;

    /// @notice Bitcoin x-only pubkey (32 bytes) for each position
    /// nftId => x-only pubkey (for linking credit to Bitcoin address)
    mapping(uint256 => bytes32) public positionBtcPubkey;

    /// @notice Relayers who can trigger health checks
    mapping(address => bool) internal relayers;

    /// @notice Current admin address (can be updated)
    address internal currentAdmin;

    /// @notice Pending admin address for two-step transfer
    address internal pendingAdmin;

    // ────────────────────────────────────────────────────────────────────────────────────────────
    // ⛔ DO NOT ADD VARIABLES BELOW THIS LINE (and do NOT add a `__gap` here either).
    // This layout is frozen at slots 0–12 for the live VaultManagerUpgradeable proxy. Appending here
    // shifts ConstantVariablesUpgradeable._admin (slot 13) and bricks admin resolution.
    // Add new vault state to VaultManagerUpgradeable's trailing __gap instead. See the header note.
    // ────────────────────────────────────────────────────────────────────────────────────────────
}

