// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

/// @title IMarketProvider
/// @notice Interface for pluggable market providers
/// @dev Each market type (variable, fixed) implements this interface
interface IMarketProvider {
    /// @notice Get the current borrow rate for this market (may update internal state).
    /// @dev For adaptive providers this is state-changing; fixed providers remain pure.
    ///      Called by LiquidityPoolV3._accrueMarketInterest on every interest accrual.
    /// @param borrowed_ Total amount borrowed from market
    /// @param liquidity_ Total liquidity in market
    /// @return borrowRateBps_ Borrow rate in basis points (e.g., 690 = 6.9%)
    function getBorrowRate(uint256 borrowed_, uint256 liquidity_) external returns (uint256 borrowRateBps_);

    /// @notice Read-only borrow rate — never updates state.
    /// @dev Called by LiquidityPoolV3.getMarketBorrowRate for display/informational purposes.
    /// @param borrowed_ Total amount borrowed from market
    /// @param liquidity_ Total liquidity in market
    /// @return borrowRateBps_ Borrow rate in basis points
    function getBorrowRateView(uint256 borrowed_, uint256 liquidity_) external view returns (uint256 borrowRateBps_);

    /// @notice Get the supply rate (what lenders earn)
    /// @param borrowed_ Total amount borrowed from market
    /// @param liquidity_ Total liquidity in market
    /// @return supplyRateBps_ Supply rate in basis points
    function getSupplyRate(uint256 borrowed_, uint256 liquidity_) external view returns (uint256 supplyRateBps_);

    /// @notice Get the maximum LTV for this market
    /// @return maxLtvBps_ Max LTV in basis points (e.g., 8000 = 80%)
    function getMaxLTV() external view returns (uint256 maxLtvBps_);

    /// @notice Get the reserve rate (protocol fee)
    /// @return reserveRateBps_ Reserve rate in basis points (e.g., 1000 = 10%)
    function getReserveRate() external view returns (uint256 reserveRateBps_);

    /// @notice Get the origination fee (if any)
    /// @return originationFeeBps_ Origination fee in basis points (e.g., 100 = 1%)
    function getOriginationFee() external view returns (uint256 originationFeeBps_);

    /// @notice Calculate interest for a given principal and time period
    /// @param principal_ Principal amount
    /// @param timeElapsed_ Time elapsed in seconds
    /// @param borrowed_ Total borrowed (for rate calculation)
    /// @param liquidity_ Total liquidity (for rate calculation)
    /// @return interest_ Interest amount
    function calculateInterest(uint256 principal_, uint256 timeElapsed_, uint256 borrowed_, uint256 liquidity_)
        external
        view
        returns (uint256 interest_);

    /// @notice Get market information
    /// @return name_ Market name
    /// @return marketType_ Market type (0 = variable, 1 = fixed)
    function getMarketInfo() external view returns (string memory name_, uint8 marketType_);
}

