// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {TaylorMath} from "./TaylorMath.sol";
import {Market, UserPosition} from "./PoolTypes.sol";

/**
 * @title PoolLogicLib
 * @notice External read-only helpers extracted from LiquidityPoolV3 to keep the
 *         implementation under the EIP-170 24,576-byte contract size limit.
 * @dev Deployed as a separate linked library. Called via DELEGATECALL from the pool,
 *      so it runs in the pool's storage context; the caller passes the relevant
 *      storage mappings by reference (this library declares no storage of its own,
 *      so the proxy's storage layout is unaffected). Every function here is a verbatim
 *      move of the corresponding pool getter — signatures on the pool are unchanged,
 *      so external/client callers see no difference.
 */
library PoolLogicLib {
    uint256 private constant EXCHANGE_RATE_PRECISION = 1e18;
    uint256 private constant BPS_DENOMINATOR = 10000;
    uint256 private constant SECONDS_PER_YEAR = 365 days;
    // Must match LiquidityPoolV3's BORROW_DUST_THRESHOLD / SUPPLY_DUST_THRESHOLD (finalizeMarketDustCore).
    uint256 private constant BORROW_DUST_THRESHOLD = 10000;
    uint256 private constant SUPPLY_DUST_THRESHOLD = 10000;

    /// @dev Supply exchange rate floored at 1 — mirrors LiquidityPoolV3._flooredSupplyRate. A total
    ///      loss can drive totalSupplyAssets to 0 while shares remain outstanding; the raw
    ///      assets*PRECISION/shares would then be 0, and every later share-issuance divide
    ///      (amount*PRECISION/rate) would revert on division-by-zero with no recovery path. Flooring
    ///      at 1 keeps the market usable. Callers must ensure shares_ > 0 (guarded at each call site).
    function _flooredSupplyRate(uint256 assets_, uint256 shares_) internal pure returns (uint256) {
        uint256 rate = (assets_ * EXCHANGE_RATE_PRECISION) / shares_;
        return rate == 0 ? 1 : rate;
    }

    /// @dev Selector-identical to LiquidityPoolV3.InvalidMarket (custom-error selectors
    ///      are name-only, independent of the defining contract), so revert data decodes
    ///      the same for existing clients.
    error InvalidMarket();

    /// @dev Mirror of LiquidityPoolV3._computeBorrowInterest.
    function _computeBorrowInterest(uint256 assets_, uint256 rateBps_, uint256 elapsed_)
        private
        pure
        returns (uint256)
    {
        uint256 ratePerSecondWad = (rateBps_ * EXCHANGE_RATE_PRECISION) / (BPS_DENOMINATOR * SECONDS_PER_YEAR);
        return (assets_ * TaylorMath.wTaylorCompounded(ratePerSecondWad, elapsed_)) / EXCHANGE_RATE_PRECISION;
    }

    function projectedBorrowExchangeRate(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        uint256 marketId_
    ) external view returns (uint256) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        Market storage market = markets[marketId_];

        if (market.totalBorrowShares == 0 || market.totalBorrowAssets == 0) {
            return market.borrowExchangeRate;
        }

        uint256 timeElapsed = block.timestamp - market.lastAccrueTime;
        if (timeElapsed == 0) return market.borrowExchangeRate;

        // Read current borrow rate view-only (never updates rateAtTarget state)
        (bool ok, bytes memory data) = address(market.provider).staticcall(
            abi.encodeWithSignature(
                "getBorrowRateView(uint256,uint256)", market.totalBorrowAssets, market.totalSupplyAssets
            )
        );
        if (!ok || data.length < 32) {
            // Fallback for providers without getBorrowRateView
            (ok, data) = address(market.provider).staticcall(
                abi.encodeWithSignature(
                    "getBorrowRate(uint256,uint256)", market.totalBorrowAssets, market.totalSupplyAssets
                )
            );
        }
        if (!ok || data.length < 32) return market.borrowExchangeRate;

        uint256 borrowRateBps = abi.decode(data, (uint256));
        uint256 interestAccrued = _computeBorrowInterest(market.totalBorrowAssets, borrowRateBps, timeElapsed);

        uint256 projectedBorrowAssets = market.totalBorrowAssets + interestAccrued;
        return (projectedBorrowAssets * EXCHANGE_RATE_PRECISION) / market.totalBorrowShares;
    }

    function marketBorrowRate(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        uint256 marketId_
    ) external view returns (uint256) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        Market storage market = markets[marketId_];

        (bool ok, bytes memory data) = address(market.provider).staticcall(
            abi.encodeWithSignature(
                "getBorrowRateView(uint256,uint256)", market.totalBorrowAssets, market.totalSupplyAssets
            )
        );
        if (ok && data.length >= 32) return abi.decode(data, (uint256));

        // Fallback for legacy providers that implement getBorrowRate as view/pure
        (ok, data) = address(market.provider).staticcall(
            abi.encodeWithSignature(
                "getBorrowRate(uint256,uint256)", market.totalBorrowAssets, market.totalSupplyAssets
            )
        );
        if (ok && data.length >= 32) return abi.decode(data, (uint256));

        return 0;
    }

    /// @dev Mirror of LiquidityPoolV3._calculateTotalExposureToMarket.
    function _calculateTotalExposureToMarket(
        mapping(uint256 => Market) storage markets,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        uint256 marketId_
    ) private view returns (uint256) {
        if (marketId_ == 0) {
            return markets[0].totalPhysicalSupply > markets[0].totalPhysicalBorrow
                ? markets[0].totalPhysicalSupply - markets[0].totalPhysicalBorrow
                : 0;
        }

        Market storage variableMarket = markets[0];
        uint256 totalExposure = 0;
        uint256 queueLen = depositorQueue.length;
        for (uint256 i = 0; i < queueLen; i++) {
            address user = depositorQueue[i];
            uint256 userExposure = userExposureBps[user][marketId_];
            if (userExposure == 0) continue;

            uint256 userMarket0Shares = userPositions[user][0].supplyShares;
            uint256 userMarket0Balance = variableMarket.supplyExchangeRate > 0
                ? (userMarket0Shares * variableMarket.supplyExchangeRate) / EXCHANGE_RATE_PRECISION
                : userActualAllocation[user][0];

            totalExposure += (userMarket0Balance * userExposure) / 10000;
        }
        return totalExposure;
    }

    function maxBorrowAmount(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        uint256 marketId_
    ) external view returns (uint256) {
        if (marketId_ >= marketCount || !markets[marketId_].active) {
            return 0;
        }

        Market storage m0 = markets[0];

        if (marketId_ == 0) {
            return m0.totalPhysicalSupply > m0.totalPhysicalBorrow ? m0.totalPhysicalSupply - m0.totalPhysicalBorrow : 0;
        }

        uint256 totalExposure = _calculateTotalExposureToMarket(
            markets, depositorQueue, userExposureBps, userPositions, userActualAllocation, marketId_
        );
        uint256 m0Liquidity =
            m0.totalPhysicalSupply > m0.totalPhysicalBorrow ? m0.totalPhysicalSupply - m0.totalPhysicalBorrow : 0;

        return totalExposure < m0Liquidity ? totalExposure : m0Liquidity;
    }

    /// @dev Maximum additional value `user` can allocate to fixed market `marketId_`.
    ///      Exposure is an AGGREGATE cap: at most `exposure%` of the LP's total current value
    ///      (residual market-0 value + value of every fixed-market position — i.e. principal +
    ///      yield) may be allocated across all fixed markets combined. Capacity = that cap minus
    ///      what is already allocated, bounded by the liquid market-0 balance. Everything is
    ///      measured at current share value, so yield lifts the cap and the allocated side
    ///      together. Mirror of LiquidityPoolV3's capacity model.
    ///
    ///      Example (100K deposit, 100% exposure): 30K already in fixed markets -> cap 100K,
    ///      allocated 30K -> capacity 70K; once allocated reaches 100K, capacity is 0. At 50%
    ///      exposure, allocation stops once 50K is allocated (half stays liquid).
    function _lpAllocatableCapacity(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage, // userLockedAllocation: unused — capacity is derived from current share value, not principal-locked
        address user,
        uint256 marketId_
    ) private view returns (uint256) {
        uint256 exposure = userExposureBps[user][marketId_];
        if (exposure == 0) return 0;

        // Residual (liquid) market-0 value at current share value; fall back to the tracked
        // allocation if the market-0 exchange rate is unset.
        uint256 residual = markets[0].supplyExchangeRate > 0
            ? (userPositions[user][0].supplyShares * markets[0].supplyExchangeRate) / EXCHANGE_RATE_PRECISION
            : userActualAllocation[user][0];

        // Aggregate value already allocated across all fixed markets (current share value).
        uint256 allocated = 0;
        for (uint256 m = 1; m < marketCount; m++) {
            uint256 shares = userPositions[user][m].supplyShares;
            if (shares == 0) continue;
            allocated += (shares * markets[m].supplyExchangeRate) / EXCHANGE_RATE_PRECISION;
        }

        // exposure% of TOTAL value (residual + allocated) is the aggregate cap on fixed markets.
        uint256 cap = ((residual + allocated) * exposure) / 10000;
        if (allocated >= cap) return 0;
        uint256 capacity = cap - allocated;

        // Never allocate more than is actually liquid in market 0.
        return capacity < residual ? capacity : residual;
    }

    /// @notice External view over the capacity model, so callers outside allocation (e.g. the
    ///         withdraw-queue replacement check) use the exact same formula — one source of truth.
    function lpAllocatableCapacity(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        address user,
        uint256 marketId_
    ) external view returns (uint256) {
        return _lpAllocatableCapacity(
            markets, marketCount, userExposureBps, userPositions, userActualAllocation, userLockedAllocation, user, marketId_
        );
    }

    function previewAllocation(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        address[] calldata lpAddresses,
        uint256 amount_,
        uint256 marketId_
    ) external view returns (uint256[] memory perLpAmounts, uint256 totalAllocated, bool fullyAllocated) {
        perLpAmounts = new uint256[](lpAddresses.length);
        if (marketId_ == 0 || marketId_ >= marketCount) return (perLpAmounts, 0, false);

        uint256 remaining = amount_;
        uint256 variableAvailable = markets[0].totalPhysicalSupply > markets[0].totalPhysicalBorrow
            ? markets[0].totalPhysicalSupply - markets[0].totalPhysicalBorrow
            : 0;

        for (uint256 i = 0; i < lpAddresses.length && remaining > 0; i++) {
            uint256 lpCap = _lpAllocatableCapacity(
                markets,
                marketCount,
                userExposureBps,
                userPositions,
                userActualAllocation,
                userLockedAllocation,
                lpAddresses[i],
                marketId_
            );
            if (lpCap == 0) continue;

            uint256 toAllocate = remaining > lpCap ? lpCap : remaining;
            if (toAllocate > variableAvailable) toAllocate = variableAvailable;
            if (toAllocate == 0) continue;

            perLpAmounts[i] = toAllocate;
            totalAllocated += toAllocate;
            remaining -= toAllocate;
            variableAvailable -= toAllocate;
        }

        fullyAllocated = (remaining == 0);
    }

    // ============================================
    // ALLOCATION CLUSTER (state-changing; moved verbatim from the pool)
    // ============================================

    /// @dev Selector-identical to the pool's events/error (topics and error selectors are
    ///      name-only), so logs and reverts decode the same for existing clients.
    event FundsAllocated(address indexed user, uint256 indexed marketId, uint256 amount);
    event FundsDeallocated(address indexed user, uint256 indexed marketId, uint256 amount);
    event ExitDequeued(address indexed lender, uint256 indexed marketId);

    error InsufficientExposure();

    /// @dev Mirror of the pool's canAllocateFromLPs. Public wrapper below preserves the
    ///      pool's external `canAllocateFromLPs` selector; the private form is reused by
    ///      allocateFundsToMarket without a second delegatecall.
    function _canAllocateFromLPs(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        address[] calldata lpAddresses,
        uint256 amount_,
        uint256 marketId_
    ) private view returns (bool) {
        if (marketId_ == 0 || marketId_ >= marketCount) return false;

        uint256 variableAvailable = markets[0].totalPhysicalSupply > markets[0].totalPhysicalBorrow
            ? markets[0].totalPhysicalSupply - markets[0].totalPhysicalBorrow
            : 0;
        if (amount_ > variableAvailable) return false;

        uint256 totalCapacity = 0;
        for (uint256 i = 0; i < lpAddresses.length; i++) {
            totalCapacity += _lpAllocatableCapacity(
                markets,
                marketCount,
                userExposureBps,
                userPositions,
                userActualAllocation,
                userLockedAllocation,
                lpAddresses[i],
                marketId_
            );
            if (totalCapacity >= amount_) return true;
        }
        return false;
    }

    function canAllocateFromLPs(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        address[] calldata lpAddresses,
        uint256 amount_,
        uint256 marketId_
    ) external view returns (bool) {
        return _canAllocateFromLPs(
            markets,
            marketCount,
            userExposureBps,
            userPositions,
            userActualAllocation,
            userLockedAllocation,
            lpAddresses,
            amount_,
            marketId_
        );
    }

    /// @dev Pack an allocation receipt into one slot: drawn principal (uint96, high 96 bits)
    ///      over the lender address (uint160, low 160 bits). Principal is a hint capped by the
    ///      lender's live balance at unwind time, so clamping to uint96 is safe.
    function _packReceipt(address lender, uint256 principal) private pure returns (uint256) {
        uint256 p = principal > type(uint96).max ? type(uint96).max : principal;
        return (p << 160) | uint256(uint160(lender));
    }

    function allocateFundsToMarket(
        mapping(uint256 => Market) storage markets,
        uint256 marketCount,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => uint256)) storage userExposureBps,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256[] storage ledger,
        uint256 marketId_,
        uint256 amount_,
        address[] calldata lpAddresses
    ) external {
        // Use provided LP list if specified and market is not 0, otherwise use FIFO queue
        bool useCustomList = lpAddresses.length > 0 && marketId_ != 0;

        // Validate custom LP list up front using the same capacity model the loop enforces
        if (
            useCustomList
                && !_canAllocateFromLPs(
                    markets,
                    marketCount,
                    userExposureBps,
                    userPositions,
                    userActualAllocation,
                    userLockedAllocation,
                    lpAddresses,
                    amount_,
                    marketId_
                )
        ) {
            revert InsufficientExposure();
        }

        uint256 remaining = amount_;

        Market storage variableMarket = markets[0];
        Market storage targetMarket = markets[marketId_];

        uint256 listLength = useCustomList ? lpAddresses.length : depositorQueue.length;

        // FIFO allocation: allocate from first lender in queue until their funds are exhausted,
        // then move to next lender. Exposure determines the maximum each lender can allocate.
        for (uint256 i = 0; i < listLength && remaining > 0; i++) {
            address user = useCustomList ? lpAddresses[i] : depositorQueue[i];

            // Per-LP cap = min(exposure headroom, free Market 0 funds); 0 skips this LP
            uint256 lpCap = _lpAllocatableCapacity(
                markets,
                marketCount,
                userExposureBps,
                userPositions,
                userActualAllocation,
                userLockedAllocation,
                user,
                marketId_
            );
            if (lpCap == 0) continue;

            // Allocate up to the minimum of: remaining needed, this LP's cap
            uint256 toAllocate = remaining > lpCap ? lpCap : remaining;

            uint256 variableAvailable = variableMarket.totalPhysicalSupply > variableMarket.totalPhysicalBorrow
                ? variableMarket.totalPhysicalSupply - variableMarket.totalPhysicalBorrow
                : 0;
            if (toAllocate > variableAvailable) toAllocate = variableAvailable;

            if (toAllocate == 0) continue;

            userActualAllocation[user][0] =
                userActualAllocation[user][0] > toAllocate ? userActualAllocation[user][0] - toAllocate : 0;
            userActualAllocation[user][marketId_] += toAllocate;
            userLockedAllocation[user][marketId_] += toAllocate;

            variableMarket.totalPhysicalSupply -= toAllocate;
            targetMarket.totalPhysicalSupply += toAllocate;

            // Use regular division (not _mulDivUp) to avoid systematic over-burning that accumulates as dust
            uint256 burnVShares = (toAllocate * EXCHANGE_RATE_PRECISION) / variableMarket.supplyExchangeRate;
            if (burnVShares > userPositions[user][0].supplyShares) burnVShares = userPositions[user][0].supplyShares;

            userPositions[user][0].supplyShares -= burnVShares;
            variableMarket.totalSupplyShares -= burnVShares;
            variableMarket.totalSupplyAssets -= toAllocate;

            uint256 mintFShares = (toAllocate * EXCHANGE_RATE_PRECISION) / targetMarket.supplyExchangeRate;
            userPositions[user][marketId_].supplyShares += mintFShares;
            targetMarket.totalSupplyShares += mintFShares;
            targetMarket.totalSupplyAssets += toAllocate;

            if (variableMarket.totalSupplyShares > 0) {
                variableMarket.supplyExchangeRate =
                    _flooredSupplyRate(variableMarket.totalSupplyAssets, variableMarket.totalSupplyShares);
            } else {
                variableMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
            }
            if (targetMarket.totalSupplyShares > 0) {
                targetMarket.supplyExchangeRate =
                    _flooredSupplyRate(targetMarket.totalSupplyAssets, targetMarket.totalSupplyShares);
            } else {
                targetMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
            }

            // Write the receipt (lender, drawn principal) onto the market's ledger stack.
            ledger.push(_packReceipt(user, toAllocate));

            remaining -= toAllocate;
            emit FundsAllocated(user, marketId_, toAllocate);
        }

        if (remaining > 0) revert InsufficientExposure();
    }

    /// @dev Unpack a ledger receipt into (lender, principal hint).
    function _unpackReceipt(uint256 entry) private pure returns (address lender, uint256 principal) {
        lender = address(uint160(entry));
        principal = entry >> 160;
    }

    /// @dev Single per-lender unwind used by BOTH the repay and loss paths. Unwinds up to
    ///      `maxValue` of `user`'s live position in fixed market `marketId_`, moving that value
    ///      back to market 0, and returns the value unwound.
    ///
    ///      Profit and loss need no separate share math: a fixed market is a share pool, so P&L is
    ///      already reflected in `supplyExchangeRate` (gain/loss adjusts totalSupplyAssets, which
    ///      reprices every holder pro rata). Unwinding is therefore always "burn N shares, pay
    ///      N x rate", whichever direction the market moved.
    ///
    ///      The ONLY divergence is physical-cash bookkeeping, controlled by `deferPhysical`:
    ///        false (repay): reduce the target's physical supply proportionally here, and refresh
    ///                       both exchange rates per lender.
    ///        true  (loss):  leave target physical and the rates alone — the loss write-down is a
    ///                       precise, externally-known figure applied exactly once in
    ///                       finalizeLossPhysical. Doing it here too would double-reduce physical
    ///                       and destroy remaining LPs' liquidity.
    ///      Crediting market 0 (shares, assets AND physical) is common to both.
    function _unwindLenderCore(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        address user,
        uint256 maxValue,
        bool deferPhysical
    ) private returns (uint256) {
        Market storage variableMarket = markets[0];
        Market storage targetMarket = markets[marketId_];

        // Eligibility is SHARE-based, not principal-based: any shareholder is unwound proportionally
        // to their live value. Gating on `locked == 0` used to exclude yield-only positions (e.g. the
        // residual left by a principal-capped swap exit), forcing them to wait for market close to
        // realise their yield. `userLocked` is still read, but only to decrement the principal
        // overlay pro rata (it is 0 for yield-only holders, so principalUnlock is 0 — no underflow).
        uint256 userLocked = userLockedAllocation[user][marketId_];
        uint256 userTotalShares = userPositions[user][marketId_].supplyShares;
        if (userTotalShares == 0) return 0;

        uint256 userPositionValue = (userTotalShares * targetMarket.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;

        uint256 shareValue = userPositionValue > maxValue ? maxValue : userPositionValue;
        if (shareValue == 0) return 0;

        uint256 burnFShares = (shareValue * EXCHANGE_RATE_PRECISION) / targetMarket.supplyExchangeRate;
        if (burnFShares > userTotalShares) burnFShares = userTotalShares;
        if (burnFShares > targetMarket.totalSupplyShares) burnFShares = targetMarket.totalSupplyShares;

        // Recompute the value from the (floored) shares actually burned, so value moved always
        // matches shares burned — otherwise a sub-share `maxValue` would credit market 0 while
        // burning nothing (a conservation leak).
        shareValue = (burnFShares * targetMarket.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;
        if (shareValue > targetMarket.totalSupplyAssets) shareValue = targetMarket.totalSupplyAssets;

        if (shareValue > maxValue) {
            shareValue = maxValue;
            burnFShares = (shareValue * EXCHANGE_RATE_PRECISION) / targetMarket.supplyExchangeRate;
            if (burnFShares > userTotalShares) burnFShares = userTotalShares;
            if (burnFShares > targetMarket.totalSupplyShares) burnFShares = targetMarket.totalSupplyShares;
        }

        // Dust guard: once the rate exceeds 1e18 (any accrued interest), a sub-share `maxValue`
        // floors burnFShares to 0 — nothing to unwind. Return 0 WITHOUT mutating state or emitting
        // a zero-value FundsDeallocated, so the caller stops rather than treating the no-op as a
        // completed/stale receipt.
        if (burnFShares == 0 || shareValue == 0) return 0;

        uint256 principalUnlock = (burnFShares * userLocked) / userTotalShares;
        if (userLockedAllocation[user][marketId_] >= principalUnlock) {
            userLockedAllocation[user][marketId_] -= principalUnlock;
        } else {
            userLockedAllocation[user][marketId_] = 0;
        }

        if (userActualAllocation[user][marketId_] >= shareValue) {
            userActualAllocation[user][marketId_] -= shareValue;
        } else {
            userActualAllocation[user][marketId_] = 0;
        }
        if (userActualAllocation[user][marketId_] == 0 && userPositions[user][marketId_].supplyShares == 0) {
            userLockedAllocation[user][marketId_] = 0;
        }
        userActualAllocation[user][0] += shareValue;

        // Divergence 1 — target physical. Computed with the pre-burn share total.
        if (!deferPhysical) {
            uint256 physicalToReduce = targetMarket.totalSupplyShares > 0
                ? (burnFShares * targetMarket.totalPhysicalSupply) / targetMarket.totalSupplyShares
                : 0;
            if (physicalToReduce > targetMarket.totalPhysicalSupply) physicalToReduce = targetMarket.totalPhysicalSupply;
            targetMarket.totalPhysicalSupply -= physicalToReduce;
        }

        userPositions[user][marketId_].supplyShares -= burnFShares;
        targetMarket.totalSupplyShares -= burnFShares;
        targetMarket.totalSupplyAssets =
            targetMarket.totalSupplyAssets >= shareValue ? targetMarket.totalSupplyAssets - shareValue : 0;

        uint256 mintVShares = (shareValue * EXCHANGE_RATE_PRECISION) / variableMarket.supplyExchangeRate;
        userPositions[user][0].supplyShares += mintVShares;
        variableMarket.totalSupplyShares += mintVShares;
        variableMarket.totalSupplyAssets += shareValue;
        variableMarket.totalPhysicalSupply += shareValue;

        // Divergence 2 — rate refresh. On the loss path both rates are refreshed once, later, by
        // finalizeLossPhysical (after the physical write-down), so refreshing here would price
        // intermediate lenders off a half-applied loss.
        if (!deferPhysical) {
            if (targetMarket.totalSupplyShares > 0) {
                targetMarket.supplyExchangeRate =
                    _flooredSupplyRate(targetMarket.totalSupplyAssets, targetMarket.totalSupplyShares);
            } else {
                targetMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
            }
            if (variableMarket.totalSupplyShares > 0) {
                variableMarket.supplyExchangeRate =
                    _flooredSupplyRate(variableMarket.totalSupplyAssets, variableMarket.totalSupplyShares);
            } else {
                variableMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
            }
        }

        emit FundsDeallocated(user, marketId_, shareValue);
        return shareValue;
    }

    /// @dev Repay-path unwind: physical reduced and rates refreshed inline.
    function _unwindLender(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        address user,
        uint256 maxValue
    ) private returns (uint256) {
        return _unwindLenderCore(
            markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, user, maxValue, false
        );
    }

    function deallocateFundsFromMarket(
        mapping(uint256 => Market) storage markets,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        uint256 amount_
    ) public {
        uint256 remaining = amount_;

        // Fallback path for pre-ledger allocations: FIFO over the whole depositor queue. The
        // selection differs from the ledger path, but the per-lender unwind math is identical.
        for (uint256 i = 0; i < depositorQueue.length && remaining > 0; i++) {
            remaining -= _unwindLender(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, depositorQueue[i], remaining
            );
        }
    }

    /// @notice Remove a lender's exit-queue entry: clear the flag AND swap-and-pop the array slot.
    /// @dev Body lives here (DELEGATECALL) to keep LiquidityPoolV3 under the EIP-170 limit, same as
    ///      finalizeMarketDustCore. Popping eagerly is load-bearing, not tidiness: the enqueue in
    ///      _maybeEnqueueExit is deduped on `!inExitQueue`, so clearing only the flag — the previous
    ///      behaviour — re-armed that guard while leaving the address in place, letting one LP append
    ///      an entry per exposure toggle, permissionlessly and without bound. Both settlement walks
    ///      below are uncapped and VaultManager requires both to succeed, so a bloated queue made
    ///      fixed-market repay and liquidation settlement revert out-of-gas, leaving underwater
    ///      positions unliquidatable. Deferring cleanup to those walks put unbounded work on the one
    ///      caller that cannot afford it, and none of it commits when the transaction reverts.
    /// @dev `queueIndex` is 1-BASED; 0 means untracked. Entries queued by the PRE-UPGRADE
    ///      implementation have no recorded index, so 0 must not be read as slot 0 — those are left
    ///      to the staleness pop in the walks below, or to pruneExitQueue.
    function dequeueExit(
        address[] storage exitQueue,
        mapping(address => bool) storage marketInExitQueue,
        mapping(address => uint256) storage queueIndex,
        address lender,
        uint256 marketId_
    ) external {
        marketInExitQueue[lender] = false;
        emit ExitDequeued(lender, marketId_);

        uint256 idx1 = queueIndex[lender];
        if (idx1 == 0) return; // legacy entry: flag is cleared, so it can never be unwound
        delete queueIndex[lender];

        uint256 idx = idx1 - 1;
        // Defensive: an index/array desync can only come from legacy state, never from the live
        // invariant. Bail rather than corrupt an unrelated slot.
        if (idx >= exitQueue.length || exitQueue[idx] != lender) return;

        uint256 lastIdx = exitQueue.length - 1;
        if (idx != lastIdx) {
            address moved = exitQueue[lastIdx];
            exitQueue[idx] = moved;
            queueIndex[moved] = idx1;
        }
        exitQueue.pop();
    }

    /// @notice Pop up to `maxIter` stale entries off a market's exit queue tail.
    /// @dev Recovery path for queues already inflated under the pre-upgrade implementation, where
    ///      dequeueExit cannot swap-and-pop (no recorded index). Bounded and repeatable, so a queue
    ///      too long to traverse in one settlement transaction can be ground down across several
    ///      calls — without it the only remedy would be another upgrade. Permissionless: it removes
    ///      only entries that are already unflagged or hold no shares, which is exactly what the
    ///      settlement walks would remove, so it grants no ordering influence.
    function pruneExitQueue(
        address[] storage exitQueue,
        mapping(address => bool) storage marketInExitQueue,
        mapping(address => uint256) storage queueIndex,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        uint256 marketId_,
        uint256 maxIter
    ) external returns (uint256 pruned) {
        for (uint256 i = 0; i < maxIter && exitQueue.length > 0; i++) {
            address lender = exitQueue[exitQueue.length - 1];
            // Same staleness test the walks use: unflagged, or no live shares to unwind.
            if (marketInExitQueue[lender] && userPositions[lender][marketId_].supplyShares > 0) break;
            marketInExitQueue[lender] = false;
            delete queueIndex[lender];
            exitQueue.pop();
            pruned++;
        }
    }

    /// @notice Ledger-based deallocation, independent of pool size. Drains the exit queue (opt-outs)
    ///         first, then pops the receipt stack LIFO, unwinding each lender's LIVE position, until
    ///         `amount_` is covered or `maxIter` entries are processed. Returns the uncovered
    ///         remainder: >0 with sources non-empty means it paused at the iteration cap (caller
    ///         reverts rather than deferring); >0 with sources empty means only pre-ledger
    ///         allocations remain (caller may fall back to the global walk).
    function deallocateViaLedger(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256[] storage ledger,
        address[] storage exitQueue,
        mapping(address => bool) storage marketInExitQueue,
        uint256 marketId_,
        uint256 amount_,
        uint256 maxIter
    ) external returns (uint256 remaining) {
        remaining = amount_;
        uint256 budget = maxIter == 0 ? type(uint256).max : maxIter;

        // Step 1: opt-outs first — free exit-queue lenders (newest first) by live balance.
        while (exitQueue.length > 0 && remaining > 0 && budget > 0) {
            budget--;
            address lender = exitQueue[exitQueue.length - 1];
            // Stale only when the lender holds no shares at all — a yield-only position
            // (shares > 0, locked == 0) is a live shareholder and must be unwound, not skipped.
            if (!marketInExitQueue[lender] || userPositions[lender][marketId_].supplyShares == 0) {
                marketInExitQueue[lender] = false; // stale entry
                exitQueue.pop();
                continue;
            }
            // A lender whose ENTIRE position fits within `remaining` is spent this pass — retire
            // the receipt and continue, ignoring any sub-share wei residue left by share-flooring.
            // (Popping only on supplyShares == 0 is too strict: a "full" unwind can leave ~1 wei,
            // whose next touch returns 0 and would wrongly `break`, stranding the exit-queue lenders
            // behind it.) Only STOP when a lender still holds real value but `remaining` can't cover
            // a single share — that leftover dust is reconciled at market close by finalizeMarketDust.
            uint256 posValue =
                (userPositions[lender][marketId_].supplyShares * markets[marketId_].supplyExchangeRate)
                    / EXCHANGE_RATE_PRECISION;
            bool lenderSpent = posValue <= remaining;
            uint256 unwound = _unwindLender(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, lender, remaining
            );
            remaining -= unwound;
            if (lenderSpent) {
                marketInExitQueue[lender] = false;
                exitQueue.pop();
            } else if (unwound == 0) {
                break;
            }
        }

        // Step 2: pop the ledger LIFO (newest receipts first).
        while (ledger.length > 0 && remaining > 0 && budget > 0) {
            budget--;
            (address lender, uint256 receiptPrincipal) = _unpackReceipt(ledger[ledger.length - 1]);
            // Stale: an exit-queue lender is handled in Step 1, and live==0 means already unwound.
            // Stale only when the lender holds no shares at all — a yield-only position
            // (shares > 0, locked == 0) is a live shareholder and must be unwound, not skipped.
            if (marketInExitQueue[lender] || userPositions[lender][marketId_].supplyShares == 0) {
                ledger.pop();
                continue;
            }
            // Spent-lender vs dust-remainder: retire the receipt when the lender's whole position
            // fits within `remaining` (fully unwound this pass, ignoring sub-share wei residue),
            // else STOP when they still hold real value but `remaining` can't cover a share. Popping
            // only on supplyShares == 0 would leave a ~1-wei "full" unwind unpopped, break on its
            // next touch, and drop the rest of the deallocation to the O(pool) global fallback.
            uint256 posValue =
                (userPositions[lender][marketId_].supplyShares * markets[marketId_].supplyExchangeRate)
                    / EXCHANGE_RATE_PRECISION;
            bool lenderSpent = posValue <= remaining;
            // Snapshot locked so we can read back the principal this unwind actually released — the
            // live aggregate stays the source of truth; the receipt principal is only a self-cleaning
            // running tally derived from it.
            uint256 lockedBefore = userLockedAllocation[lender][marketId_];
            uint256 unwound = _unwindLender(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, lender, remaining
            );
            remaining -= unwound;
            if (lenderSpent) {
                ledger.pop();
            } else {
                // Partial: the lender still holds real value, so keep them on the stack — but draw the
                // TOP receipt down by the principal just released so repeated partial repays self-clean
                // the ledger instead of carrying full-value duplicate receipts until finalizeMarketDust.
                // Retire it once its principal is exhausted; over-counting left by a swap is still
                // reconciled lazily by the supplyShares == 0 pop above.
                uint256 principalUnlock = lockedBefore - userLockedAllocation[lender][marketId_];
                if (principalUnlock >= receiptPrincipal) {
                    ledger.pop();
                } else if (unwound == 0) {
                    break;
                } else {
                    ledger[ledger.length - 1] = _packReceipt(lender, receiptPrincipal - principalUnlock);
                }
            }
        }
    }

    /// @dev Loss-path unwind: identical share math to the repay path (P&L is already priced into
    ///      supplyExchangeRate), but target physical and the rate refresh are DEFERRED to
    ///      finalizeLossPhysical, which applies the precise write-down exactly once.
    function _unwindLenderLossy(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        address user,
        uint256 maxValue
    ) private returns (uint256) {
        return _unwindLenderCore(
            markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, user, maxValue, true
        );
    }

    /// @dev One-time finalization for the loss path: remove the loss-adjusted principal from the
    ///      target market's physical supply and refresh both exchange rates.
    function finalizeLossPhysical(
        mapping(uint256 => Market) storage markets,
        uint256 marketId_,
        uint256 physicalToReduce_
    ) external {
        Market storage targetMarket = markets[marketId_];
        Market storage variableMarket = markets[0];

        if (targetMarket.totalPhysicalSupply >= physicalToReduce_) {
            targetMarket.totalPhysicalSupply -= physicalToReduce_;
        } else {
            targetMarket.totalPhysicalSupply = 0;
        }

        if (targetMarket.totalSupplyShares > 0) {
            targetMarket.supplyExchangeRate =
                _flooredSupplyRate(targetMarket.totalSupplyAssets, targetMarket.totalSupplyShares);
        } else {
            targetMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }
        if (variableMarket.totalSupplyShares > 0) {
            variableMarket.supplyExchangeRate =
                _flooredSupplyRate(variableMarket.totalSupplyAssets, variableMarket.totalSupplyShares);
        } else {
            variableMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }
    }

    /// @notice Loss-path ledger walk — structurally identical to deallocateViaLedger (opt-outs
    ///         first, then LIFO receipts, fully unbounded), but unwinds via _unwindLenderLossy
    ///         since the loss is already baked into the exchange rate (LIFO ordering is neutral —
    ///         every lender already absorbed it). Returns the uncovered remainder: >0 means only
    ///         pre-ledger allocations remain (caller falls back via proportionalDeallocateFundsFromMarket).
    function proportionalDeallocateViaLedger(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256[] storage ledger,
        address[] storage exitQueue,
        mapping(address => bool) storage marketInExitQueue,
        uint256 marketId_,
        uint256 amount_,
        uint256 maxIter
    ) external returns (uint256 remaining) {
        remaining = amount_;
        // Mirrors deallocateViaLedger: 0 means uncapped. A non-zero cap bounds the WHOLE call
        // (exit-queue pass plus ledger pass), so one settlement can never iterate without a ceiling.
        uint256 budget = maxIter == 0 ? type(uint256).max : maxIter;

        // Opt-outs first.
        while (exitQueue.length > 0 && remaining > 0 && budget > 0) {
            budget--;
            address lender = exitQueue[exitQueue.length - 1];
            // Stale only when the lender holds no shares at all — a yield-only position
            // (shares > 0, locked == 0) is a live shareholder and must be unwound, not skipped.
            if (!marketInExitQueue[lender] || userPositions[lender][marketId_].supplyShares == 0) {
                marketInExitQueue[lender] = false;
                exitQueue.pop();
                continue;
            }
            // Spent-lender vs dust-remainder (mirrors the repay path): retire the receipt when the
            // lender's whole position fits within `remaining` — ignoring the sub-share wei residue a
            // "full" unwind leaves — else stop only when a live lender's real value can't be covered
            // by a sub-share `remaining`. Prevents stranding queued lenders behind a spent-but-dusty one.
            uint256 posValue =
                (userPositions[lender][marketId_].supplyShares * markets[marketId_].supplyExchangeRate)
                    / EXCHANGE_RATE_PRECISION;
            bool lenderSpent = posValue <= remaining;
            uint256 u = _unwindLenderLossy(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, lender, remaining
            );
            remaining -= u;
            if (lenderSpent) {
                marketInExitQueue[lender] = false;
                exitQueue.pop();
            } else if (u == 0) {
                break;
            }
        }

        // Then LIFO receipts.
        while (ledger.length > 0 && remaining > 0 && budget > 0) {
            budget--;
            (address lender, uint256 receiptPrincipal) = _unpackReceipt(ledger[ledger.length - 1]);
            // Stale only when the lender holds no shares at all — a yield-only position
            // (shares > 0, locked == 0) is a live shareholder and must be unwound, not skipped.
            if (marketInExitQueue[lender] || userPositions[lender][marketId_].supplyShares == 0) {
                ledger.pop();
                continue;
            }
            // Spent-lender vs dust-remainder (mirrors the repay path): retire the receipt when the
            // lender's whole position fits within `remaining` — ignoring the sub-share wei residue a
            // "full" unwind leaves — else stop only when a live lender's real value can't be covered
            // by a sub-share `remaining`. Prevents dropping the remainder to the O(pool) global walk.
            uint256 posValue =
                (userPositions[lender][marketId_].supplyShares * markets[marketId_].supplyExchangeRate)
                    / EXCHANGE_RATE_PRECISION;
            bool lenderSpent = posValue <= remaining;
            uint256 lockedBefore = userLockedAllocation[lender][marketId_];
            uint256 u = _unwindLenderLossy(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, lender, remaining
            );
            remaining -= u;
            if (lenderSpent) {
                ledger.pop();
            } else {
                // Partial: draw the top receipt down by the principal just released so the ledger
                // self-cleans across repeated partial loss-deallocations (mirrors the repay path).
                uint256 principalUnlock = lockedBefore - userLockedAllocation[lender][marketId_];
                if (principalUnlock >= receiptPrincipal) {
                    ledger.pop();
                } else if (u == 0) {
                    break;
                } else {
                    ledger[ledger.length - 1] = _packReceipt(lender, receiptPrincipal - principalUnlock);
                }
            }
        }
    }

    /// @notice Loss-path fallback for pre-ledger allocations — FIFO over the global depositor
    ///         queue, mirroring deallocateFundsFromMarket but unwinding via _unwindLenderLossy.
    function proportionalDeallocateFundsFromMarket(
        mapping(uint256 => Market) storage markets,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        uint256 amount_
    ) external {
        uint256 remaining = amount_;
        for (uint256 i = 0; i < depositorQueue.length && remaining > 0; i++) {
            remaining -= _unwindLenderLossy(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, depositorQueue[i], remaining
            );
        }
    }

    /// @dev Migrate a single lender's full fixed-market position back to market 0 at `cachedRate`,
    ///      crediting proportional physical supply. No-ops (returns zeros) if the lender already
    ///      has zero shares — safe to call redundantly for the same lender.
    function _migrateLenderShares(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        address user,
        uint256 cachedRate
    ) private returns (uint256 userShares, uint256 physicalCredit) {
        Market storage market = markets[marketId_];
        Market storage variableMarket = markets[0];

        userShares = userPositions[user][marketId_].supplyShares;
        if (userShares == 0) return (0, 0);

        uint256 shareValue = (userShares * cachedRate) / EXCHANGE_RATE_PRECISION;
        userPositions[user][marketId_].supplyShares = 0;
        userActualAllocation[user][marketId_] = 0;
        userLockedAllocation[user][marketId_] = 0;
        userActualAllocation[user][0] += shareValue;

        uint256 mintVShares = variableMarket.supplyExchangeRate > 0
            ? (shareValue * EXCHANGE_RATE_PRECISION) / variableMarket.supplyExchangeRate
            : shareValue;
        userPositions[user][0].supplyShares += mintVShares;
        variableMarket.totalSupplyShares += mintVShares;
        variableMarket.totalSupplyAssets += shareValue;

        physicalCredit = market.totalSupplyShares > 0 ? (userShares * market.totalPhysicalSupply) / market.totalSupplyShares : 0;
        variableMarket.totalPhysicalSupply += physicalCredit;

        emit FundsDeallocated(user, marketId_, shareValue);
    }

    /// @notice Migrate every ledger/exit-queue-tracked lender's fixed-market position back to
    ///         market 0 in one pass, fully draining and clearing both structures. Bounded by this
    ///         market's own ledger/exit-queue size rather than the global depositor count, so a
    ///         dust-Sybil-inflated depositorQueue can't block it. Used by finalizeMarketDust
    ///         before it falls back to the (unbounded) global scan for any pre-ledger remainder.
    function migrateMarketToVariableViaLedger(
        mapping(uint256 => Market) storage markets,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256[] storage ledger,
        address[] storage exitQueue,
        mapping(address => bool) storage marketInExitQueue,
        uint256 marketId_,
        uint256 cachedRate
    ) public returns (uint256 sharesMigrated, uint256 physicalCredited) {
        while (exitQueue.length > 0) {
            address lender = exitQueue[exitQueue.length - 1];
            exitQueue.pop();
            marketInExitQueue[lender] = false;
            (uint256 userShares, uint256 physicalCredit) = _migrateLenderShares(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, lender, cachedRate
            );
            sharesMigrated += userShares;
            physicalCredited += physicalCredit;
        }

        while (ledger.length > 0) {
            (address lender,) = _unpackReceipt(ledger[ledger.length - 1]);
            ledger.pop();
            (uint256 userShares, uint256 physicalCredit) = _migrateLenderShares(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, lender, cachedRate
            );
            sharesMigrated += userShares;
            physicalCredited += physicalCredit;
        }
    }

    /// @dev Core dust-cleanup body of LiquidityPoolV3.finalizeMarketDust, extracted to keep the pool
    ///      under the EIP-170 limit. The pool wrapper must have already: authorized the caller,
    ///      bounds-checked marketId_, accrued interest for marketId_ and market 0, and confirmed no
    ///      active position debt remains in the market. Logic is a verbatim move of the prior body.
    function finalizeMarketDustCore(
        mapping(uint256 => Market) storage markets,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256[] storage ledger,
        address[] storage exitQueue,
        mapping(address => bool) storage marketInExitQueue,
        uint256 marketId_
    ) external {
        Market storage market = markets[marketId_];

        if (
            market.totalBorrowAssets <= BORROW_DUST_THRESHOLD && market.totalBorrowShares <= BORROW_DUST_THRESHOLD
                && market.totalPhysicalBorrow <= BORROW_DUST_THRESHOLD
        ) {
            uint256 deallocatePrincipal = market.totalPhysicalBorrow;
            market.totalBorrowAssets = 0;
            market.totalBorrowShares = 0;
            market.totalPhysicalBorrow = 0;
            market.borrowExchangeRate = EXCHANGE_RATE_PRECISION;

            if (marketId_ != 0 && deallocatePrincipal > 0) {
                deallocateFundsFromMarket(
                    markets, depositorQueue, userPositions, userActualAllocation, userLockedAllocation, marketId_, deallocatePrincipal
                );
            }
        }

        // If market is fully closed on borrow side, deterministically migrate remaining
        // fixed-market shares/value back to market 0 so no residual fixed state remains.
        if (
            marketId_ != 0 && market.totalBorrowAssets == 0 && market.totalBorrowShares == 0
                && market.totalPhysicalBorrow == 0 && market.totalSupplyShares > 0
        ) {
            Market storage variableMarket = markets[0];
            uint256 cachedRate = market.supplyExchangeRate > 0 ? market.supplyExchangeRate : EXCHANGE_RATE_PRECISION;

            uint256 totalPhysicalCredited = 0;

            if (market.protocolSupplyShares > 0) {
                uint256 protocolValue = (market.protocolSupplyShares * cachedRate) / EXCHANGE_RATE_PRECISION;
                if (protocolValue > 0) {
                    uint256 newVShares = variableMarket.totalSupplyAssets > 0
                        ? (protocolValue * variableMarket.totalSupplyShares) / variableMarket.totalSupplyAssets
                        : protocolValue;
                    variableMarket.protocolSupplyShares += newVShares;
                    variableMarket.totalSupplyShares += newVShares;
                    variableMarket.totalSupplyAssets += protocolValue;
                    uint256 protocolPhysical = market.totalSupplyShares > 0
                        ? (market.protocolSupplyShares * market.totalPhysicalSupply) / market.totalSupplyShares
                        : 0;
                    variableMarket.totalPhysicalSupply += protocolPhysical;
                    totalPhysicalCredited += protocolPhysical;
                }
            }

            uint256 lenderSharesTotal = market.totalSupplyShares - market.protocolSupplyShares;
            (uint256 sharesMigrated, uint256 physicalCreditedViaLedger) = migrateMarketToVariableViaLedger(
                markets, userPositions, userActualAllocation, userLockedAllocation, ledger, exitQueue, marketInExitQueue, marketId_, cachedRate
            );
            totalPhysicalCredited += physicalCreditedViaLedger;

            if (sharesMigrated < lenderSharesTotal) {
                totalPhysicalCredited += migrateMarketToVariableFallback(
                    markets, depositorQueue, userPositions, userActualAllocation, userLockedAllocation, marketId_, cachedRate
                );
            }

            if (market.totalPhysicalSupply > totalPhysicalCredited) {
                uint256 remaining = market.totalPhysicalSupply - totalPhysicalCredited;
                uint256 dustShares = variableMarket.totalSupplyAssets > 0
                    ? (remaining * variableMarket.totalSupplyShares) / variableMarket.totalSupplyAssets
                    : remaining;
                variableMarket.protocolSupplyShares += dustShares;
                variableMarket.totalSupplyShares += dustShares;
                variableMarket.totalSupplyAssets += remaining;
                variableMarket.totalPhysicalSupply += remaining;
            }

            market.totalSupplyShares = 0;
            market.protocolSupplyShares = 0;
            market.totalSupplyAssets = 0;
            market.totalPhysicalSupply = 0;
            market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;

            if (variableMarket.totalSupplyShares > 0) {
                variableMarket.supplyExchangeRate =
                    _flooredSupplyRate(variableMarket.totalSupplyAssets, variableMarket.totalSupplyShares);
            }
        } else if (
            marketId_ != 0 && market.totalBorrowAssets == 0 && market.totalBorrowShares == 0
                && market.totalPhysicalBorrow == 0 && market.totalSupplyShares <= SUPPLY_DUST_THRESHOLD
                && market.totalSupplyAssets <= SUPPLY_DUST_THRESHOLD
                && market.totalPhysicalSupply <= SUPPLY_DUST_THRESHOLD
        ) {
            // Tiny tail cleanup path if market was already near-zero.
            if (market.protocolSupplyShares > 0) {
                uint256 dustRate = market.supplyExchangeRate > 0 ? market.supplyExchangeRate : EXCHANGE_RATE_PRECISION;
                uint256 protocolValue = (market.protocolSupplyShares * dustRate) / EXCHANGE_RATE_PRECISION;
                if (protocolValue > 0) {
                    Market storage variableMarketDust = markets[0];
                    uint256 newVShares = variableMarketDust.totalSupplyAssets > 0
                        ? (protocolValue * variableMarketDust.totalSupplyShares) / variableMarketDust.totalSupplyAssets
                        : protocolValue;
                    variableMarketDust.protocolSupplyShares += newVShares;
                    variableMarketDust.totalSupplyShares += newVShares;
                    variableMarketDust.totalSupplyAssets += protocolValue;
                    variableMarketDust.totalPhysicalSupply += protocolValue;
                }
            }
            market.totalSupplyShares = 0;
            market.protocolSupplyShares = 0;
            market.totalSupplyAssets = 0;
            market.totalPhysicalSupply = 0;
            market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }
    }

    /// @dev Migrates `tokenAmount` worth of protocol shares from a fixed market to market 0.
    ///      Called on each repayment proportional to protocol's share of the market.
    /// @return physicalReduced The PRINCIPAL-only physical actually stripped from the fixed market —
    ///         callers on the loss path use it to write down exactly the remaining principal.
    function migrateProtocolSharesToVariable(
        mapping(uint256 => Market) storage markets,
        uint256 marketId_,
        uint256 tokenAmount_
    ) external returns (uint256 physicalReduced) {
        Market storage fixedMarket = markets[marketId_];
        Market storage variableMarket = markets[0];

        if (fixedMarket.protocolSupplyShares == 0 || fixedMarket.totalSupplyShares == 0) return 0;

        // Shares to burn in fixed market (tokenAmount → shares at current rate)
        uint256 sharesToBurn = fixedMarket.totalSupplyAssets > 0
            ? (tokenAmount_ * fixedMarket.totalSupplyShares) / fixedMarket.totalSupplyAssets
            : 0;
        if (sharesToBurn > fixedMarket.protocolSupplyShares) sharesToBurn = fixedMarket.protocolSupplyShares;
        if (sharesToBurn == 0) return 0;

        // VALUE to migrate (assets/shares → principal + accrued interest). This is what moves on the
        // ASSETS side and into market 0; it may legitimately exceed physical, so it is NOT capped at
        // totalPhysicalSupply.
        uint256 tokenAmount = (sharesToBurn * fixedMarket.totalSupplyAssets) / fixedMarket.totalSupplyShares;
        if (tokenAmount == 0) return 0;

        // PHYSICAL (principal-only) reduction. totalPhysicalSupply tracks principal, not value, so it
        // must shrink by the PRINCIPAL slice of the burned shares (physical/shares) — NOT by
        // `tokenAmount` (value). Reducing it by the value over-removed the protocol's accrued-interest
        // slice on every repay/liquidation, drifting totalPhysicalSupply below totalPhysicalBorrow and
        // bricking new fixed-market borrows. Mirrors the LP path in _unwindLenderCore; computed pre-burn.
        physicalReduced = (sharesToBurn * fixedMarket.totalPhysicalSupply) / fixedMarket.totalSupplyShares;
        if (physicalReduced > fixedMarket.totalPhysicalSupply) physicalReduced = fixedMarket.totalPhysicalSupply;

        // Burn from fixed market
        fixedMarket.protocolSupplyShares -= sharesToBurn;
        fixedMarket.totalSupplyShares -= sharesToBurn;
        fixedMarket.totalSupplyAssets =
            fixedMarket.totalSupplyAssets >= tokenAmount ? fixedMarket.totalSupplyAssets - tokenAmount : 0;
        fixedMarket.totalPhysicalSupply =
            fixedMarket.totalPhysicalSupply >= physicalReduced ? fixedMarket.totalPhysicalSupply - physicalReduced : 0;
        if (fixedMarket.totalSupplyShares > 0) {
            fixedMarket.supplyExchangeRate =
                _flooredSupplyRate(fixedMarket.totalSupplyAssets, fixedMarket.totalSupplyShares);
        }

        // Mint protocol shares in market 0 at current variable rate
        uint256 newShares = variableMarket.totalSupplyAssets > 0
            ? (tokenAmount * variableMarket.totalSupplyShares) / variableMarket.totalSupplyAssets
            : tokenAmount;
        variableMarket.protocolSupplyShares += newShares;
        variableMarket.totalSupplyShares += newShares;
        variableMarket.totalSupplyAssets += tokenAmount;
        variableMarket.totalPhysicalSupply += tokenAmount;
        if (variableMarket.totalSupplyShares > 0) {
            variableMarket.supplyExchangeRate =
                _flooredSupplyRate(variableMarket.totalSupplyAssets, variableMarket.totalSupplyShares);
        }
    }

    /// @notice Fallback for pre-ledger lenders in finalizeMarketDust — FIFO over the global
    ///         depositor queue, mirroring deallocateFundsFromMarket but for a full migration
    ///         (no target amount) via _migrateLenderShares.
    function migrateMarketToVariableFallback(
        mapping(uint256 => Market) storage markets,
        address[] storage depositorQueue,
        mapping(address => mapping(uint256 => UserPosition)) storage userPositions,
        mapping(address => mapping(uint256 => uint256)) storage userActualAllocation,
        mapping(address => mapping(uint256 => uint256)) storage userLockedAllocation,
        uint256 marketId_,
        uint256 cachedRate
    ) public returns (uint256 physicalCredited) {
        uint256 queueLen = depositorQueue.length;
        for (uint256 i = 0; i < queueLen; i++) {
            (, uint256 physicalCredit) = _migrateLenderShares(
                markets, userPositions, userActualAllocation, userLockedAllocation, marketId_, depositorQueue[i], cachedRate
            );
            physicalCredited += physicalCredit;
        }
    }
}

