// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {IMarketProvider} from "../interfaces/IMarketProvider.sol";

// ============================================
// SHARED STORAGE TYPES
// ============================================
// These structs were previously declared inside LiquidityPoolV3. They are moved to
// this shared file so both the pool and PoolLogicLib can reference them without a
// circular import. Field ORDER and TYPES are preserved verbatim — the pool's storage
// layout is unchanged (struct definitions do not occupy storage; only field order
// within a struct matters, and that is identical to the prior in-contract definition).

/// @notice Market configuration and state (aligned with simulator)
struct Market {
    IMarketProvider provider; // Rate provider contract
    address token; // Stablecoin address
    bool active; // Market active status

    // Share-based accounting (both variable and fixed markets)
    uint256 totalSupplyShares; // Total supply shares issued to LPs
    uint256 totalSupplyAssets; // Total claimable by LPs (increases with interest)
    uint256 totalPhysicalSupply; // Actual USDC in pool

    uint256 totalBorrowShares; // Total borrow shares issued to borrowers
    uint256 totalBorrowAssets; // Total owed by borrowers (increases with interest)
    uint256 totalPhysicalBorrow; // Original principal borrowed

    // Exchange rates (Morpho-style)
    uint256 supplyExchangeRate; // totalSupplyAssets / totalSupplyShares (scaled by 1e18)
    uint256 borrowExchangeRate; // totalBorrowAssets / totalBorrowShares (scaled by 1e18)

    // Protocol earnings (legacy token-based tracking — deprecated, use protocolSupplyShares)
    uint256 protocolEarnings; // Deprecated: use protocolSupplyShares
    uint256 protocolEarningsAvailable; // Deprecated: use protocolSupplyShares

    // Market parameters
    uint256 originationFeeBps; // Origination fee in basis points
    uint256 reserveRateBps; // Protocol reserve rate (e.g., 2000 = 20%); should match provider.getReserveRate()
    uint256 maxLtvBps; // Max loan-to-value ratio
    uint256 liquidationThresholdBps; // Liquidation threshold

    // Interest accrual tracking
    uint256 lastAccrueTime; // Last interest accrual timestamp

    // Protocol supply shares (Morpho-style fee shares minted to surgeWallet on each accrual)
    // Appended at end to preserve storage slot layout for upgradeable contract
    uint256 protocolSupplyShares;
}

/// @notice User position in a specific market
struct UserPosition {
    uint256 supplyShares; // Supply shares owned in this market
    uint256 borrowShares; // Borrow shares owned in this market
}

struct DepositorPosition {
    uint256 totalDepositedAssets;
    bool inQueue;
}

struct WithdrawRequest {
    address user;
    // Packed into the same slot as `user` (address 20B + bool 1B <= 32B), so the struct stays
    // 3 slots and the dynamic-array element stride is unchanged — upgrade-safe. Any request
    // stored before this field existed reads back as false (the slot's high bytes were zero),
    // i.e. it is treated as a plain fixed-amount request exactly as it was queued.
    bool isFullExit;
    uint256 amount;
    uint256 timestamp;
}

