// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

/// @title TaylorMath
/// @notice Shared fixed-point Taylor-series math helpers.
library TaylorMath {
    uint256 internal constant WAD = 1e18;

    /// @notice Approximates `e^(rate * timeElapsed) - 1` using the first three Taylor terms.
    /// @dev Matches Morpho's `MathLib.wTaylorCompounded` shape. `rate` must be WAD-scaled per second.
    function wTaylorCompounded(uint256 rate, uint256 timeElapsed) internal pure returns (uint256) {
        uint256 firstTerm = rate * timeElapsed;
        uint256 secondTerm = (firstTerm * firstTerm) / (2 * WAD);
        uint256 thirdTerm = (secondTerm * firstTerm) / (3 * WAD);
        return firstTerm + secondTerm + thirdTerm;
    }
}

