// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IMarketProvider} from "./interfaces/IMarketProvider.sol";
import {TaylorMath} from "./libraries/TaylorMath.sol";
import {PoolLogicLib} from "./libraries/PoolLogicLib.sol";
import {Market, UserPosition, DepositorPosition, WithdrawRequest} from "./libraries/PoolTypes.sol";

/// @notice Minimal view surface of a clock-driven (adaptive) provider, used by setMarketProvider to
///         confirm market 0's provider actually advanced its rate clock on install. Deliberately not
///         added to IMarketProvider so fixed providers need not implement it — a fixed provider on
///         market 0 simply fails this check.
interface IClockedProvider {
    function lastRateUpdate() external view returns (uint256);
}

/**
 * @title LiquidityPoolV3
 * @notice Multi-market liquidity pool with share-based accounting (aligned with simulator)
 * @dev Implements uniform share-based accounting for all markets (variable and fixed)
 */
contract LiquidityPoolV3 is Initializable, UUPSUpgradeable, OwnableUpgradeable, PausableUpgradeable {
    using SafeERC20 for IERC20;

    // ============================================
    // STRUCTS
    // ============================================
    // Market, UserPosition, DepositorPosition and WithdrawRequest are defined in
    // libraries/PoolTypes.sol (imported above) so PoolLogicLib can share them without a
    // circular import. Field order/types are identical to the prior in-contract
    // definitions, so the storage layout is unchanged.

    // ============================================
    // STATE VARIABLES
    // ============================================

    /// @notice Markets mapping
    mapping(uint256 => Market) public markets;
    uint256 public marketCount;

    /// @notice User positions per market
    mapping(address => mapping(uint256 => UserPosition)) public userPositions;

    /// @notice Global protocol reserves per token
    mapping(address => uint256) public protocolReserves;

    /// @notice Surge wallet address (receives protocol fees)
    address public surgeWallet;

    /// @notice VaultManager address (authorized to call borrow/repay)
    address public vaultManager;

    /// @notice Market physical supply resync status
    mapping(uint256 => bool) public marketPhysicalResynced;

    mapping(address => mapping(uint256 => uint256)) public userExposureBps;
    mapping(address => mapping(uint256 => uint256)) public userActualAllocation;
    mapping(address => mapping(uint256 => uint256)) public userLockedAllocation;
    mapping(address => DepositorPosition) public depositorPositions;
    address[] public depositorQueue;
    mapping(address => uint256) public depositorIndex;

    /// @notice Pause manager address (can pause and unpause)
    address public pauseManager;

    /// @notice Pending pause manager address for two-step transfer
    address public pendingPauseManager;

    /// @notice Withdraw queue for locked markets (marketId -> queue)
    /// @dev Appended at end for storage layout optimization in upgradeable contract
    mapping(uint256 => WithdrawRequest[]) public withdrawQueue;
    /// @notice User's pending withdraw amount per market
    /// @dev Appended at end for storage layout optimization in upgradeable contract
    mapping(address => mapping(uint256 => uint256)) public pendingWithdrawAmount;

    /// @notice Operational admin role — distinct from `owner`. Authorized to process the
    ///         withdraw queue. Set by the owner via setAdmin.
    /// @dev Appended at end to preserve storage layout for the upgradeable contract.
    address public admin;

    // ============================================
    // ALLOCATION LEDGER (appended at end — upgrade-safe)
    // ============================================

    /// @notice Per-market stack of allocation receipts, newest on top. Each entry packs the
    ///         drawn lender (low 20 bytes) and the drawn principal as uint96 (high 12 bytes).
    ///         Receipts are ORDERING HINTS; the source of truth for how much a lender can be
    ///         unwound is always their live locked balance. Popped LIFO on deallocation.
    mapping(uint256 => uint256[]) internal allocationLedger;

    /// @notice Per-market queue of lenders who opted out (set exposure 0 while allocated) and
    ///         want their funds returned to market 0. Drained before any ledger pops.
    mapping(uint256 => address[]) internal marketExitQueue;
    /// @notice Whether a lender currently sits in a market's exit queue (dedup + O(1) skip).
    mapping(uint256 => mapping(address => bool)) internal inExitQueue;

    /// @notice 1-BASED position of a lender's live entry in marketExitQueue[marketId]; 0 means no
    ///         tracked position. Lets a re-opt-in swap-and-pop the actual array slot instead of only
    ///         clearing inExitQueue, which left the entry behind and re-armed the push guard —
    ///         letting one LP grow the array without bound by toggling exposure.
    /// @dev Appended at end — upgrade-safe. 1-based so 0 doubles as "untracked": entries queued by
    ///      the PRE-UPGRADE implementation have no recorded index, and 0 must not be mistaken for
    ///      slot 0. Those legacy entries are left to the walks' existing staleness pop.
    ///      Safe against the library walks because every exit-queue pop there is a TAIL pop
    ///      (PoolLogicLib deallocateViaLedger / proportionalDeallocateViaLedger /
    ///      migrateMarketToVariableViaLedger) which never relocates surviving entries, and each
    ///      clears inExitQueue — so a lender the library removed can never reach _dequeueExit.
    mapping(uint256 => mapping(address => uint256)) internal exitQueueIndex;

    /// @notice Per-call iteration ceiling for the ledger deallocation walks. 0 == uncapped (the
    ///         deployed default, safe while the LP set per fixed market is small).
    /// @dev Appended at end — upgrade-safe. Setting this NON-ZERO is only safe once settlement can
    ///      finish across calls: a capped walk returns an uncovered remainder, and until a carry
    ///      path exists that remainder has nowhere legitimate to go. _deallocate/_deallocateLoss
    ///      therefore revert DeallocationIncomplete rather than fall through to the
    ///      O(depositorQueue) scan, which is the dust-Sybil vector this cap exists to avoid.
    uint256 public deallocMaxIter;


    // ============================================
    // CONSTANTS
    // ============================================

    uint256 private constant EXCHANGE_RATE_PRECISION = 1e18;
    uint256 private constant BPS_DENOMINATOR = 10000;
    uint256 private constant SECONDS_PER_YEAR = 365 days;
    uint256 private constant BORROW_DUST_THRESHOLD = 10000; // token base units (e.g. 0.01 USDC for 6 decimals)
    uint256 private constant SUPPLY_DUST_THRESHOLD = 10000; // token/share base units (e.g. 0.01 USDC for 6 decimals)

    // ============================================
    // EVENTS
    // ============================================

    event MarketCreated(uint256 indexed marketId, address indexed provider, address indexed token);
    event Deposit(address indexed user, uint256 indexed marketId, uint256 amount, uint256 shares);
    event Withdraw(address indexed user, uint256 indexed marketId, uint256 amount, uint256 shares);
    event WithdrawAll(address indexed user, uint256 indexed marketId, uint256 amount, uint256 shares);
    event WithdrawQueued(address indexed user, uint256 indexed marketId, uint256 amount, bool isFullExit);
    event WithdrawProcessed(address indexed user, uint256 indexed marketId, uint256 amount, address[] replacementLPs);
    event WithdrawCancelled(address indexed user, uint256 indexed marketId, uint256 amount);
    event Borrow(address indexed borrower, uint256 indexed marketId, uint256 amount, uint256 shares);
    event Repay(address indexed borrower, uint256 indexed marketId, uint256 amount, uint256 shares);
    event LiquidationRepay(uint256 indexed marketId, uint256 bidAmount, uint256 borrowedValue, int256 pnl);
    event InterestAccrued(uint256 indexed marketId, uint256 borrowInterest, uint256 protocolCut, uint256 lenderCut);
    event ProtocolReservesClaimed(address indexed token, uint256 amount);
    event ExposureUpdated(address indexed user, uint256 indexed marketId, uint256 exposureBps);
    event FundsAllocated(address indexed user, uint256 indexed marketId, uint256 amount);
    event FundsDeallocated(address indexed user, uint256 indexed marketId, uint256 amount);
    event MarketStatusChanged(uint256 indexed marketId, bool active);
    event MarketProviderUpdated(uint256 indexed marketId, address indexed oldProvider, address indexed newProvider);
    event MarketReserveRateUpdated(uint256 indexed marketId, uint256 oldReserveRateBps, uint256 newReserveRateBps);
    event MarketMaxLTVUpdated(uint256 indexed marketId, uint256 oldMaxLtvBps, uint256 newMaxLtvBps);
    event MarketLiquidationThresholdUpdated(
        uint256 indexed marketId, uint256 oldLiquidationThresholdBps, uint256 newLiquidationThresholdBps
    );
    event ProtocolSharesMinted(uint256 indexed marketId, uint256 shares, uint256 feeAccrued);
    event ProtocolSharesWithdrawn(uint256 indexed marketId, uint256 shares, uint256 tokenAmount);
    event SurgeWalletUpdated(address indexed oldSurgeWallet, address indexed newSurgeWallet);
    event VaultManagerUpdated(address indexed oldVaultManager, address indexed newVaultManager);
    event AdminUpdated(address indexed oldAdmin, address indexed newAdmin);
    event ExitQueued(address indexed lender, uint256 indexed marketId);
    event MaxIterUpdated(uint256 oldMaxIter, uint256 newMaxIter);
    event ExitDequeued(address indexed lender, uint256 indexed marketId);
    event PauseManagerProposed(address indexed currentPauseManager, address indexed proposedPauseManager);
    event PauseManagerAccepted(address indexed previousPauseManager, address indexed newPauseManager);

    // ============================================
    // ERRORS
    // ============================================

    error Unauthorized();
    error InvalidMarket();
    error MarketNotActive();
    error InvalidAmount();
    error InvalidAddress();
    error InsufficientLiquidity();
    error InsufficientShares();
    error TokenNotSupported();
    error InvalidExposure();
    error InsufficientExposure();
    error ProviderAlreadyInUse();
    error ReentrancyGuardReentrantCall();
    error WithdrawAlreadyQueued();
    error DeallocationIncomplete();

    // ============================================
    // MODIFIERS
    // ============================================

    /// @dev Reentrancy lock stored at a custom assembly slot — zero sequential storage slots used.
    /// Slot: keccak256("surge.storage.ReentrancyGuard") — version-independent, no OZ dependency.
    modifier nonReentrant() {
        bytes32 slot = keccak256("surge.storage.ReentrancyGuard");
        uint256 status;
        assembly { status := sload(slot) }
        if (status == 2) revert ReentrancyGuardReentrantCall();
        assembly { sstore(slot, 2) }
        _;
        assembly { sstore(slot, 1) }
    }

    modifier onlyVaultManager() {
        if (msg.sender != vaultManager) revert Unauthorized();
        _;
    }

    modifier onlyPauseManager() {
        if (msg.sender != pauseManager) revert Unauthorized();
        _;
    }

    modifier onlyAdmin() {
        if (msg.sender != admin) revert Unauthorized();
        _;
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // ============================================
    // INITIALIZATION
    // ============================================

    function initialize(address surgeWallet_, address vaultManager_) external initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();

        if (surgeWallet_ == address(0)) revert InvalidAmount();
        if (vaultManager_ == address(0)) revert InvalidAmount();

        surgeWallet = surgeWallet_;
        vaultManager = vaultManager_;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============================================
    // MARKET MANAGEMENT
    // ============================================

    /// @notice Create a new market
    function createMarket(
        address provider_,
        address token_,
        uint256 originationFeeBps_,
        uint256 reserveRateBps_,
        uint256 maxLtvBps_,
        uint256 liquidationThresholdBps_
    ) external onlyOwner returns (uint256 marketId) {
        if (provider_ == address(0)) revert InvalidAmount();
        if (token_ == address(0)) revert InvalidAmount();
        // Collateral-ratio math assumes a 6-decimal stablecoin; enforce it at market creation.
        if (IERC20Metadata(token_).decimals() != 6) revert TokenNotSupported();
        if (maxLtvBps_ == 0 || maxLtvBps_ > BPS_DENOMINATOR) revert InvalidAmount();
        if (liquidationThresholdBps_ == 0 || liquidationThresholdBps_ > BPS_DENOMINATOR) revert InvalidAmount();
        if (maxLtvBps_ >= liquidationThresholdBps_) revert InvalidAmount();
        if (reserveRateBps_ > BPS_DENOMINATOR) revert InvalidAmount();

        // Check if provider is already bound to another market, active or not
        // (prevents rateAtTarget cross-contamination via deactivate/reassign/reactivate)
        for (uint256 i = 0; i < marketCount; i++) {
            if (address(markets[i].provider) == provider_) {
                revert ProviderAlreadyInUse();
            }
        }

        marketId = marketCount++;

        Market storage market = markets[marketId];
        market.provider = IMarketProvider(provider_);
        market.token = token_;
        market.active = true;
        market.originationFeeBps = originationFeeBps_;
        market.reserveRateBps = reserveRateBps_;
        market.maxLtvBps = maxLtvBps_;
        market.liquidationThresholdBps = liquidationThresholdBps_;
        market.lastAccrueTime = block.timestamp;

        // Initialize exchange rates to 1:1
        market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        market.borrowExchangeRate = EXCHANGE_RATE_PRECISION;

        emit MarketCreated(marketId, provider_, token_);
    }

    // ============================================
    // CORE FUNCTIONS - SUPPLY
    // ============================================

    /// @notice Deposit funds into a market (issues shares)
    function deposit(uint256 amount_) external nonReentrant whenNotPaused {
        uint256 marketId_ = 0;
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (amount_ == 0) revert InvalidAmount();

        Market storage market = markets[marketId_];
        if (!market.active) revert MarketNotActive();

        // Accrue interest before deposit
        _accrueMarketInterest(marketId_);

        // Transfer tokens from user
        IERC20(market.token).safeTransferFrom(msg.sender, address(this), amount_);

        // Calculate shares to issue
        uint256 sharesToIssue;
        if (market.totalSupplyShares == 0) {
            // First deposit: 1:1 ratio
            sharesToIssue = amount_;
        } else {
            // Calculate based on current exchange rate
            sharesToIssue = (amount_ * EXCHANGE_RATE_PRECISION) / market.supplyExchangeRate;
        }

        // Update user position
        userPositions[msg.sender][marketId_].supplyShares += sharesToIssue;

        DepositorPosition storage dp = depositorPositions[msg.sender];
        dp.totalDepositedAssets += amount_;
        if (!dp.inQueue) {
            dp.inQueue = true;
            depositorIndex[msg.sender] = depositorQueue.length;
            depositorQueue.push(msg.sender);
        }

        userActualAllocation[msg.sender][0] += amount_;

        // Update market state
        market.totalSupplyShares += sharesToIssue;
        market.totalSupplyAssets += amount_;
        market.totalPhysicalSupply += amount_;

        // Update exchange rate
        if (market.totalSupplyShares > 0) {
            market.supplyExchangeRate = _flooredSupplyRate(market.totalSupplyAssets, market.totalSupplyShares);
        } else {
            market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }

        emit Deposit(msg.sender, marketId_, amount_, sharesToIssue);
    }

    /// @notice Withdraw funds from a market (burns shares)
    function withdraw(uint256 amount_) external nonReentrant {
        if (amount_ == 0) revert InvalidAmount();

        // LP withdrawals always operate on the variable market (market 0)
        uint256 marketId_ = 0;
        Market storage market = markets[marketId_];
        UserPosition storage position = userPositions[msg.sender][marketId_];

        // Accrue interest before withdrawal
        _accrueMarketInterest(marketId_);

        // Calculate user's liquid market 0 claimable amount
        uint256 userClaimable = (position.supplyShares * market.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;
        if (amount_ > userClaimable) revert InvalidAmount();

        // Funds allocated to fixed markets are not withdrawable here; those are held as fixed-market
        // shares, not market 0 shares. To withdraw locked funds the LP calls withdrawFromMarket(marketId).

        // Note: userActualAllocation check removed to allow interest withdrawals
        // The userClaimable check above is sufficient to prevent over-withdrawal

        // Check available liquidity
        uint256 availableLiquidity = market.totalPhysicalSupply > market.totalPhysicalBorrow
            ? market.totalPhysicalSupply - market.totalPhysicalBorrow
            : 0;
        if (amount_ > availableLiquidity) revert InsufficientLiquidity();

        // Calculate shares to burn
        uint256 sharesToBurn = _mulDivUp(amount_, EXCHANGE_RATE_PRECISION, market.supplyExchangeRate);
        if (sharesToBurn > position.supplyShares) revert InsufficientShares();

        // Update user position
        position.supplyShares -= sharesToBurn;

        // Update market state
        market.totalSupplyShares -= sharesToBurn;
        market.totalSupplyAssets -= amount_;
        market.totalPhysicalSupply -= amount_;

        // Update exchange rate
        if (market.totalSupplyShares > 0) {
            market.supplyExchangeRate = _flooredSupplyRate(market.totalSupplyAssets, market.totalSupplyShares);
        } else {
            market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }

        DepositorPosition storage dp = depositorPositions[msg.sender];

        // Reduce totalDepositedAssets by the withdrawal amount, but cap at zero
        // This allows LPs to withdraw yield beyond their original deposit
        if (dp.totalDepositedAssets >= amount_) {
            dp.totalDepositedAssets -= amount_;
        } else {
            dp.totalDepositedAssets = 0;
        }

        // Reduce userActualAllocation by withdrawal amount, but cap at zero
        // This allows LPs to withdraw yield beyond their original deposit
        if (userActualAllocation[msg.sender][0] >= amount_) {
            userActualAllocation[msg.sender][0] -= amount_;
        } else {
            userActualAllocation[msg.sender][0] = 0;
        }

        // Remove from queue only when fully exited: no deposited assets, no variable allocation,
        // and no residual fixed-market locked positions.
        // Self-guarding: only removes when the LP holds no shares/locked in ANY market.
        _removeFromQueue(msg.sender);

        // Transfer tokens to user
        IERC20(market.token).safeTransfer(msg.sender, amount_);

        emit Withdraw(msg.sender, marketId_, amount_, sharesToBurn);
    }

    /// @notice Withdraw the caller's entire market-0 (variable) position.
    /// @dev Market 0 ONLY. A fixed-market position is illiquid — its funds are lent out — so it
    ///      must be exited through withdrawFromMarket + processWithdrawQueue, where a replacement
    ///      LP fronts the cash. `marketId_` is kept in the signature for ABI compatibility.
    function withdrawAll(uint256 marketId_) external nonReentrant {
        if (marketId_ != 0) revert InvalidMarket();

        Market storage market = markets[marketId_];
        UserPosition storage position = userPositions[msg.sender][marketId_];

        // Accrue interest before withdrawal
        _accrueMarketInterest(marketId_);

        // Calculate user's claimable amount from all their shares
        uint256 sharesToBurn = position.supplyShares;
        if (sharesToBurn == 0) revert InvalidAmount();

        uint256 userClaimable = (sharesToBurn * market.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;

        // No locked-allocation branch here: userLockedAllocation is only ever written for FIXED
        // markets, so it is always 0 for market 0 — and this function is market-0 only.

        // Check available liquidity
        uint256 availableLiquidity = market.totalPhysicalSupply > market.totalPhysicalBorrow
            ? market.totalPhysicalSupply - market.totalPhysicalBorrow
            : 0;
        if (userClaimable > availableLiquidity) revert InsufficientLiquidity();

        // Update user position
        position.supplyShares -= sharesToBurn;

        // Update market state
        market.totalSupplyShares -= sharesToBurn;
        market.totalSupplyAssets -= userClaimable;
        market.totalPhysicalSupply -= userClaimable;

        // Update exchange rate
        if (market.totalSupplyShares > 0) {
            market.supplyExchangeRate = _flooredSupplyRate(market.totalSupplyAssets, market.totalSupplyShares);
        } else {
            market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }

        DepositorPosition storage dp = depositorPositions[msg.sender];

        // Reduce totalDepositedAssets by the withdrawal amount, but cap at zero
        // This allows LPs to withdraw yield beyond their original deposit
        if (dp.totalDepositedAssets >= userClaimable) {
            dp.totalDepositedAssets -= userClaimable;
        } else {
            dp.totalDepositedAssets = 0;
        }

        // Reduce userActualAllocation by withdrawal amount, but cap at zero
        // This allows LPs to withdraw yield beyond their original deposit
        if (userActualAllocation[msg.sender][0] >= userClaimable) {
            userActualAllocation[msg.sender][0] -= userClaimable;
        } else {
            userActualAllocation[msg.sender][0] = 0;
        }

        // Remove from queue only when fully exited: no deposited assets, no variable allocation,
        // and no residual fixed-market locked positions.
        // Self-guarding: only removes when the LP holds no shares/locked in ANY market.
        _removeFromQueue(msg.sender);

        // Transfer tokens to user
        IERC20(market.token).safeTransfer(msg.sender, userClaimable);

        emit WithdrawAll(msg.sender, marketId_, userClaimable, sharesToBurn);
    }

    /// @notice Request a withdrawal of `amount_` of the caller's funds locked in a fixed market.
    /// @dev Funds allocated to a fixed market are held as fixed-market shares and can't be withdrawn
    ///      instantly. This queues the request and emits WithdrawQueued; DCN observes the event and
    ///      calls processWithdrawQueue with a replacement LP that takes over the locked position,
    ///      moving the caller's funds back to market 0 where they are burned and paid out.
    ///      Partial withdrawals are supported: `amount_` may be up to the caller's full current
    ///      claim in this market. One pending request per (LP, market), one market per call.
    /// @param marketId_ The fixed market (non-zero) the caller's funds are locked in
    /// @param amount_ The amount the caller wishes to withdraw from this market (<= full claimable)
    function withdrawFromMarket(uint256 marketId_, uint256 amount_) external nonReentrant {
        if (marketId_ == 0 || marketId_ >= marketCount) revert InvalidMarket();
        if (amount_ == 0) revert InvalidAmount();
        // Guard against a duplicate request for the same market while one is already pending
        if (pendingWithdrawAmount[msg.sender][marketId_] > 0) revert WithdrawAlreadyQueued();

        Market storage market = markets[marketId_];
        UserPosition storage position = userPositions[msg.sender][marketId_];

        // Accrue interest so the queued amount reflects the LP's full current claim
        _accrueMarketInterest(marketId_);

        uint256 shares = position.supplyShares;
        if (shares == 0) revert InsufficientShares();

        // The caller's full current claim (value) in this fixed market
        uint256 claimable = (shares * market.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;
        if (claimable == 0) revert InvalidAmount();

        // A request for the whole position (amount_ >= current claim) is a FULL exit — rather than
        // reverting on an over-ask, cap it to the claim and flag it. The flag (not the frozen
        // amount) is what processWithdrawQueue keys on: interest accrues between queue and process,
        // so pricing a full exit off the stored amount would always leave the accrued-interest tail
        // behind as a residual position. With isFullExit set, the processor prices the exit off the
        // position's value AT PROCESS TIME and sweeps the whole (grown) position in one shot. A
        // genuine partial (amount_ < claimable) is stored verbatim and behaves as before.
        bool fullExit = amount_ >= claimable;
        uint256 queuedAmount = fullExit ? claimable : amount_;

        withdrawQueue[marketId_].push(WithdrawRequest({
            user: msg.sender,
            isFullExit: fullExit,
            amount: queuedAmount,
            timestamp: block.timestamp
        }));
        pendingWithdrawAmount[msg.sender][marketId_] = queuedAmount;

        emit WithdrawQueued(msg.sender, marketId_, queuedAmount, fullExit);
    }

    /// @dev Remove a pending withdraw request and clear its pendingWithdrawAmount, so a
    ///      resolved/processed request never strands the LP behind the WithdrawAlreadyQueued
    ///      guard. `requestIndex` must be a valid index into withdrawQueue[marketId_].
    function _removeWithdrawRequest(uint256 marketId_, uint256 requestIndex, address user) internal {
        pendingWithdrawAmount[user][marketId_] = 0;
        WithdrawRequest[] storage queue = withdrawQueue[marketId_];
        queue[requestIndex] = queue[queue.length - 1];
        queue.pop();
    }

    /// @notice Cancel a pending withdraw request for a given LP in a fixed market, clearing it
    ///         from the queue without moving any funds. Callable by the LP themselves or by admin.
    /// @param marketId_ The fixed market the pending request belongs to
    /// @param user The LP whose pending withdraw request should be cancelled
    function cancelWithdrawRequest(uint256 marketId_, address user) external nonReentrant {
        if (msg.sender != user && msg.sender != admin) revert Unauthorized();
        if (marketId_ == 0 || marketId_ >= marketCount) revert InvalidMarket();

        uint256 pendingAmount = pendingWithdrawAmount[user][marketId_];
        if (pendingAmount == 0) revert InvalidAmount();

        WithdrawRequest[] storage queue = withdrawQueue[marketId_];
        uint256 requestIndex = type(uint256).max;
        for (uint256 i = 0; i < queue.length; i++) {
            if (queue[i].user == user) {
                requestIndex = i;
                break;
            }
        }

        if (requestIndex == type(uint256).max) revert InvalidAddress();

        _removeWithdrawRequest(marketId_, requestIndex, user);

        emit WithdrawCancelled(user, marketId_, pendingAmount);
    }

    /// @notice Number of receipts in a fixed market's allocation ledger — the pagination bound for
    ///         getAllocationLedgerDecoded.
    function getAllocationLedgerLength(uint256 marketId_) external view returns (uint256) {
        return allocationLedger[marketId_].length;
    }

    /// @notice Decoded, LIVE, PAGINATED view of a fixed market's allocation ledger for off-chain
    ///         (DCN) use: one row per ledger receipt in [start_, start_ + count_) with the lender and
    ///         their CURRENT locked allocation and fixed-market supply shares — read from live state,
    ///         NOT the receipt's stale packed principal.
    /// @dev Paginated so an arbitrarily large ledger can never blow the node's eth_call gas/time cap.
    ///      The ledger can hold duplicate lenders (one receipt per allocating borrow) and stale rows
    ///      for lenders since fully deallocated (locked == 0 && shares == 0, receipts skipped lazily
    ///      on pop). Callers should dedup by address and may drop all-zero rows. `start_` past the end
    ///      returns empty arrays; the window is clamped to the ledger length.
    /// @param marketId_ The fixed market whose ledger to read
    /// @param start_ First receipt index to return
    /// @param count_ Max receipts to return from `start_`
    /// @return lenders Lender address per receipt (in ledger order)
    /// @return lockedAllocations Live userLockedAllocation for each lender in this market
    /// @return supplyShares Live fixed-market supply shares for each lender
    function getAllocationLedgerDecoded(uint256 marketId_, uint256 start_, uint256 count_)
        external
        view
        returns (address[] memory lenders, uint256[] memory lockedAllocations, uint256[] memory supplyShares)
    {
        uint256[] storage ledger = allocationLedger[marketId_];
        uint256 len = ledger.length;
        if (start_ >= len || count_ == 0) {
            return (new address[](0), new uint256[](0), new uint256[](0));
        }
        uint256 end = start_ + count_;
        if (end > len) end = len;
        uint256 n = end - start_;
        lenders = new address[](n);
        lockedAllocations = new uint256[](n);
        supplyShares = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            address lp = address(uint160(ledger[start_ + i]));
            lenders[i] = lp;
            lockedAllocations[i] = userLockedAllocation[lp][marketId_];
            supplyShares[i] = userPositions[lp][marketId_].supplyShares;
        }
    }

    /// @notice Process the withdraw queue for a single exiting LP by swapping the requested
    ///         (possibly partial) locked allocation onto one or more replacement LPs.
    /// @dev Admin-only (owner). Exactly ONE withdrawing LP is processed per call. Only the
    ///      amount the LP originally requested via withdrawFromMarket is swapped/withdrawn —
    ///      any remaining locked position beyond that amount is left untouched for a later
    ///      request. The swap is distributed across `replacementLPs` in order, each
    ///      contributing up to its own exposure capacity, until the full requested amount is
    ///      covered — so several smaller LPs can collectively replace the requested amount
    ///      when no single LP has enough capacity alone.
    ///      Reverts if the provided replacements cannot cover the full swap.
    /// @param marketId_ Target fixed market
    /// @param withdrawingLP The single LP being exited from the queue
    /// @param replacementLPs Ordered list of LPs that take over the withdrawing LP's position
    function processWithdrawQueue(uint256 marketId_, address withdrawingLP, address[] calldata replacementLPs)
        external
        onlyAdmin
        nonReentrant
    {
        if (marketId_ == 0 || marketId_ >= marketCount) revert InvalidMarket();
        if (withdrawingLP == address(0)) revert InvalidAddress();
        if (replacementLPs.length == 0) revert InvalidAddress();

        Market storage market = markets[marketId_];
        WithdrawRequest[] storage queue = withdrawQueue[marketId_];

        if (queue.length == 0) return;

        // Accrue interest before processing. Market 0 must be accrued too: the swap below prices
        // market-0 share transfers off variableMarket.supplyExchangeRate, so a stale rate would
        // move too many shares from the replacement LP to the withdrawing LP — a per-call
        // LP-to-LP interest leak equal to the unbooked market-0 interest on the swapped value.
        _accrueMarketInterest(marketId_);
        _accrueMarketInterest(0);

        // Find the withdrawing LP's request in the queue
        uint256 requestIndex = type(uint256).max;
        for (uint256 i = 0; i < queue.length; i++) {
            if (queue[i].user == withdrawingLP) {
                requestIndex = i;
                break;
            }
        }

        if (requestIndex == type(uint256).max) return; // Request not found

        WithdrawRequest storage request = queue[requestIndex];

        // `lockedAmount` is the exiter's PRINCIPAL overlay; it no longer gates the swap, it only
        // sets the principal:value ratio applied per portion below. A yield-only position
        // (locked == 0, shares > 0) is a legitimate exit: it swaps as a pure yield-for-cash
        // transfer with lockedMoved == 0 throughout.
        uint256 lockedAmount = userLockedAllocation[withdrawingLP][marketId_];

        // Get withdrawing LP's fixed market shares. Zero shares is the only true "already
        // resolved" case (e.g. the borrower repaid and the position was deallocated before
        // processing) — clear the stale request so the LP isn't stuck behind WithdrawAlreadyQueued.
        UserPosition storage withdrawingPos = userPositions[withdrawingLP][marketId_];
        uint256 withdrawingShares = withdrawingPos.supplyShares;

        if (withdrawingShares == 0) {
            _removeWithdrawRequest(marketId_, requestIndex, withdrawingLP);
            return;
        }

        // Share value of the position: principal + accrued yield, at the current rate.
        uint256 shareValue = (withdrawingShares * market.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;

        // Swap the share value the LP requested (capped only by what they actually hold). Value
        // moves at shareValue; the principal overlay moves pro rata per portion, so the replacement
        // ends up in exactly the state of an LP who held the position through the accrual: shares
        // worth `portion`, locked == the principal fraction of it.
        // A FULL exit is priced off the CURRENT shareValue (not the stored, pre-accrual amount) so
        // the whole grown position — including interest accrued since it was queued — is swept out
        // and no yield-only residue is left behind.
        bool isFullExit = request.isFullExit;
        uint256 swapAmount;
        if (isFullExit) {
            swapAmount = shareValue;
        } else {
            swapAmount = request.amount;
            if (swapAmount > shareValue) swapAmount = shareValue;
        }

        Market storage variableMarket = markets[0];

        // Distribute the swap across the replacement LPs. Each takes over as much of the
        // withdrawing LP's position as its own exposure capacity allows; we move on to the
        // next replacement until the full swapAmount is covered. Each swap is a symmetric
        // share transfer between the two LPs — market totals are unchanged.
        uint256 remainingSwap = swapAmount;
        for (uint256 r = 0; r < replacementLPs.length && remainingSwap > 0; r++) {
            address replacementLP = replacementLPs[r];
            if (replacementLP == address(0) || replacementLP == withdrawingLP) continue;

            // This replacement LP's remaining capacity — same formula the borrow/allocation
            // path uses, so a replacement can absorb exactly what it could be allocated normally.
            uint256 replacementCapacity = PoolLogicLib.lpAllocatableCapacity(
                markets,
                marketCount,
                userExposureBps,
                userPositions,
                userActualAllocation,
                userLockedAllocation,
                replacementLP,
                marketId_
            );
            if (replacementCapacity == 0) continue;

            // Portion this replacement covers = min(remaining, its capacity)
            uint256 portion = remainingSwap > replacementCapacity ? replacementCapacity : remainingSwap;

            // 1a. Fixed-market shares: withdrawing LP -> replacement LP, plus the principal
            //     (`lockedMoved`) that rides along pro rata to the share value moved. Ratio inputs
            //     (lockedAmount / shareValue) are frozen at entry so they can't drift mid-loop.
            //     On the final portion of a FULL exit, sweep the exiter's whole remaining position
            //     instead of recomputing from value — avoids the sub-share flooring residue that
            //     would otherwise leave a 1-wei yield-only position behind.
            uint256 sharesToTransfer;
            uint256 lockedMoved;
            uint256 exiterLocked = userLockedAllocation[withdrawingLP][marketId_];
            if (isFullExit && portion == remainingSwap) {
                sharesToTransfer = withdrawingPos.supplyShares;
                lockedMoved = exiterLocked;
            } else {
                sharesToTransfer = (portion * EXCHANGE_RATE_PRECISION) / market.supplyExchangeRate;
                if (sharesToTransfer > withdrawingPos.supplyShares) sharesToTransfer = withdrawingPos.supplyShares;
                lockedMoved = (portion * lockedAmount) / shareValue;
                if (lockedMoved > exiterLocked) lockedMoved = exiterLocked;
            }
            withdrawingPos.supplyShares -= sharesToTransfer;
            userPositions[replacementLP][marketId_].supplyShares += sharesToTransfer;

            // 1b. Market 0 shares: replacement LP -> withdrawing LP (freed funds land back in market 0
            //     as real shares the withdrawing LP can burn on payout)
            uint256 market0SharesToTransfer = variableMarket.supplyExchangeRate > 0
                ? (portion * EXCHANGE_RATE_PRECISION) / variableMarket.supplyExchangeRate
                : 0;
            if (market0SharesToTransfer > userPositions[replacementLP][0].supplyShares) {
                market0SharesToTransfer = userPositions[replacementLP][0].supplyShares;
            }
            userPositions[replacementLP][0].supplyShares -= market0SharesToTransfer;
            userPositions[withdrawingLP][0].supplyShares += market0SharesToTransfer;

            // 2. Transfer the PRINCIPAL overlay — `lockedMoved`, not `portion`. Moving the full
            //    share value here would inflate the replacement's locked above the outstanding
            //    borrowed principal and break sum(locked) == borrowed principal. Capped above, so
            //    the subtraction cannot underflow.
            userLockedAllocation[withdrawingLP][marketId_] = exiterLocked - lockedMoved;
            userLockedAllocation[replacementLP][marketId_] += lockedMoved;

            // Keep the ledger complete: the replacement now backs `lockedMoved` of principal in
            // this market, so record a receipt for them (packed: principal uint96 << 160 | lender).
            // A yield-only portion moves no principal — skip the push rather than write a dead
            // zero-principal slot. The withdrawing LP's own receipts are skipped lazily on pop.
            if (lockedMoved > 0) {
                allocationLedger[marketId_].push(
                    (uint256(uint96(lockedMoved)) << 160) | uint256(uint160(replacementLP))
                );
            }

            // 3. Transfer actual allocation (target market) — principal-denominated, so it tracks
            //    `lockedMoved`. Guard the subtraction: after a partial repay with accrued interest,
            //    actual can be below locked, and an unguarded subtraction would panic and
            //    permanently brick this request.
            if (userActualAllocation[withdrawingLP][marketId_] >= lockedMoved) {
                userActualAllocation[withdrawingLP][marketId_] -= lockedMoved;
            } else {
                userActualAllocation[withdrawingLP][marketId_] = 0;
            }
            userActualAllocation[replacementLP][marketId_] += lockedMoved;

            // 4. Update replacement LP's market 0 allocation
            if (userActualAllocation[replacementLP][0] >= portion) {
                userActualAllocation[replacementLP][0] -= portion;
            } else {
                userActualAllocation[replacementLP][0] = 0;
            }

            // 5. Withdrawing LP gets back the freed funds in market 0
            userActualAllocation[withdrawingLP][0] += portion;

            remainingSwap -= portion;
        }

        // The provided replacement LPs must collectively cover the full swap
        if (remainingSwap > 0) revert InsufficientExposure();

        // Now process the actual withdrawal from market 0. Market 0 was already accrued up-front
        // (before the swap priced market-0 shares); no time has passed since, so re-accruing here
        // would be a no-op.
        UserPosition storage withdrawingMarket0Pos = userPositions[withdrawingLP][0];
        uint256 withdrawingMarket0Shares = withdrawingMarket0Pos.supplyShares;

        if (withdrawingMarket0Shares > 0) {
            uint256 market0Claimable = (withdrawingMarket0Shares * variableMarket.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;

            // Pay out only the value that came FROM the fixed position: `swapAmount` (the whole
            // grown position on a full exit, the requested slice on a partial). NOT the LP's entire
            // market-0 balance — that can include a pre-existing liquid position which this
            // fixed-market exit must not touch (allocateFundsToMarket burns only the allocated
            // slice of market-0 shares, so an LP can still hold unallocated market-0 shares here).
            // market0Claimable is only the safety cap on what is actually claimable/available.
            uint256 withdrawAmount = swapAmount;
            if (withdrawAmount > market0Claimable) withdrawAmount = market0Claimable;

            // Check available liquidity in market 0
            uint256 availableLiquidity = variableMarket.totalPhysicalSupply > variableMarket.totalPhysicalBorrow
                ? variableMarket.totalPhysicalSupply - variableMarket.totalPhysicalBorrow
                : 0;

            if (withdrawAmount > availableLiquidity) withdrawAmount = availableLiquidity;

            if (withdrawAmount > 0) {
                // Calculate shares to burn
                uint256 sharesToBurn = _mulDivUp(withdrawAmount, EXCHANGE_RATE_PRECISION, variableMarket.supplyExchangeRate);
                if (sharesToBurn > withdrawingMarket0Shares) sharesToBurn = withdrawingMarket0Shares;

                // Update user position
                withdrawingMarket0Pos.supplyShares -= sharesToBurn;

                // Update market state
                variableMarket.totalSupplyShares -= sharesToBurn;
                variableMarket.totalSupplyAssets -= withdrawAmount;
                variableMarket.totalPhysicalSupply -= withdrawAmount;

                // Update exchange rate
                if (variableMarket.totalSupplyShares > 0) {
                    variableMarket.supplyExchangeRate = _flooredSupplyRate(variableMarket.totalSupplyAssets, variableMarket.totalSupplyShares);
                } else {
                    variableMarket.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
                }

                // Update depositor position
                DepositorPosition storage dp = depositorPositions[withdrawingLP];
                if (dp.totalDepositedAssets >= withdrawAmount) {
                    dp.totalDepositedAssets -= withdrawAmount;
                } else {
                    dp.totalDepositedAssets = 0;
                }

                if (userActualAllocation[withdrawingLP][0] >= withdrawAmount) {
                    userActualAllocation[withdrawingLP][0] -= withdrawAmount;
                } else {
                    userActualAllocation[withdrawingLP][0] = 0;
                }

                // Remove from queue if fully exited
                // Self-guarding (see withdraw): no-ops while any position remains.
                _removeFromQueue(withdrawingLP);

                // Transfer tokens to withdrawing LP
                IERC20(variableMarket.token).safeTransfer(withdrawingLP, withdrawAmount);

                emit Withdraw(withdrawingLP, 0, withdrawAmount, sharesToBurn);
            }
        }

        // Clear pending withdraw amount and remove the request from the queue
        _removeWithdrawRequest(marketId_, requestIndex, withdrawingLP);

        // If the withdrawing LP was also in the exit queue (opted out separately), remove the entry
        // outright. Clearing only the flag left a permanent stale address behind, so ordinary
        // opt-out/withdraw churn grew the queue monotonically even with no attacker (see
        // _dequeueExit).
        if (inExitQueue[marketId_][withdrawingLP]) _dequeueExit(withdrawingLP, marketId_);

        emit WithdrawProcessed(withdrawingLP, marketId_, swapAmount, replacementLPs);
    }

    // ============================================
    // CORE FUNCTIONS - BORROW
    // ============================================

    /// @notice Borrow funds from a market (issues borrow shares)
    function borrow(address token_, address borrower_, uint256 amount_, uint256 marketId_, address[] calldata lpAddresses)
        external
        onlyVaultManager
        nonReentrant
        whenNotPaused
        returns (uint256 borrowShares_)
    {
        if (marketId_ >= marketCount) revert InvalidMarket();

        Market storage market = markets[marketId_];
        if (!market.active) revert MarketNotActive();
        if (market.token != token_) revert TokenNotSupported();

        // Accrue interest before borrow
        _accrueMarketInterest(marketId_);
        if (marketId_ != 0) _accrueMarketInterest(0);

        if (marketId_ != 0) {
            // Allocate directly against the caller-supplied LP list (only those LPs are
            // traversed and their combined capacity is validated inside allocateFundsToMarket);
            // an empty list falls back to global FIFO. The previous
            // calculateTotalExposureToMarket pre-check was removed: it was redundant
            // (allocateFundsToMarket already reverts InsufficientExposure when it can't cover)
            // and scanned the entire depositorQueue on every fixed-market borrow — a dust-Sybil
            // DoS vector — even when an explicit list was provided.
            PoolLogicLib.allocateFundsToMarket(
                markets,
                marketCount,
                depositorQueue,
                userExposureBps,
                userPositions,
                userActualAllocation,
                userLockedAllocation,
                allocationLedger[marketId_],
                marketId_,
                amount_,
                lpAddresses
            );
        }

        // Check available liquidity
        uint256 availableLiquidity = market.totalPhysicalSupply > market.totalPhysicalBorrow
            ? market.totalPhysicalSupply - market.totalPhysicalBorrow
            : 0;
        if (amount_ > availableLiquidity) revert InsufficientLiquidity();

        // Calculate borrow shares to issue
        uint256 borrowSharesToIssue;
        if (market.totalBorrowShares == 0) {
            // First borrow: 1:1 ratio
            borrowSharesToIssue = amount_;
        } else {
            // Calculate based on current exchange rate
            borrowSharesToIssue =
                (amount_ * EXCHANGE_RATE_PRECISION + market.borrowExchangeRate - 1) / market.borrowExchangeRate;
        }

        // Update market state
        market.totalBorrowShares += borrowSharesToIssue;
        market.totalBorrowAssets += amount_;
        market.totalPhysicalBorrow += amount_;
        // Option A semantics: totalPhysicalSupply tracks total pool assets (cash + outstanding principal).
        // Borrowing shifts assets from cash to loan principal, so totalPhysicalSupply does not change here.

        // Update exchange rate
        if (market.totalBorrowShares > 0) {
            market.borrowExchangeRate = (market.totalBorrowAssets * EXCHANGE_RATE_PRECISION) / market.totalBorrowShares;
        }

        // Transfer tokens to borrower
        IERC20(market.token).safeTransfer(borrower_, amount_);

        borrowShares_ = borrowSharesToIssue;
        emit Borrow(borrower_, marketId_, amount_, borrowSharesToIssue);
    }

    // ============================================
    // CORE FUNCTIONS - REPAY
    // ============================================

    /// @notice Repay borrowed funds — VaultManager is source of truth for debt, LP only tracks market-level totals
    function repay(address token_, address borrower_, uint256 amount_, uint256 marketId_)
        external
        onlyVaultManager
        nonReentrant
        returns (uint256 sharesToBurn_)
    {
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (amount_ == 0) revert InvalidAmount();

        Market storage market = markets[marketId_];
        if (market.token != token_) revert TokenNotSupported();

        // Accrue interest before repayment
        _accrueMarketInterest(marketId_);

        // Cap repay to total outstanding borrow
        uint256 repayAmount = amount_;
        if (market.totalBorrowAssets > 0 && repayAmount > market.totalBorrowAssets) {
            repayAmount = market.totalBorrowAssets;
        }
        if (repayAmount == 0) revert InvalidAmount();

        // Transfer tokens from VaultManager (it holds them after ERC3009 transfer)
        IERC20(market.token).safeTransferFrom(msg.sender, address(this), repayAmount);

        // Calculate shares to burn proportional to repayAmount / totalBorrowAssets
        // Use regular division (not _mulDivUp) to match the rounding direction of physicalBorrowToReduce
        uint256 sharesToBurn =
            market.totalBorrowShares > 0 ? (repayAmount * market.totalBorrowShares) / market.totalBorrowAssets : 0;

        // Calculate physical borrow reduction directly from proportion to avoid double round-down
        // This prevents accumulated rounding dust across multiple repayments
        uint256 physicalBorrowToReduce = market.totalBorrowAssets > 0
            ? (repayAmount * market.totalPhysicalBorrow) / market.totalBorrowAssets
            : repayAmount;

        // Calculate interest portion
        uint256 interestPortion = repayAmount > physicalBorrowToReduce ? repayAmount - physicalBorrowToReduce : 0;

        // Update market state
        if (sharesToBurn > market.totalBorrowShares) sharesToBurn = market.totalBorrowShares;
        market.totalBorrowShares -= sharesToBurn;
        market.totalBorrowAssets = market.totalBorrowAssets > repayAmount ? market.totalBorrowAssets - repayAmount : 0;
        market.totalPhysicalBorrow = market.totalPhysicalBorrow > physicalBorrowToReduce
            ? market.totalPhysicalBorrow - physicalBorrowToReduce
            : 0;

        // Full interest flows into totalPhysicalSupply (protocol's portion is tracked via protocolSupplyShares)
        if (interestPortion > 0 && marketId_ == 0) {
            market.totalPhysicalSupply += interestPortion;
        }

        // Update exchange rate
        if (market.totalBorrowShares > 0) {
            market.borrowExchangeRate = (market.totalBorrowAssets * EXCHANGE_RATE_PRECISION) / market.totalBorrowShares;
        } else {
            market.borrowExchangeRate = EXCHANGE_RATE_PRECISION;
        }

        // For fixed markets: split repayAmount into LP and protocol portions so each is
        // counted exactly once in market 0's totalPhysicalSupply.
        if (marketId_ != 0 && repayAmount > 0) {
            _accrueMarketInterest(0);
            uint256 supplySharesBefore = market.totalSupplyShares;
            uint256 protocolPortion = 0;
            if (market.protocolSupplyShares > 0 && supplySharesBefore > 0) {
                protocolPortion = (market.protocolSupplyShares * repayAmount) / supplySharesBefore;
            }
            // Migrate protocol slice FIRST while totalPhysicalSupply still holds full principal
            // so the cap in _migrateProtocolSharesToVariable never fires against a depleted value.
            // Then deallocate the LP slice.
            if (protocolPortion > 0) PoolLogicLib.migrateProtocolSharesToVariable(markets, marketId_, protocolPortion);
            _deallocate(marketId_, repayAmount - protocolPortion);
        }
        sharesToBurn_ = sharesToBurn;
        emit Repay(borrower_, marketId_, repayAmount, sharesToBurn);
    }

    /// @notice Finalize tiny residual borrow after VaultManager updates market debt count
    /// @dev Called by VaultManager after position debt reaches zero.
    /// @dev Callable by the VaultManager (inline on the last repay/liquidation of a market) or by
    ///      admin as a retry. The VM call is best-effort — if this reverts there (e.g. the pre-ledger
    ///      fallback scan runs out of gas on a dust-Sybil-inflated depositor queue), the borrower's
    ///      repay is NOT blocked; admin can re-invoke this with a fresh gas budget to complete close.
    function finalizeMarketDust(uint256 marketId_) external nonReentrant {
        if (msg.sender != vaultManager && msg.sender != admin) revert Unauthorized();
        if (marketId_ >= marketCount) revert InvalidMarket();

        // Accrue before reading rates. Migration below mints market-0 shares off market 0's supply
        // rate, so a stale rate would misprice them. Self-accruing matters for the admin retry
        // path: the inline VM call rides a repay/liquidation that already accrued market 0, but a
        // standalone admin call may hit a stale market 0.
        _accrueMarketInterest(marketId_);
        if (marketId_ != 0) _accrueMarketInterest(0);

        // Only close when VM confirms no active position debt remains in this market.
        if (_vaultManagerHasActiveDebtInMarket(marketId_)) return;

        // Heavy dust-cleanup body lives in the library (DELEGATECALL) to keep this contract under the
        // EIP-170 limit. Auth, bounds, accrual, and the active-debt guard above stay here because they
        // need pool internals; everything below is pure storage manipulation over the passed refs.
        PoolLogicLib.finalizeMarketDustCore(
            markets,
            depositorQueue,
            userPositions,
            userActualAllocation,
            userLockedAllocation,
            allocationLedger[marketId_],
            marketExitQueue[marketId_],
            inExitQueue[marketId_],
            marketId_
        );
    }

    // ============================================
    // INTEREST ACCRUAL
    // ============================================

    /// @notice Accrue interest for a market - callable by VaultManager to synchronize
    ///         exchange rates before debt calculation, preventing stale-rate residuals.
    function accrueMarketInterest(uint256 marketId_) external onlyVaultManager nonReentrant {
        if (marketId_ >= marketCount) revert InvalidMarket();
        _accrueMarketInterest(marketId_);
    }

    /// @notice Accrue interest for a market (aligned with simulator)
    function _accrueMarketInterest(uint256 marketId_) internal {
        Market storage market = markets[marketId_];

        if (market.totalBorrowAssets == 0) {
            // Sync provider clock even with zero borrows to prevent rate drift
            // For adaptive providers: updates lastRateUpdate to keep clock current
            // For fixed providers: harmless call that returns constant rate (view function)
            market.provider.getBorrowRate(0, market.totalSupplyAssets);
            market.lastAccrueTime = block.timestamp;
            return;
        }

        uint256 timeElapsed = block.timestamp - market.lastAccrueTime;
        if (timeElapsed == 0) return;

        // Get borrow rate from provider.
        // Utilization basis = totalBorrowAssets / totalSupplyAssets (both interest-inclusive),
        // so the rate borrowers are charged matches what getMarketBorrowRate/getUtilization report.
        uint256 borrowRateBps = market.provider.getBorrowRate(market.totalBorrowAssets, market.totalSupplyAssets);

        // Convert BPS/year rate to WAD/second, then apply Taylor-series compound approximation
        uint256 interestAccrued = _computeBorrowInterest(market.totalBorrowAssets, borrowRateBps, timeElapsed);

        if (interestAccrued > 0) {
            // Increase borrow assets (what borrowers owe)
            market.totalBorrowAssets += interestAccrued;

            uint256 protocolCut = (interestAccrued * market.reserveRateBps) / BPS_DENOMINATOR;

            // Full interest goes to supply assets (lenders + protocol share via minted shares)
            market.totalSupplyAssets += interestAccrued;

            // Mint protocol shares (Morpho-style): protocolShares = F × S / (A + I − F)
            // After minting, protocol's value = F, lenders' value = A + (I − F)  ✓
            if (protocolCut > 0 && market.totalSupplyShares > 0) {
                uint256 denominator = market.totalSupplyAssets - protocolCut;
                if (denominator > 0) {
                    uint256 protocolShares = (protocolCut * market.totalSupplyShares) / denominator;
                    if (protocolShares > 0) {
                        market.totalSupplyShares += protocolShares;
                        market.protocolSupplyShares += protocolShares;
                        emit ProtocolSharesMinted(marketId_, protocolShares, protocolCut);
                    }
                }
            }

            // Update exchange rates
            if (market.totalSupplyShares > 0) {
                market.supplyExchangeRate =
                    _flooredSupplyRate(market.totalSupplyAssets, market.totalSupplyShares);
            } else {
                market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
            }
            if (market.totalBorrowShares > 0) {
                market.borrowExchangeRate =
                    (market.totalBorrowAssets * EXCHANGE_RATE_PRECISION) / market.totalBorrowShares;
            }

            uint256 lenderCut = interestAccrued - protocolCut;
            emit InterestAccrued(marketId_, interestAccrued, protocolCut, lenderCut);
        }

        market.lastAccrueTime = block.timestamp;
    }

    // ============================================
    // LIQUIDATION
    // ============================================

    /// @notice Repay from liquidation with PnL distribution
    function repayFromLiquidation(uint256 marketId_, uint256 bidAmount_, uint256 borrowedValue_)
        external
        onlyVaultManager
        nonReentrant
        whenNotPaused
    {
        if (marketId_ >= marketCount) revert InvalidMarket();

        Market storage market = markets[marketId_];

        // Accrue interest first to ensure totalSupplyAssets includes LP yield
        _accrueMarketInterest(marketId_);
        if (marketId_ != 0) _accrueMarketInterest(0);

        // Transfer tokens from vault manager
        IERC20(market.token).safeTransferFrom(msg.sender, address(this), bidAmount_);

        // Calculate lender loss/gain
        int256 lenderLoss = int256(borrowedValue_) - int256(bidAmount_);

        // Calculate physical borrow reduction directly from proportion to avoid double round-down
        // This prevents accumulated rounding dust across multiple liquidations
        uint256 physicalBorrowToReduce = market.totalBorrowAssets > 0
            ? (borrowedValue_ * market.totalPhysicalBorrow) / market.totalBorrowAssets
            : borrowedValue_;

        // Interest portion actually recovered by the bid (capped at interest owed, excludes principal and gain)
        uint256 cappedBid = bidAmount_ < borrowedValue_ ? bidAmount_ : borrowedValue_;
        uint256 interestPortionInBid = cappedBid > physicalBorrowToReduce ? cappedBid - physicalBorrowToReduce : 0;

        // Full recovered interest flows into totalPhysicalSupply (protocol tracked via protocolSupplyShares)
        if (interestPortionInBid > 0 && marketId_ == 0) {
            market.totalPhysicalSupply += interestPortionInBid;
        }

        // Derive shares to burn from borrowedValue using exchange rate.
        // Floor is intentional (matches physicalBorrowToReduce's rounding above; see repay() note).
        // Borrow shares are issued rounding UP at borrow time but burned rounding DOWN here, so a
        // multi-borrower market can retain ~1 phantom borrow share per fully-liquidated borrower —
        // burningAllShares (below) clears it on the final liquidation, and finalizeMarketDust
        // reconciles any residue at close. Bounded dust, not a leak; do not "fix" with _mulDivUp.
        uint256 sharesToBurn =
            market.borrowExchangeRate > 0 ? (borrowedValue_ * EXCHANGE_RATE_PRECISION) / market.borrowExchangeRate : 0;
        if (sharesToBurn > market.totalBorrowShares) sharesToBurn = market.totalBorrowShares;

        // If burning all shares, zero out all borrow state (handles VaultManager's stale borrowedValue)
        bool burningAllShares = (sharesToBurn == market.totalBorrowShares);

        market.totalBorrowShares -= sharesToBurn;

        if (burningAllShares) {
            // When all shares are burned, zero out everything regardless of borrowedValue
            // This handles cases where borrowedValue from VaultManager is stale due to continued interest accrual
            market.totalBorrowShares = 0;
            market.totalBorrowAssets = 0;
            market.totalPhysicalBorrow = 0;
        } else {
            // Partial liquidation: reduce by borrowedValue
            market.totalBorrowAssets =
                market.totalBorrowAssets > borrowedValue_ ? market.totalBorrowAssets - borrowedValue_ : 0;
            market.totalPhysicalBorrow = market.totalPhysicalBorrow > physicalBorrowToReduce
                ? market.totalPhysicalBorrow - physicalBorrowToReduce
                : 0;
        }

        // Update supply: subtract loss/gain
        if (lenderLoss > 0) {
            // Loss case: reduce totalSupplyAssets by full loss — protocol shares lose value proportionally
            uint256 totalLoss = uint256(lenderLoss);
            market.totalSupplyAssets = market.totalSupplyAssets >= totalLoss ? market.totalSupplyAssets - totalLoss : 0;
            if (marketId_ == 0) {
                uint256 principalLoss = physicalBorrowToReduce > bidAmount_ ? physicalBorrowToReduce - bidAmount_ : 0;
                market.totalPhysicalSupply =
                    market.totalPhysicalSupply >= principalLoss ? market.totalPhysicalSupply - principalLoss : 0;
            }
        } else {
            // Gain case
            uint256 gain = uint256(-lenderLoss);
            market.totalSupplyAssets += gain;
            // Physical: only market 0 books the surplus cash directly. For a fixed market the surplus
            // reaches market 0 through the deallocation below (it is part of bidAmount_); writing it
            // into the fixed market's principal-tracking totalPhysicalSupply here — then stripping it
            // at the physical/assets ratio (< 1 under accrued interest) — under-removes it on a partial
            // unwind, leaving phantom, unbacked supply. Mirror the interest/loss branches: gate on 0.
            if (marketId_ == 0) market.totalPhysicalSupply += gain;
        }

        // Note: totalPhysicalSupply is reduced in _deallocateFundsFromMarket
        // The proportional reduction based on shares burned handles both normal repay and liquidations

        // Update exchange rates
        if (market.totalSupplyShares > 0) {
            market.supplyExchangeRate = _flooredSupplyRate(market.totalSupplyAssets, market.totalSupplyShares);
        } else {
            market.supplyExchangeRate = EXCHANGE_RATE_PRECISION;
        }
        if (market.totalBorrowShares > 0) {
            market.borrowExchangeRate = (market.totalBorrowAssets * EXCHANGE_RATE_PRECISION) / market.totalBorrowShares;
        } else {
            // Reset to 1:1 once the borrow side is empty (consistent with repay() and finalizeMarketDust()).
            market.borrowExchangeRate = EXCHANGE_RATE_PRECISION;
        }

        emit LiquidationRepay(marketId_, bidAmount_, borrowedValue_, -lenderLoss);

        // Deallocate funds based on profit/loss scenario.
        // Split bidAmount_ into LP and protocol portions to prevent each deallocation path
        // from double-counting the protocol's slice in market 0's totalPhysicalSupply.
        if (marketId_ != 0 && bidAmount_ > 0) {
            uint256 supplySharesBefore = markets[marketId_].totalSupplyShares;
            Market storage fixedMkt = markets[marketId_];
            // Cache the protocol share count BEFORE the migration below burns it — both the
            // protocol/LP split and the physical split must use the same pre-migration basis.
            uint256 protocolSharesBefore = fixedMkt.protocolSupplyShares;
            uint256 protocolPortion = 0;
            if (protocolSharesBefore > 0 && supplySharesBefore > 0) {
                protocolPortion = (protocolSharesBefore * bidAmount_) / supplySharesBefore;
            }
            uint256 lpPortion = bidAmount_ - protocolPortion;
            // Migrate protocol slice FIRST while totalPhysicalSupply still holds full principal.
            // Capture the PRINCIPAL physical the migration actually stripped, so the loss write-down
            // below removes exactly the remaining principal (migration + write-down == full principal).
            uint256 migratedPhysical = 0;
            if (protocolPortion > 0) {
                migratedPhysical = PoolLogicLib.migrateProtocolSharesToVariable(markets, marketId_, protocolPortion);
            }
            if (lenderLoss == 0) {
                // Break-even == a normal full-recovery repay: bidAmount_ equals the liquidated value,
                // so the ratio-based deallocation strips exactly the principal and conserves.
                if (lpPortion > 0) _deallocate(marketId_, lpPortion);
            } else {
                // GAIN or LOSS: the ratio-based strip cannot handle a pure surplus/deficit once
                // interest has accrued (physical/assets != the principal fraction of bidAmount_), so it
                // over/under-removes physical. Instead strip the EXACT remaining principal —
                // physicalBorrowToReduce minus what the migration already relocated — so migration +
                // write-down remove the full principal from totalPhysicalSupply, and the surplus/deficit
                // lands in market 0 through the value deallocation. Conserves for both signs of loss.
                uint256 lpPhysical =
                    physicalBorrowToReduce > migratedPhysical ? physicalBorrowToReduce - migratedPhysical : 0;
                if (lpPortion > 0) {
                    _deallocateLoss(marketId_, lpPortion, lpPhysical);
                }
            }
        }
    }

    function setExposure(uint256 marketId_, uint256 exposureBps_) external nonReentrant whenNotPaused {
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (marketId_ == 0) revert InvalidMarket();
        if (exposureBps_ > 10000) revert InvalidExposure();
        if (!markets[marketId_].active) revert MarketNotActive();

        // Must be a live LP. Keyed on actual holdings (shares/locked), NOT totalDepositedAssets,
        // which clamps to 0 once an LP withdraws their original principal even while interest-grown
        // share value remains — otherwise a still-funded LP could not adjust exposure.
        if (!_hasAnyLpPosition(msg.sender)) revert InvalidAmount();

        userExposureBps[msg.sender][marketId_] = exposureBps_;
        emit ExposureUpdated(msg.sender, marketId_, exposureBps_);
        _maybeEnqueueExit(msg.sender, marketId_, exposureBps_);
    }

    /// @dev A lender setting exposure to 0 while still allocated to a fixed market is opting out:
    ///      drop them into that market's exit queue so the next deallocation returns their funds
    ///      to market 0 first — permissionless, no DCN/admin needed. Deduped via inExitQueue.
    function _maybeEnqueueExit(address lender, uint256 marketId_, uint256 exposureBps_) internal {
        // Keyed on holding a position at all (shares OR locked), not on locked alone: a yield-only
        // holder is still a live shareholder and must get the same opt-out priority.
        bool hasPosition =
            userLockedAllocation[lender][marketId_] > 0 || userPositions[lender][marketId_].supplyShares > 0;
        if (exposureBps_ == 0 && hasPosition && !inExitQueue[marketId_][lender]) {
            inExitQueue[marketId_][lender] = true;
            marketExitQueue[marketId_].push(lender);
            exitQueueIndex[marketId_][lender] = marketExitQueue[marketId_].length; // 1-based
            emit ExitQueued(lender, marketId_);
        } else if (exposureBps_ != 0 && inExitQueue[marketId_][lender]) {
            // Re-opt-in: the lender re-committed to this market, so revoke their exit-queue priority.
            // Without this, a lender who set exposure 0 then back to non-zero stays flagged and gets
            // force-unwound ahead of LIFO on the next deallocation — returning their re-committed
            // position against their stated intent.
            _dequeueExit(lender, marketId_);
        }
    }

    /// @dev Thin wrapper — the swap-and-pop body lives in PoolLogicLib (DELEGATECALL) to keep this
    ///      contract under the EIP-170 limit, same as finalizeMarketDustCore. See
    ///      PoolLogicLib.dequeueExit for why popping eagerly is load-bearing rather than tidiness.
    function _dequeueExit(address lender, uint256 marketId_) internal {
        PoolLogicLib.dequeueExit(marketExitQueue[marketId_], inExitQueue[marketId_], exitQueueIndex[marketId_], lender, marketId_);
    }

    /// @notice Pop up to `maxIter` stale entries off a market's exit queue tail. Recovery path for
    ///         queues already inflated under the pre-upgrade implementation; bounded and repeatable
    ///         so a queue too long for one settlement transaction can be ground down across several
    ///         calls. Permissionless — see PoolLogicLib.pruneExitQueue.
    /// @dev No marketId bounds check: an unknown market's queue is an empty array, so the call is a
    ///      no-op returning 0. Omitted to conserve EIP-170 headroom, which is scarce here.
    function pruneExitQueue(uint256 marketId_, uint256 maxIter) external nonReentrant returns (uint256) {
        return PoolLogicLib.pruneExitQueue(
            marketExitQueue[marketId_], inExitQueue[marketId_], exitQueueIndex[marketId_], userPositions, marketId_, maxIter
        );
    }

    /// @notice Length of a market's exit queue — lets monitoring alert on growth before a
    ///         settlement transaction is the thing that discovers it.
    function getExitQueueLength(uint256 marketId_) external view returns (uint256) {
        return marketExitQueue[marketId_].length;
    }

    /// @dev Return `amount` of LP funds from fixed market `marketId_` to market 0 via the ledger
    ///      (exit queue first, then LIFO receipts) — fully unbounded, no iteration cap. Drains
    ///      every exit-queue and ledger entry it needs in a single call. If any amount remains
    ///      uncovered after the ledger is fully drained (only pre-ledger allocations left), fall
    ///      back to the global FIFO walk.
    function _deallocate(uint256 marketId_, uint256 amount) internal {
        uint256 rem = PoolLogicLib.deallocateViaLedger(
            markets,
            userPositions,
            userActualAllocation,
            userLockedAllocation,
            allocationLedger[marketId_],
            marketExitQueue[marketId_],
            inExitQueue[marketId_],
            marketId_,
            amount,
            deallocMaxIter
        );
        // Sub-share flooring residue (rem < one share's value) can never be unwound by the fallback:
        // it hits the same _unwindLenderCore floor and moves nothing, while iterating the entire
        // depositorQueue — the permissionless dust-Sybil DoS vector. Once any interest has accrued
        // (rate > 1e18) the double floor leaves such a residue on essentially every deallocation, so
        // gating on `rem == 0` would route almost all repays into the O(depositorQueue) walk. Only a
        // MATERIALLY uncovered remainder (genuine pre-ledger allocations) reaches the
        // fallback; the dust stays as fixed-market shares and is reconciled at close by
        // finalizeMarketDust.
        if (rem <= SUPPLY_DUST_THRESHOLD) return;
        _requireLedgerDrained(marketId_);
        PoolLogicLib.deallocateFundsFromMarket(
            markets, depositorQueue, userPositions, userActualAllocation, userLockedAllocation, marketId_, rem
        );
    }

    /// @dev A material remainder is a genuine PRE-LEDGER allocation only when the ledger walk ran to
    ///      exhaustion. If either source still holds entries the walk stopped early — at
    ///      `deallocMaxIter`, or on the `unwound == 0` break — and that value is still reachable
    ///      through the ledger later. Falling through to the O(depositorQueue) scan in that case is
    ///      the dust-Sybil DoS vector a cap is supposed to avoid, so fail closed instead.
    ///      Unreachable while deallocMaxIter == 0; it becomes load-bearing the moment a cap is set,
    ///      and forces the carry path to be built alongside rather than after.
    function _requireLedgerDrained(uint256 marketId_) internal view {
        if (allocationLedger[marketId_].length != 0 || marketExitQueue[marketId_].length != 0) {
            revert DeallocationIncomplete();
        }
    }

    /// @notice Set the per-call iteration ceiling for ledger deallocation. 0 == uncapped.
    /// @dev A non-zero value bounds gas per settlement call but makes an over-cap settlement REVERT
    ///      (see _requireLedgerDrained) rather than silently scan the depositor queue. Do not raise
    ///      this above 0 until settlement can resume across transactions — a cap alone converts an
    ///      out-of-gas failure into an explicit one, it does not let large settlements complete.
    function setMaxIter(uint256 maxIter_) external onlyOwner {
        emit MaxIterUpdated(deallocMaxIter, maxIter_);
        deallocMaxIter = maxIter_;
    }

    /// @dev Loss-path counterpart to _deallocate, same structure: ledger walk first (exit queue
    ///      then LIFO receipts, fully unbounded, loss already baked into the exchange rate so
    ///      LIFO ordering is neutral), then fall back to the global FIFO walk for any pre-ledger
    ///      remainder. Physical write-down (`physicalToReduce_`) is a precise, externally-known
    ///      figure tied to the liquidation's `physicalBorrowToReduce` — applied exactly once via
    ///      finalizeLossPhysical, regardless of which walk covered the value.
    function _deallocateLoss(uint256 marketId_, uint256 amount, uint256 physicalToReduce_) internal {
        if (markets[marketId_].totalSupplyShares == 0) {
            PoolLogicLib.finalizeLossPhysical(markets, marketId_, physicalToReduce_);
            return;
        }

        uint256 rem = PoolLogicLib.proportionalDeallocateViaLedger(
            markets,
            userPositions,
            userActualAllocation,
            userLockedAllocation,
            allocationLedger[marketId_],
            marketExitQueue[marketId_],
            inExitQueue[marketId_],
            marketId_,
            amount,
            deallocMaxIter
        );
        // Mirror _deallocate: only a MATERIALLY uncovered remainder (genuine pre-ledger allocations)
        // reaches the O(depositorQueue) fallback. Sub-share flooring residue can't be
        // unwound there anyway (same floor moves nothing), so routing it into the unbounded walk is
        // both wasteful and the dust-Sybil DoS vector — it stays as fixed-market shares and is
        // reconciled at close by finalizeMarketDust.
        if (rem > SUPPLY_DUST_THRESHOLD) {
            _requireLedgerDrained(marketId_);
            PoolLogicLib.proportionalDeallocateFundsFromMarket(
                markets, depositorQueue, userPositions, userActualAllocation, userLockedAllocation, marketId_, rem
            );
        }

        PoolLogicLib.finalizeLossPhysical(markets, marketId_, physicalToReduce_);
    }

    function setExposures(uint256[] calldata marketIds_, uint256[] calldata exposures_)
        external
        nonReentrant
        whenNotPaused
    {
        if (marketIds_.length != exposures_.length) revert InvalidMarket();
        // Live-LP check keyed on actual holdings, not totalDepositedAssets (see setExposure).
        if (!_hasAnyLpPosition(msg.sender)) revert InvalidAmount();

        for (uint256 i = 0; i < marketIds_.length; i++) {
            uint256 marketId = marketIds_[i];
            uint256 exposure = exposures_[i];
            if (marketId >= marketCount) revert InvalidMarket();
            if (marketId == 0) revert InvalidMarket();
            if (exposure > 10000) revert InvalidExposure();
            if (!markets[marketId].active) revert MarketNotActive();

            userExposureBps[msg.sender][marketId] = exposure;
            emit ExposureUpdated(msg.sender, marketId, exposure);
            _maybeEnqueueExit(msg.sender, marketId, exposure);
        }
    }

    /// @notice DEPRECATED: Emergency function to reset all user allocations
