    /// @notice Check whether the given LP list can collectively supply `amount_` to `marketId_`.
    /// @param lpAddresses LP addresses to draw from (assumed distinct)
    /// @param amount_ Total amount to allocate to the target market
    /// @param marketId_ Target fixed market ID (must not be market 0)
    /// @return canAllocate true if the list can provide the full amount within all constraints
    /// @dev Logic lives in PoolLogicLib to keep the implementation under the EIP-170 size limit.
    function canAllocateFromLPs(address[] calldata lpAddresses, uint256 amount_, uint256 marketId_)
        public
        view
        returns (bool canAllocate)
    {
        return PoolLogicLib.canAllocateFromLPs(
            markets,
            marketCount,
            userExposureBps,
            userPositions,
            userActualAllocation,
            userLockedAllocation,
            lpAddresses,
            amount_,
            marketId_
        );
    }

    /// @notice Simulate how much would be drawn from each LP to allocate `amount_` to `marketId_`.
    /// @dev Mirrors the greedy fill in _allocateFundsToMarket exactly. perLpAmounts[i] is the amount
    ///      taken from lpAddresses[i]. Assumes distinct LP addresses. Sub-wei differences vs the live
    ///      allocation are possible from exchange-rate drift as funds move market-to-market.
    /// @return perLpAmounts Amount drawn from each LP, index-aligned with lpAddresses
    /// @return totalAllocated Sum of perLpAmounts
    /// @return fullyAllocated true if the list covers the full amount_ (totalAllocated == amount_)
    function previewAllocation(address[] calldata lpAddresses, uint256 amount_, uint256 marketId_)
        external
        view
        returns (uint256[] memory perLpAmounts, uint256 totalAllocated, bool fullyAllocated)
    {
        return PoolLogicLib.previewAllocation(
            markets,
            marketCount,
            userExposureBps,
            userPositions,
            userActualAllocation,
            userLockedAllocation,
            lpAddresses,
            amount_,
            marketId_
        );
    }

    /// @dev Supply exchange rate floored at 1. A total loss can drive totalSupplyAssets to 0 while
    ///      shares are still outstanding; the raw `assets * PRECISION / shares` would then be 0,
    ///      and every deposit/withdraw/allocate that divides by the rate (e.g. share issuance)
    ///      would revert on division-by-zero with no recovery path. Flooring at 1 keeps the market
    ///      usable: the next deposit re-establishes a healthy rate and correctly dilutes the
    ///      loss-bearing legacy shares toward zero value. Callers must ensure shares > 0.
    function _flooredSupplyRate(uint256 totalSupplyAssets_, uint256 totalSupplyShares_)
        internal
        pure
        returns (uint256)
    {
        uint256 rate = (totalSupplyAssets_ * EXCHANGE_RATE_PRECISION) / totalSupplyShares_;
        return rate == 0 ? 1 : rate;
    }

    /// @dev True if the user still holds ANY live LP position: supply shares in any market
    ///      (market 0 or a fixed market) or any locked fixed-market allocation. This is the
    ///      authoritative "is this a live LP?" signal — it is share/value based, unlike
    ///      totalDepositedAssets, which tracks net PRINCIPAL and clamps to 0 once an LP withdraws
    ///      their original deposit even while interest-grown share value remains. Using this for
    ///      the exposure gates and queue removal prevents wrongly locking out / dropping an LP who
    ///      still has funds in the pool (e.g. 100k deposit grown to 105k, then 100k withdrawn
    ///      leaves ~5k in shares but totalDepositedAssets == 0). It also subsumes the earlier
    ///      fixed-market-shares guard so a queue-swap exit's residual accrued-yield shares keep the
    ///      LP reachable by finalizeMarketDust's migration instead of being swept to the protocol.
    function _hasAnyLpPosition(address user_) internal view returns (bool) {
        for (uint256 i = 0; i < marketCount; i++) {
            if (userPositions[user_][i].supplyShares > 0) return true;
            if (userLockedAllocation[user_][i] > 0) return true;
        }
        return false;
    }

    function _removeFromQueue(address user_) internal {
        DepositorPosition storage dp = depositorPositions[user_];
        if (!dp.inQueue) return;
        // Never drop an LP that still holds any position (market-0 shares, fixed-market shares, or
        // locked allocation) — e.g. residual accrued-yield shares after a full-principal withdrawal
        // or a queue-swap exit. They must stay tracked so their value is returned at close.
        if (_hasAnyLpPosition(user_)) return;

        uint256 index = depositorIndex[user_];
        uint256 lastIndex = depositorQueue.length - 1;

        if (index != lastIndex) {
            address lastUser = depositorQueue[lastIndex];
            depositorQueue[index] = lastUser;
            depositorIndex[lastUser] = index;
        }

        depositorQueue.pop();
        delete depositorIndex[user_];
        dp.inQueue = false;
    }

    // ============================================
    // PROTOCOL EARNINGS
    // ============================================

    // The one-time migrateProtocolEarningsToShares(marketId) migration was removed after all
    // deployed markets had been converted from the legacy scalar accounting to protocolSupplyShares.
    // The deprecated `protocolEarnings` / `protocolEarningsAvailable` fields remain in the Market
    // struct as inert storage placeholders (removing them would shift every later storage slot and
    // break the upgradeable layout); nothing reads or writes them anymore. New markets never
    // populate them — interest accrual mints protocolSupplyShares directly.

    /// @notice Redeem protocol supply shares for tokens and send to surgeWallet.
    ///         Accrues interest first so shares are valued at the latest rate.
    function withdrawProtocolShares(uint256 marketId_, uint256 shares_) external onlyOwner nonReentrant {
        if (marketId_ >= marketCount) revert InvalidMarket();

        _accrueMarketInterest(marketId_);

        Market storage market = markets[marketId_];
        if (shares_ == 0 || shares_ > market.protocolSupplyShares) revert InvalidAmount();

        uint256 tokenAmount =
            market.totalSupplyShares > 0 ? (shares_ * market.totalSupplyAssets) / market.totalSupplyShares : 0;
        if (tokenAmount == 0) revert InvalidAmount();

        // Only withdraw against available cash liquidity, never funds currently lent out.
        uint256 available = market.totalPhysicalSupply > market.totalPhysicalBorrow
            ? market.totalPhysicalSupply - market.totalPhysicalBorrow
            : 0;
        if (tokenAmount > available) revert InsufficientLiquidity();

        market.protocolSupplyShares -= shares_;
        market.totalSupplyShares -= shares_;
        market.totalSupplyAssets = market.totalSupplyAssets >= tokenAmount ? market.totalSupplyAssets - tokenAmount : 0;
        market.totalPhysicalSupply =
            market.totalPhysicalSupply >= tokenAmount ? market.totalPhysicalSupply - tokenAmount : 0;

        if (market.totalSupplyShares > 0) {
            market.supplyExchangeRate = _flooredSupplyRate(market.totalSupplyAssets, market.totalSupplyShares);
        }

        IERC20(market.token).safeTransfer(surgeWallet, tokenAmount);
        emit ProtocolSharesWithdrawn(marketId_, shares_, tokenAmount);
    }

    /// @notice Get protocol supply shares for a market
    function getProtocolSupplyShares(uint256 marketId_) external view returns (uint256) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        return markets[marketId_].protocolSupplyShares;
    }

    // @notice DEPRECATED: Emergency function to correct totalPhysicalSupply accounting
    // @dev This function is deprecated due to lack of validation and audit trail.
    //      Kept for ABI compatibility only. Always reverts.
    // @param marketId_ Market to correct (unused)
    // @param amount_ Amount to add (unused)
    // function emergencyCorrectPhysicalSupply(
    //     uint256 marketId_,
    //     uint256 amount_
    // ) external onlyOwner {
    //     revert("Function deprecated - contact admin for accounting corrections");
    // }

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    /// @notice Get user's claimable supply amount
    function getUserSupplyAmount(address user_, uint256 marketId_) external view returns (uint256) {
        Market storage market = markets[marketId_];
        UserPosition storage position = userPositions[user_][marketId_];

        return (position.supplyShares * market.supplyExchangeRate) / EXCHANGE_RATE_PRECISION;
    }

    /// @notice Get user's borrowed amount
    function getUserBorrowAmount(address user_, uint256 marketId_) external view returns (uint256) {
        Market storage market = markets[marketId_];
        UserPosition storage position = userPositions[user_][marketId_];

        return (position.borrowShares * market.borrowExchangeRate) / EXCHANGE_RATE_PRECISION;
    }

    /// @notice Get available liquidity in a market
    function getAvailableLiquidity(uint256 marketId_) external view returns (uint256) {
        Market storage market = markets[marketId_];

        return market.totalPhysicalSupply > market.totalPhysicalBorrow
            ? market.totalPhysicalSupply - market.totalPhysicalBorrow
            : 0;
    }

    /// @notice Get market utilization in bps = totalBorrowAssets / totalSupplyAssets (both interest-inclusive)
    function getUtilization(uint256 marketId_) external view returns (uint256) {
        Market storage market = markets[marketId_];

        if (market.totalSupplyAssets == 0) return 0;

        return (market.totalBorrowAssets * BPS_DENOMINATOR) / market.totalSupplyAssets;
    }

    /// @notice Get market's max LTV (for VaultManager compatibility)
    function getMarketMaxLTV(uint256 marketId_) external view returns (uint256) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        return markets[marketId_].maxLtvBps;
    }

    /// @notice Check whether a market is active (for VaultManager compatibility)
    function isMarketActive(uint256 marketId_) external view returns (bool) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        return markets[marketId_].active;
    }

    /// @notice Get market's liquidation threshold (for VaultManager compatibility)
    function getMarketLiquidationThreshold(uint256 marketId_) external view returns (uint256) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        return markets[marketId_].liquidationThresholdBps;
    }

    /// @notice Get market's borrow exchange rate (for shares-based debt calculation)
    function getMarketBorrowExchangeRate(uint256 marketId_) external view returns (uint256) {
        if (marketId_ >= marketCount) revert InvalidMarket();
        return markets[marketId_].borrowExchangeRate;
    }

    /// @notice Project the borrow exchange rate to the current timestamp without accruing state.
    ///         Use this for frontend display of live debt — returns the same value
    ///         _accrueMarketInterest would write, but as a pure view (zero gas overhead).
    function getProjectedBorrowExchangeRate(uint256 marketId_) external view returns (uint256) {
        return PoolLogicLib.projectedBorrowExchangeRate(markets, marketCount, marketId_);
    }

    /// @notice Get market's current borrow rate from its provider (read-only, never updates state).
    ///         Tries getBorrowRateView first; falls back to getBorrowRate staticcall for providers
    ///         deployed before the getBorrowRateView interface was introduced.
    function getMarketBorrowRate(uint256 marketId_) external view returns (uint256) {
        return PoolLogicLib.marketBorrowRate(markets, marketCount, marketId_);
    }

    /// @notice Get maximum borrowable amount from a market_getCurrentDebtFromShares
    /// @param marketId_ Market ID to check
    /// @return maxAmount Maximum amount that can be borrowed
    function getMaxBorrowAmount(uint256 marketId_) external view returns (uint256 maxAmount) {
        return PoolLogicLib.maxBorrowAmount(
            markets, marketCount, depositorQueue, userExposureBps, userPositions, userActualAllocation, marketId_
        );
    }

    // ============================================
    // INTERNAL HELPERS
    // ============================================

    /// @dev Single source of truth for compound interest calculation.
    ///      Used by both _accrueMarketInterest (settlement) and getProjectedBorrowExchangeRate
    ///      (view preview) so the two can never silently diverge if the rate model changes.
    function _computeBorrowInterest(uint256 assets_, uint256 rateBps_, uint256 elapsed_)
        internal
        pure
        returns (uint256)
    {
        uint256 ratePerSecondWad =
            (rateBps_ * EXCHANGE_RATE_PRECISION) / (BPS_DENOMINATOR * SECONDS_PER_YEAR);
        return (assets_ * TaylorMath.wTaylorCompounded(ratePerSecondWad, elapsed_)) / EXCHANGE_RATE_PRECISION;
    }

    /// @dev Rounds up: (a * b + d - 1) / d
    /// @notice Used for share burns to ensure we always burn enough shares to cover the amount
    function _mulDivUp(uint256 a, uint256 b, uint256 d) internal pure returns (uint256) {
        if (a == 0 || b == 0) return 0;
        uint256 p = a * b;
        return ((p - 1) / d) + 1;
    }

    /// @dev Checks with VaultManager whether a market still has active debt positions.
    ///      If call fails, assume active debt exists (safer than auto-closing).
    function _vaultManagerHasActiveDebtInMarket(uint256 marketId_) internal view returns (bool hasActiveDebt_) {
        (bool ok, bytes memory data) =
            vaultManager.staticcall(abi.encodeWithSignature("hasActiveDebtInMarket(uint256)", marketId_));
        if (!ok || data.length < 32) return true;
        hasActiveDebt_ = abi.decode(data, (bool));
    }

    // ============================================
    // ADMIN FUNCTIONS
    // ============================================

    function setSurgeWallet(address surgeWallet_) external onlyOwner {
        if (surgeWallet_ == address(0)) revert InvalidAddress();
        address oldSurgeWallet = surgeWallet;
        surgeWallet = surgeWallet_;
        emit SurgeWalletUpdated(oldSurgeWallet, surgeWallet_);
    }

    function setVaultManager(address vaultManager_) external onlyOwner {
        if (vaultManager_ == address(0)) revert InvalidAddress();
        address oldVaultManager = vaultManager;
        vaultManager = vaultManager_;
        emit VaultManagerUpdated(oldVaultManager, vaultManager_);
    }

    /// @notice Set the operational admin (distinct from owner). Owner-only.
    function setAdmin(address admin_) external onlyOwner {
        if (admin_ == address(0)) revert InvalidAddress();
        address oldAdmin = admin;
        admin = admin_;
        emit AdminUpdated(oldAdmin, admin_);
    }

    /// @notice Propose a new pause manager (two-step transfer)
    function proposePauseManager(address newPauseManager_) external onlyOwner {
        if (newPauseManager_ == address(0)) revert InvalidAddress();
        if (newPauseManager_ == pauseManager) revert InvalidAddress();
        pendingPauseManager = newPauseManager_;
        emit PauseManagerProposed(pauseManager, newPauseManager_);
    }

    /// @notice Accept pause manager role (must be called by proposed address)
    function acceptPauseManager() external {
        if (msg.sender != pendingPauseManager) revert Unauthorized();
        address previous = pauseManager;
        pauseManager = msg.sender;
        pendingPauseManager = address(0);
        emit PauseManagerAccepted(previous, msg.sender);
    }

    /// @notice Pause critical operations (deposits, borrows, liquidations)
    /// @dev Withdrawals and repayments remain enabled during pause
    function pause() external onlyPauseManager {
        _pause();
    }

    /// @notice Unpause all operations
    function unpause() external onlyPauseManager {
        _unpause();
    }

    function adminSetMarketActive(uint256 marketId_, bool active_) external onlyOwner {
        if (marketId_ >= marketCount) revert InvalidMarket();

        // Providers are permanently bound to the market they were assigned to (see createMarket/
        // setMarketProvider); toggling `active` never frees or reclaims a provider, so no re-check
        // is needed here. Kept as a no-op branch for clarity/history.
        markets[marketId_].active = active_;
        emit MarketStatusChanged(marketId_, active_);
    }

    /// @notice Update the market provider for an existing market
    /// @dev Use with caution - changing provider affects interest rates for all positions
    /// @param marketId_ Market ID to update
    /// @param newProvider_ New market provider address
    function setMarketProvider(uint256 marketId_, address newProvider_) external onlyOwner {
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (newProvider_ == address(0)) revert InvalidMarket();

        // Check if new provider is already bound to another market, active or not
        // (prevents rateAtTarget cross-contamination via deactivate/reassign/reactivate)
        for (uint256 i = 0; i < marketCount; i++) {
            if (i != marketId_ && address(markets[i].provider) == newProvider_) {
                revert ProviderAlreadyInUse();
            }
        }

        _accrueMarketInterest(marketId_);

        Market storage market = markets[marketId_];
        address oldProvider = address(market.provider);
        market.provider = IMarketProvider(newProvider_);

        // Sync the INCOMING provider's rate clock to now. Its lastRateUpdate is still the value set
        // in its constructor, so without this the first post-swap accrual computes
        // elapsed = block.timestamp - constructorTimestamp and replays the entire deploy-to-execute
        // gap as one exponential drift jump, mispricing borrow interest. liquidity_ == 0
        // short-circuits every drift path (rateAtTarget returned unchanged), so this only advances
        // lastRateUpdate; it does not move the anchor. It also reverts (onlyPool) if newProvider_ was
        // constructed for a different pool, so a mis-bound provider can never be silently installed
        // and brick every future _accrueMarketInterest.
        market.provider.getBorrowRate(0, 0);

        // Market 0 is the base variable market that all deposits/withdrawals and every fixed market's
        // supply rate depend on, so hold it to a stricter bar: the provider must be a live,
        // clock-advancing (adaptive) provider. A fixed provider that no-ops getBorrowRate would leave
        // the clock stale and silently break the variable-rate mechanism — this check rejects it.
        if (marketId_ == 0) {
            require(IClockedProvider(newProvider_).lastRateUpdate() == block.timestamp, "market 0 clock not synced");
        }

        emit MarketProviderUpdated(marketId_, oldProvider, newProvider_);
    }

    function setMarketReserveRate(uint256 marketId_, uint256 reserveRateBps_) external onlyOwner {
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (reserveRateBps_ > BPS_DENOMINATOR) revert InvalidMarket();

        _accrueMarketInterest(marketId_);

        Market storage market = markets[marketId_];
        uint256 old = market.reserveRateBps;
        market.reserveRateBps = reserveRateBps_;

        emit MarketReserveRateUpdated(marketId_, old, reserveRateBps_);
    }

    function setMarketMaxLTV(uint256 marketId_, uint256 maxLtvBps_) external onlyOwner {
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (maxLtvBps_ == 0 || maxLtvBps_ > BPS_DENOMINATOR) revert InvalidMarket();

        Market storage market = markets[marketId_];
        if (maxLtvBps_ >= market.liquidationThresholdBps) revert InvalidAmount();

        uint256 old = market.maxLtvBps;
        market.maxLtvBps = maxLtvBps_;

        emit MarketMaxLTVUpdated(marketId_, old, maxLtvBps_);
    }

    function setMarketLiquidationThreshold(uint256 marketId_, uint256 liquidationThresholdBps_) external onlyOwner {
        if (marketId_ >= marketCount) revert InvalidMarket();
        if (liquidationThresholdBps_ == 0 || liquidationThresholdBps_ > BPS_DENOMINATOR) revert InvalidMarket();

        _accrueMarketInterest(marketId_);

        Market storage market = markets[marketId_];
        if (market.maxLtvBps >= liquidationThresholdBps_) revert InvalidAmount();

        uint256 old = market.liquidationThresholdBps;
        market.liquidationThresholdBps = liquidationThresholdBps_;

        emit MarketLiquidationThresholdUpdated(marketId_, old, liquidationThresholdBps_);
    }
}

src/VaultManagerUpgradeable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {HelpersUpgradeable} from "./common/HelpersUpgradeable.sol";
import {ErrorTypes} from "./libraries/ErrorTypes.sol";

interface IERC721 {
    function ownerOf(uint256 tokenId) external view returns (address owner);
}

interface IERC3009 {
    /// @dev Intentionally NOT using transferWithAuthorization: it is permissionless
    /// (any address can relay a valid signature to the token contract), which lets an
    /// attacker front-run the VaultManager's own call, burn the authorization nonce,
    /// and strand the transferred funds in this contract with no accounting update.
    /// receiveWithAuthorization enforces `msg.sender == to` on compliant tokens
    /// (e.g. USDC), so only this contract can ever execute the transfer.
    function receiveWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external;
}

interface IAuctionHouse {
    function createAuction(
        uint256 nftId_,
        address token_,
        uint256 debtToPay_,
        uint256 collateralSatsForSale_,
        address originalOwner_
    ) external;
}

/// @title VaultManagerUpgradeable (Tick-Based)
/// @notice Main vault contract with tick-based position tracking (upgradeable version)
/// @dev Uses Transparent Proxy pattern for upgradeability
contract VaultManagerUpgradeable is HelpersUpgradeable, PausableUpgradeable {
    /**
     * |
     * |        State Variables            |
     * |__________________________________
     */
    /// @notice Nonces for EIP-712 signatures (replay protection)
    mapping(address => uint256) public nonces;

    /// @notice EIP-712 domain separator (computed on initialize, not immutable)
    bytes32 private _domainSeparator;

    /// @notice EIP-712 typehash for repayWithERC3009Single
    bytes32 public constant REPAY_WITH_ERC3009_TYPEHASH = keccak256(
        "RepayWithERC3009(uint256 nftId,uint256 amount,uint256 deadline,uint256 validAfter,uint256 validBefore,bytes32 transferNonce,uint256 nonce)"
    );

    /// @notice EIP-712 typehash for withdrawCollateralWithAuthorization
    bytes32 public constant WITHDRAW_COLLATERAL_TYPEHASH =
        keccak256("WithdrawCollateral(uint256 nftId,uint256 withdrawSats,uint256 deadline,uint256 nonce)");

    /// @notice EIP-712 typehash for requestCreditLineExtension
    bytes32 public constant EXTEND_CREDIT_LINE_TYPEHASH =
        keccak256("RequestCreditLineExtension(uint256 nftId,uint256 deadline,uint256 nonce)");

    /// @notice Pending withdrawal requests (nftId => withdrawSats)
    mapping(uint256 => uint256) public pendingWithdrawals;

    /// @notice Positions in liquidation (nftId => inLiquidation)
    mapping(uint256 => bool) public inLiquidation;

    /// @notice AuctionHouse contract address
    address public auctionHouse;

    /// @notice Old VaultManager contract address for migration
    address public oldVaultManager;

    /// @notice Track migrated positions to prevent duplicate migration
    mapping(uint256 => bool) public isMigrated;

    /// @notice Liquidation type
    enum LiquidationType {
        FullLiquidation,
        Delinquency
    }

    /// @notice Collateral update type — controls validation inside _addCollateral
    enum CollateralUpdateType {
        AddCollateral,
        ExitBlockUpdate
    }

    /// @notice Liquidation details structure
    struct LiquidationDetails {
        uint256 collateralSats;
        uint256 debtStable;
        uint256 liquidationPenalty;
        uint256 collateralToLiquidate;
        uint256 timestamp;
        bool isActive;
        uint256 marketId;
        LiquidationType liquidationType;
    }

    /// @notice Track liquidation details for each position (nftId => LiquidationDetails)
    mapping(uint256 => LiquidationDetails) public liquidationDetails;

    /// @notice Old LiquidityPool for legacy position repayments
    address private _oldLiquidityPool;

    /// @notice Market ID for each position (0 = Primary/Variable, 1 = Secondary/Fixed, etc.)
    /// nftId => marketId
    /// NOTE: Added in upgrade - type(uint256).max marks legacy positions
    mapping(uint256 => uint256) public positionMarket;

    /**
     * |
     * |            Modifiers              |
     * |__________________________________
     */
    modifier onlyPauseManager() {
        if (msg.sender != pauseManager) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyAdmin);
        }
        _;
    }

    /**
     * |
     * |           Constructor             |
     * |__________________________________
     */
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * |
     * |           Initializer             |
     * |__________________________________
     */
    /// @notice Initialize the contract (replaces constructor)
    /// @param admin_ Admin address (MPC signer)
    /// @param positionNFT_ Position NFT contract address
    /// @param oracle_ Oracle contract address
    /// @param liquidityPool_ Liquidity pool contract address
    /// @param liqPenaltyBps_ Liquidation penalty (800 = 8%)
    function initialize(
        address admin_,
        address positionNFT_,
        address oracle_,
        address liquidityPool_,
        uint256 liqPenaltyBps_
    ) external initializer {
        __Helpers_init(admin_, positionNFT_, oracle_, liquidityPool_);
        __Pausable_init();

        // Initialize EIP-712 domain separator
        _domainSeparator = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("SurgeVaultManager")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );

        // Initialize vaultVars with parameters
        vaultVars = (liqPenaltyBps_ << 193);
    }

    /**
     * |
     * |         Admin Functions           |
     * |__________________________________
     */
    /// @notice Admin creates a loan position for a user
    /// @param marketId_ Market ID to borrow from (0 = Primary/Variable, 1 = Secondary/Fixed)
    function createLoan(
        address user_,
        uint256 collateralSats_,
        uint256 debtStable_,
        address token_,
        uint256 durationDays_,
        bytes32 btcPubkey_,
        uint256 marketId_,
        uint256 exitBlock_,
        address[] calldata lpAddresses
    ) external onlyAdmin nonReentrant whenNotPaused returns (uint256 nftId_) {
        if (collateralSats_ == 0 || debtStable_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (positionBorrowCap > 0) {
            if (debtStable_ > positionBorrowCap) {
                revert SurgeVaultError(ErrorTypes.VaultManager__BorrowCapExceeded);
            }
        }

        // Get market's max LTV from liquidity pool
        (bool success, bytes memory data) =
            _liquidityPool.staticcall(abi.encodeWithSignature("getMarketMaxLTV(uint256)", marketId_));
        require(success && data.length > 0, "Failed to get market LTV");
        uint256 maxLtvBps = abi.decode(data, (uint256));

        // Convert LTV to min collateral ratio (LTV 80% = 8000 bps = 125% CR = 12500 bps)
        uint256 minCR = (10000 * 10000) / maxLtvBps;

        uint256 btcPrice = _getOraclePrice();
        _checkCollateralRatio(collateralSats_, debtStable_, btcPrice, minCR);

        int24 tick = _getTickAtRatio(collateralSats_, debtStable_, btcPrice);

        (bool successMint, bytes memory dataMint) = _positionNFT.call(abi.encodeWithSignature("mint(address)", user_));
        require(successMint, "NFT mint failed");
        nftId_ = abi.decode(dataMint, (uint256));

        positionData[nftId_] = _packPositionData(collateralSats_, debtStable_, 1);
        positionToken[nftId_] = token_;
        positionMarket[nftId_] = marketId_;
        marketActiveDebtCount[marketId_]++;
        loanExpiry[nftId_] = block.timestamp + (durationDays_ * 1 days);
        positionBtcPubkey[nftId_] = btcPubkey_;
        positionExitBlock[nftId_] = exitBlock_;
        tickPositions[nftId_][0] = _packTickPosition(tick, collateralSats_, debtStable_);

        _updateTickData(tick, int256(debtStable_));
        _updateVaultTotals(int256(collateralSats_), int256(debtStable_));

        (bool success2, bytes memory borrowData) = _liquidityPool.call(
            abi.encodeWithSignature("borrow(address,address,uint256,uint256,address[])", token_, user_, debtStable_, marketId_, lpAddresses)
        );
        require(success2, "Liquidity borrow failed");
        positionBorrowShares[nftId_] = abi.decode(borrowData, (uint256));

        emit LogLoanCreated(nftId_, user_, collateralSats_, debtStable_, token_, btcPubkey_);
    }

    /// @notice Admin updates collateral for existing position
    function addCollateral(uint256 nftId_, uint256 newCollateralSats_) external onlyAdmin nonReentrant {
        _addCollateral(nftId_, newCollateralSats_, CollateralUpdateType.AddCollateral);
    }

    /// @dev Internal collateral top-up — shared by addCollateral and any internal logic that needs to increase collateral.
    ///      ExitBlockUpdate skips the "new must exceed current" check.
    function _addCollateral(uint256 nftId_, uint256 newCollateralSats_, CollateralUpdateType updateType_) internal {
        if (newCollateralSats_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        _accruePositionInterest(nftId_);

        (bool isActive, uint256 collateralSats, uint256 debtStable,, uint256 tickCount) =
            _unpackPositionData(positionData[nftId_]);

        if (!isActive) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionNotActive);
        }

        if (updateType_ == CollateralUpdateType.AddCollateral) {
            if (newCollateralSats_ <= collateralSats && collateralSats != 0) {
                revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
            }
        }

        int256 collateralDiff = int256(newCollateralSats_) - int256(collateralSats);
        positionData[nftId_] = _packPositionData(newCollateralSats_, debtStable, tickCount);

        (bool tickActive, int24 tick, uint256 tickColl, uint256 tickDebt,) =
            _unpackTickPosition(tickPositions[nftId_][0]);

        if (tickActive) {
            uint256 newTickColl;
            if (collateralDiff >= 0) {
                newTickColl = tickColl + uint256(collateralDiff);
            } else {
                uint256 reduction = uint256(-collateralDiff);
                newTickColl = tickColl >= reduction ? tickColl - reduction : 0;
            }
            tickPositions[nftId_][0] = _packTickPosition(tick, newTickColl, tickDebt);
        }

        _updateVaultTotals(collateralDiff, 0);
        if (updateType_ == CollateralUpdateType.AddCollateral) {
            emit LogCollateralAdded(nftId_, uint256(collateralDiff), newCollateralSats_);
        } else {
            emit LogCollateralRefreshed(nftId_, collateralDiff, newCollateralSats_);
        }
    }

    /// @notice Set auction house contract address
    function setAuctionHouse(address auctionHouse_) external onlyAdmin {
        if (auctionHouse_ == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAddress);
