        auctionHouse = auctionHouse_;
        emit LogAuctionHouseSet(auctionHouse_);
    }

    /// @notice Update liquidation penalty
    /// @param liqPenaltyBps_ New liquidation penalty in basis points (e.g., 800 = 8%)
    function setLiquidationPenalty(uint256 liqPenaltyBps_) external onlyAdmin {
        if (liqPenaltyBps_ > 10000) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        // Update liquidation penalty in vaultVars (bits 193-208)
        uint256 vars = vaultVars;
        uint256 mask = uint256((1 << 16) - 1) << 193;
        vars = (vars & ~mask) | (liqPenaltyBps_ << 193);
        vaultVars = vars;
        emit LogLiquidationPenaltySet(liqPenaltyBps_);
    }

