    /// @notice Propose a new admin
    function proposeAdmin(address newAdmin_) external onlyAdmin {
        if (newAdmin_ == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAddress);
        }

        address currentAdminAddr = currentAdmin == address(0) ? _admin : currentAdmin;
        if (newAdmin_ == currentAdminAddr) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAddress);
        }

        pendingAdmin = newAdmin_;
        emit LogAdminTransferProposed(currentAdminAddr, newAdmin_);
    }

    /// @notice Accept admin role
    function acceptAdmin() external {
        if (msg.sender != pendingAdmin) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyAdmin);
        }

        address previousAdmin = currentAdmin == address(0) ? _admin : currentAdmin;
        currentAdmin = msg.sender;
        pendingAdmin = address(0);

        emit LogAdminTransferAccepted(previousAdmin, msg.sender);
    }

    /// @notice Propose a new pause manager (two-step transfer)
    function proposePauseManager(address newPauseManager_) external onlyAdmin {
        if (newPauseManager_ == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAddress);
        }
        if (newPauseManager_ == pauseManager) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAddress);
        }
        pendingPauseManager = newPauseManager_;
        emit LogPauseManagerProposed(pauseManager, newPauseManager_);
    }

    /// @notice Accept pause manager role (must be called by proposed address)
    function acceptPauseManager() external {
        if (msg.sender != pendingPauseManager) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyAdmin);
        }
        address previous = pauseManager;
        pauseManager = msg.sender;
        pendingPauseManager = address(0);
        emit LogPauseManagerAccepted(previous, msg.sender);
    }

    /// @notice Pause critical operations (withdrawals and liquidations)
    /// @dev Repayments and admin functions remain enabled during pause
    function pause() external onlyPauseManager {
        _pause();
    }

    /// @notice Unpause all operations
    function unpause() external onlyPauseManager {
        _unpause();
    }

