    /// @notice Confirm collateral withdrawal after BTC release
    function confirmWithdrawal(uint256 nftId_) external onlyAdmin nonReentrant {
        if (inLiquidation[nftId_]) revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        uint256 withdrawSats = pendingWithdrawals[nftId_];

        if (withdrawSats == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        _accruePositionInterest(nftId_);

        (bool isActive, uint256 collateralSats, uint256 debtStable,, uint256 tickCount) =
            _unpackPositionData(positionData[nftId_]);

        uint256 newCollateralSats = collateralSats - withdrawSats;
        uint256 packed = _packPositionData(newCollateralSats, debtStable, tickCount);
        positionData[nftId_] = isActive ? packed : packed & ~uint256(1);

        (bool tickActive, int24 tick, uint256 tickColl, uint256 tickDebt,) =
            _unpackTickPosition(tickPositions[nftId_][0]);

        if (tickActive && tickColl >= withdrawSats) {
            uint256 newTickColl = tickColl - withdrawSats;
            tickPositions[nftId_][0] = _packTickPosition(tick, newTickColl, tickDebt);
        }

        _updateVaultTotals(-int256(withdrawSats), 0);
        pendingWithdrawals[nftId_] = 0;

        emit LogCollateralWithdrawn(nftId_, withdrawSats, newCollateralSats);
    }

    /// @notice Cancel pending withdrawal
    function cancelWithdrawal(uint256 nftId_) external onlyAdmin nonReentrant {
        uint256 withdrawSats = pendingWithdrawals[nftId_];

        if (withdrawSats == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        pendingWithdrawals[nftId_] = 0;
        emit LogCollateralWithdrawalCancelled(nftId_, withdrawSats);
    }

    /// @notice Admin allows user to borrow more
    function borrowMore(uint256 nftId_, uint256 additionalDebt_, address[] calldata lpAddresses) external onlyAdmin nonReentrant whenNotPaused {
        if (additionalDebt_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        if (pendingWithdrawals[nftId_] > 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (pendingExtension[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PendingExtension);
        }

        // Prevent borrowMore on legacy positions (must migrate via switchMarket first)
        if (_isLegacyMarket(positionMarket[nftId_])) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        (bool success, bytes memory data) = _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(success, "Owner check failed");
        address owner = abi.decode(data, (address));

        // Accrue LP interest first so _accruePositionInterest reads a fresh exchange rate.
        uint256 borrowMoreMarketId = positionMarket[nftId_];
        if (!_isLegacyMarket(borrowMoreMarketId)) {
            (bool accrueOk,) =
                _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", borrowMoreMarketId));
            require(accrueOk, "Market accrue failed");
        }
        uint256 currentDebt = _accruePositionInterest(nftId_);

        (bool isActive, uint256 collateralSats, uint256 debtStable,, uint256 tickCount) =
            _unpackPositionData(positionData[nftId_]);

        if (!isActive) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionNotActive);
        }

        if (positionBorrowCap > 0) {
            if (currentDebt + additionalDebt_ > positionBorrowCap) {
                revert SurgeVaultError(ErrorTypes.VaultManager__BorrowCapExceeded);
            }
        }

        // Get market's max LTV from liquidity pool
        uint256 marketId = positionMarket[nftId_];
        (bool successLtv, bytes memory dataLtv) =
            _liquidityPool.staticcall(abi.encodeWithSignature("getMarketMaxLTV(uint256)", marketId));
        require(successLtv && dataLtv.length > 0, "Failed to get market LTV");
        uint256 maxLtvBps = abi.decode(dataLtv, (uint256));

        // Convert LTV to min collateral ratio
        uint256 minCR = (10000 * 10000) / maxLtvBps;

        // Health check uses live debt (shares × rate) for new positions, stored debt for legacy
        uint256 liveDebt = currentDebt > 0 ? currentDebt : debtStable;
        uint256 newDebt = liveDebt + additionalDebt_;
        uint256 btcPrice = _getOraclePrice();

        _checkCollateralRatio(collateralSats, newDebt, btcPrice, minCR);

        int24 newTick = _getTickAtRatio(collateralSats, newDebt, btcPrice);
        tickPositions[nftId_][tickCount] = _packTickPosition(newTick, 0, additionalDebt_);
        _updateTickData(newTick, int256(additionalDebt_));

        // positionData.debtStable tracks principal; add new principal for new positions
        uint256 newPrincipal = debtStable + additionalDebt_;
        positionData[nftId_] = _packPositionData(collateralSats, newPrincipal, tickCount + 1);
        // Mirror the decrement condition: only increment if BOTH principal and shares are 0
        if (debtStable == 0 && positionBorrowShares[nftId_] == 0) {
            marketActiveDebtCount[marketId]++;
        }
        _updateVaultTotals(0, int256(additionalDebt_));

        address token = positionToken[nftId_];
        (bool success2, bytes memory borrowData2) = _liquidityPool.call(
            abi.encodeWithSignature("borrow(address,address,uint256,uint256,address[])", token, owner, additionalDebt_, marketId, lpAddresses)
        );
        require(success2, "Liquidity borrow failed");
        positionBorrowShares[nftId_] += abi.decode(borrowData2, (uint256));

        emit LogBorrowMore(nftId_, additionalDebt_, newDebt);
    }

    /// @notice Switch position to a different market (only when debt is 0)
    /// @param nftId_ Position NFT ID
    /// @param newMarketId_ New market ID to switch to
    function switchMarket(uint256 nftId_, uint256 newMarketId_) external onlyAdmin nonReentrant {
        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        (bool isActive,, uint256 debtStable,,) = _unpackPositionData(positionData[nftId_]);

        if (!isActive) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionNotActive);
        }

        // Can only switch markets when debt is 0
        // For new positions check shares; for legacy check stored debtStable
        bool isLegacySwitch = _isLegacyMarket(positionMarket[nftId_]);
        bool hasDebt = isLegacySwitch ? (debtStable != 0) : (positionBorrowShares[nftId_] != 0);
        if (hasDebt) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        // Verify new market exists
        (bool success, bytes memory data) =
            _liquidityPool.staticcall(abi.encodeWithSignature("getMarketMaxLTV(uint256)", newMarketId_));
        require(success && data.length > 0, "Invalid market");

        // Verify new market is active
        (bool activeSuccess, bytes memory activeData) =
            _liquidityPool.staticcall(abi.encodeWithSignature("isMarketActive(uint256)", newMarketId_));
        require(activeSuccess && activeData.length > 0, "Invalid market");
        if (!abi.decode(activeData, (bool))) {
            revert SurgeVaultError(ErrorTypes.VaultManager__MarketNotActive);
        }

        uint256 oldMarketId = positionMarket[nftId_];
        positionMarket[nftId_] = newMarketId_;

        emit LogMarketSwitched(nftId_, oldMarketId, newMarketId_);
    }

    /**
     * |
     * |          User Functions           |
     * |__________________________________
     */
    /// @notice User requests collateral withdrawal
    function withdrawCollateral(uint256 nftId_, uint256 withdrawSats_) external nonReentrant whenNotPaused {
        if (withdrawSats_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        (bool success, bytes memory data) = _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(success, "Owner check failed");
        address owner = abi.decode(data, (address));

        if (owner != msg.sender) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyOwner);
        }

        if (pendingWithdrawals[nftId_] > 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (pendingExtension[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PendingExtension);
        }

        // Accrue LP interest first so _accruePositionInterest reads a fresh exchange rate.
        uint256 withdrawMarketId = positionMarket[nftId_];
        if (!_isLegacyMarket(withdrawMarketId)) {
            (bool accrueOk,) =
                _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", withdrawMarketId));
            require(accrueOk, "Market accrue failed");
        }
        uint256 liveDebt = _accruePositionInterest(nftId_);

        (, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        if (withdrawSats_ > collateralSats) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        uint256 newCollateralSats = collateralSats - withdrawSats_;

        if (liveDebt > 0) {
            if (newCollateralSats == 0) {
                revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
            }

            uint256 btcPrice = _getOraclePrice();
            uint256 mktId = positionMarket[nftId_];
            (bool okLtv, bytes memory dLtv) =
                _liquidityPool.staticcall(abi.encodeWithSignature("getMarketMaxLTV(uint256)", mktId));
            require(okLtv && dLtv.length > 0, "Failed to get market LTV");
            uint256 minCR = (10000 * 10000) / abi.decode(dLtv, (uint256));
            _checkCollateralRatio(newCollateralSats, liveDebt, btcPrice, minCR);
        }

        pendingWithdrawals[nftId_] = withdrawSats_;
        bytes32 btcPubkey = positionBtcPubkey[nftId_];
        emit LogCollateralWithdrawalRequested(nftId_, withdrawSats_, btcPubkey);
    }

    /// @notice User requests collateral withdrawal with EIP-712 authorization
    function withdrawCollateralWithAuthorization(
        uint256 nftId_,
        uint256 withdrawSats_,
        uint256 deadline_,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant whenNotPaused {
        if (withdrawSats_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        if (block.timestamp > deadline_) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        (bool success, bytes memory data) = _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(success, "Owner check failed");
        address owner = abi.decode(data, (address));

        uint256 nonce = nonces[owner];

        bytes32 structHash =
            keccak256(abi.encode(WITHDRAW_COLLATERAL_TYPEHASH, nftId_, withdrawSats_, deadline_, nonce));

        bytes32 digest = keccak256(abi.encodePacked("\u0019\u0001", DOMAIN_SEPARATOR(), structHash));

        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidSignature);
        }

        address signer = ecrecover(digest, v, r, s);

        if (signer == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyOwner);
        }

        if (signer != owner) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyOwner);
        }

        nonces[owner]++;

        if (pendingWithdrawals[nftId_] > 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (pendingExtension[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PendingExtension);
        }

        // Accrue LP interest first so _accruePositionInterest reads a fresh exchange rate.
        uint256 withdrawAuthMarketId = positionMarket[nftId_];
        if (!_isLegacyMarket(withdrawAuthMarketId)) {
            (bool accrueOk,) =
                _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", withdrawAuthMarketId));
            require(accrueOk, "Market accrue failed");
        }
        uint256 liveDebt2 = _accruePositionInterest(nftId_);

        (, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        if (withdrawSats_ > collateralSats) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        uint256 newCollateralSats = collateralSats - withdrawSats_;

        if (liveDebt2 > 0) {
            if (newCollateralSats == 0) {
                revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
            }

            uint256 btcPrice = _getOraclePrice();
            uint256 mktId2 = positionMarket[nftId_];
            (bool okLtv2, bytes memory dLtv2) =
                _liquidityPool.staticcall(abi.encodeWithSignature("getMarketMaxLTV(uint256)", mktId2));
            require(okLtv2 && dLtv2.length > 0, "Failed to get market LTV");
            uint256 minCR = (10000 * 10000) / abi.decode(dLtv2, (uint256));
            _checkCollateralRatio(newCollateralSats, liveDebt2, btcPrice, minCR);
        }

        pendingWithdrawals[nftId_] = withdrawSats_;
        bytes32 btcPubkey = positionBtcPubkey[nftId_];
        emit LogCollateralWithdrawalRequested(nftId_, withdrawSats_, btcPubkey);
    }

    /// @notice User repays debt with ERC-3009 gasless transfer
    function repayWithERC3009Single(
        uint256 nftId_,
        uint256 amount_,
        uint256 deadline_,
        uint256 validAfter_,
        uint256 validBefore_,
        bytes32 transferNonce_,
        uint8 v,
        bytes32 r,
        bytes32 s,
        uint8 transferV,
        bytes32 transferR,
        bytes32 transferS
    ) external nonReentrant {
        if (amount_ == 0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (block.timestamp > deadline_) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        (bool success, bytes memory data) = _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(success, "Owner check failed");
        address owner = abi.decode(data, (address));

        uint256 nonce = nonces[owner];

        bytes32 structHash = keccak256(
            abi.encode(
                REPAY_WITH_ERC3009_TYPEHASH,
                nftId_,
                amount_,
                deadline_,
                validAfter_,
                validBefore_,
                transferNonce_,
                nonce
            )
        );

        bytes32 digest = keccak256(abi.encodePacked("\u0019\u0001", DOMAIN_SEPARATOR(), structHash));

        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidSignature);
        }

        address signer = ecrecover(digest, v, r, s);

        if (signer == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyOwner);
        }

        if (signer != owner) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyOwner);
        }

        nonces[owner]++;

        // Determine routing early so we can conditionally accrue interest for legacy positions
        address token = positionToken[nftId_];
        uint256 marketId = positionMarket[nftId_];
        bool isLegacy = _isLegacyMarket(marketId);

        // Accrue interest before reading debt to synchronize exchange rate between VM and LP.
        // Legacy: writes accrued interest into positionData (old formula).
        // New: triggers LP to update borrowExchangeRate so _getCurrentDebtFromShares reads a fresh rate.
        if (isLegacy) {
            _accruePositionInterest(nftId_);
        } else {
            (bool accrueSuccess,) =
                _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", marketId));
            require(accrueSuccess, "Market accrue failed");
        }

        (bool isActive, uint256 collateralSats, uint256 principal,, uint256 tickCount) =
            _unpackPositionData(positionData[nftId_]);

        if (!isActive) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionNotActive);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        // Live debt: legacy = principal (already has interest from accrual above)
        //            new    = borrowShares × LP.borrowExchangeRate
        uint256 actualDebt = isLegacy ? principal : _getCurrentDebtFromShares(nftId_);

        IERC3009(token)
            .receiveWithAuthorization(
                owner,
                address(this),
                amount_,
                validAfter_,
                validBefore_,
                transferNonce_,
                transferV,
                transferR,
                transferS
            );

        // Cap repay to actual debt (may differ from amount_ due to interest accrual)
        uint256 repayAmount = amount_ > actualDebt ? actualDebt : amount_;

        // Refund excess if user signed more than actual debt
        if (amount_ > repayAmount) {
            (bool refundSuccess,) =
                token.call(abi.encodeWithSignature("transfer(address,uint256)", owner, amount_ - repayAmount));
            require(refundSuccess, "Refund failed");
        }

        if (isLegacy) {
            // Route to old LiquidityPool (3 parameters, no marketId)
            require(_oldLiquidityPool.code.length > 0, "Old LP not set");
            (bool approveSuccess,) =
                token.call(abi.encodeWithSignature("approve(address,uint256)", _oldLiquidityPool, repayAmount));
            require(approveSuccess, "Approve failed");

            (bool success2,) = _oldLiquidityPool.call(
                abi.encodeWithSignature("repay(address,address,uint256)", token, address(this), repayAmount)
            );
            require(success2, "Old LP repay failed");
        } else {
            // Route to new LP; capture returned sharesToBurn to update positionBorrowShares
            (bool approveSuccess,) =
                token.call(abi.encodeWithSignature("approve(address,uint256)", _liquidityPool, repayAmount));
            require(approveSuccess, "Approve failed");

            (bool success2, bytes memory repayData) = _liquidityPool.call(
                abi.encodeWithSignature("repay(address,address,uint256,uint256)", token, owner, repayAmount, marketId)
            );
            require(success2, "Liquidity repay failed");
            uint256 sharesToBurn = abi.decode(repayData, (uint256));
            if (repayAmount >= actualDebt) {
                // Full repayment: zero shares directly to avoid rounding dust
                positionBorrowShares[nftId_] = 0;
            } else {
                positionBorrowShares[nftId_] =
                    positionBorrowShares[nftId_] > sharesToBurn ? positionBorrowShares[nftId_] - sharesToBurn : 0;
            }
        }

        // Scale repayAmount into principal space for tick accounting
        // (principal tracks original debt; live debt includes interest for new positions)
        uint256 principalToDeduct = (isLegacy || actualDebt == 0) ? repayAmount : (repayAmount * principal) / actualDebt;

        uint256 remaining = principalToDeduct;
        for (uint256 i = tickCount; i > 0 && remaining > 0; i--) {
            (bool tickActive, int24 tick, uint256 tickColl, uint256 tickDebt,) =
                _unpackTickPosition(tickPositions[nftId_][i - 1]);

            if (!tickActive || tickDebt == 0) continue;

            uint256 repayAmt = remaining > tickDebt ? tickDebt : remaining;
            tickDebt -= repayAmt;
            remaining -= repayAmt;

            if (tickDebt == 0) {
                tickPositions[nftId_][i - 1] = 0;
            } else {
                tickPositions[nftId_][i - 1] = _packTickPosition(tick, tickColl, tickDebt);
            }

            _updateTickData(tick, -int256(repayAmt));
        }

        // Compute new principal: for legacy subtract directly; for new scale proportionally
        uint256 newPrincipal;
        if (isLegacy) {
            newPrincipal = principal > repayAmount ? principal - repayAmount : 0;
        } else {
            newPrincipal = actualDebt > repayAmount ? (principal * (actualDebt - repayAmount)) / actualDebt : 0;
        }

        positionData[nftId_] = _packPositionData(collateralSats, newPrincipal, tickCount);

        if (newPrincipal == 0 && positionBorrowShares[nftId_] == 0) {
            if (!isLegacy) {
                positionBorrowShares[nftId_] = 0;
                uint256 activeCount = marketActiveDebtCount[marketId];
                if (activeCount > 0) marketActiveDebtCount[marketId] = activeCount - 1;
                // Best-effort: if the pool's finalize reverts (e.g. its pre-ledger fallback scan
                // runs out of gas on a dust-Sybil-inflated depositor queue), do NOT block the
                // borrower's repay. The debt is already cleared above; admin retries via the
                // pool's finalizeMarketDust to complete market close.
                (bool finalizeSuccess,) =
                    _liquidityPool.call(abi.encodeWithSignature("finalizeMarketDust(uint256)", marketId));
                if (!finalizeSuccess) emit LogMarketDustFinalizeDeferred(marketId);
            }
        }
        // Vault totals track principal for new positions; live debt (repayAmount) can exceed principal
        uint256 vaultDebtDeduction = isLegacy ? repayAmount : principalToDeduct;
        _updateVaultTotals(0, -int256(vaultDebtDeduction));

        emit LogDebtRepaid(nftId_, repayAmount, newPrincipal);
    }

    /**
     * |
     * |        Relayer Functions          |
     * |__________________________________
     */
    /// @notice Check position health and create auction if underwater
    function checkHealth(uint256 nftId_) external nonReentrant whenNotPaused {
        if (auctionHouse == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        // Accrue LP interest first so _accruePositionInterest reads a fresh exchange rate.
        uint256 marketId = positionMarket[nftId_];
        if (!_isLegacyMarket(marketId)) {
            (bool accrueSuccess,) =
                _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", marketId));
            require(accrueSuccess, "Market accrue failed");
        }
        // Legacy → writes interest to storage; new → returns borrowShares × fresh LP rate
        uint256 liveDebt = _accruePositionInterest(nftId_);

        (bool isActive, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        if (!isActive) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionNotActive);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        uint256 btcPrice = _getOraclePriceLiquidate();

        // Get liquidation threshold and penalty
        bool isLegacy = _isLegacyMarket(marketId);
        uint256 liqThresholdBps;
        uint256 liqPenalty;

        if (isLegacy) {
            // Use legacy parameters for old positions
            (, liqThresholdBps, liqPenalty) = this.getLegacyParams();
        } else {
            // Get market's liquidation threshold from new LP
            (bool successThreshold, bytes memory dataThreshold) =
                _liquidityPool.staticcall(abi.encodeWithSignature("getMarketLiquidationThreshold(uint256)", marketId));
            require(successThreshold && dataThreshold.length > 0, "Failed to get liquidation threshold");
            liqThresholdBps = abi.decode(dataThreshold, (uint256));
            liqPenalty = _getVaultParams();
        }

        // New markets: liqThresholdBps is an LTV (e.g. 8500 = 85%), convert to CR.
        // Legacy markets: liqThresholdBps from getLegacyParams() is already a CR (e.g. 12000 = 120%), no inversion.
        uint256 liqThreshold = isLegacy ? liqThresholdBps : (10000 * 10000) / liqThresholdBps;

        // Health check uses live debt (shares × rate for new; stored+interest for legacy)
        uint256 positionCR = _calculateCollateralRatio(collateralSats, liveDebt, btcPrice);

        if (positionCR >= liqThreshold * 1e12) {
            emit LogHealthChecked(nftId_, positionCR);
            return;
        }

        // Add penalty to live debt for auction price calculation
        uint256 effectiveDebt = (liveDebt * (10000 + liqPenalty)) / 10000;
        uint256 collateralToLiquidate = (effectiveDebt * BTC_PRECISION * ORACLE_PRECISION) / btcPrice;
        if (collateralToLiquidate > collateralSats) {
            collateralToLiquidate = collateralSats;
        }
        pendingWithdrawals[nftId_] = 0;
        inLiquidation[nftId_] = true;

        (bool successOwner, bytes memory dataOwner) =
            _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(successOwner, "Owner check failed");
        address owner = abi.decode(dataOwner, (address));
        address token = positionToken[nftId_];

        IAuctionHouse(auctionHouse).createAuction(nftId_, token, effectiveDebt, collateralToLiquidate, owner);

        // Store liveDebt (not principal) so finalizeAuction has the right base
        liquidationDetails[nftId_] = LiquidationDetails({
            collateralSats: collateralSats,
            debtStable: liveDebt,
            liquidationPenalty: liqPenalty,
            collateralToLiquidate: collateralToLiquidate,
            timestamp: block.timestamp,
            isActive: true,
            marketId: marketId,
            liquidationType: LiquidationType.FullLiquidation
        });

        emit LogLiquidationTriggered(nftId_, collateralSats, liveDebt, liqPenalty, collateralToLiquidate);
    }

    /// @notice Trigger delinquency settlement when a position's exit block is within the delinquent window.
    ///         Seizes collateral worth liveDebt + liquidation penalty + delinquency penalty.
    ///         Remaining collateral stays in positionData (isActive=false) for user to reclaim.
    /// @param nftId_            Position NFT ID
    /// @param currentBtcBlock_  Current Bitcoin block number (provided by caller; not available on-chain)
    function checkDelinquency(uint256 nftId_, uint256 currentBtcBlock_) external onlyAdmin nonReentrant whenNotPaused {
        if (auctionHouse == address(0)) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        uint256 exitBlock = positionExitBlock[nftId_];
        require(exitBlock > 0, "Exit block not set");

        require(currentBtcBlock_ <= exitBlock, "Exit block already passed");
        int256 effectiveExitBlock = int256(exitBlock) - delinquentBuffer;
        require(effectiveExitBlock > 0 && currentBtcBlock_ >= uint256(effectiveExitBlock), "Not delinquent");

        uint256 marketId = positionMarket[nftId_];
        if (!_isLegacyMarket(marketId)) {
            (bool accrueSuccess,) =
                _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", marketId));
            require(accrueSuccess, "Market accrue failed");
        }
        uint256 liveDebt = _accruePositionInterest(nftId_);

        (bool isActive, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        if (!isActive) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionNotActive);
        }

        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }

        // If no debt, just close the position — no auction needed
        if (liveDebt == 0) {
            positionData[nftId_] &= ~uint256(1);
            emit LogDelinquencyTriggered(nftId_, collateralSats, 0, 0, 0);
            return;
        }

        uint256 btcPrice = _getOraclePriceLiquidate();

        // Fetch liquidation penalty
        uint256 liqPenalty;
        if (_isLegacyMarket(marketId)) {
            (,, liqPenalty) = this.getLegacyParams();
        } else {
            liqPenalty = _getVaultParams();
        }

        // auctionDebt: what the buyer pays (debt + liquidation penalty only)
        // collateralToSeize: BTC seized includes buyerDiscount on top — giving buyer extra BTC as incentive
        // effectiveDebt is in USDC (6 decimals); btcPrice is USD * 1e27 (no USDC decimal),
        // so divide by 1e6 to normalize and get the correct sats equivalent.
        uint256 auctionDebt = (liveDebt * (10000 + liqPenalty)) / 10000;
        uint256 seizeValue = (liveDebt * (10000 + liqPenalty + buyerDiscount)) / 10000;
        uint256 collateralToSeize = (seizeValue * BTC_PRECISION * ORACLE_PRECISION) / (btcPrice * 1e6);
        if (collateralToSeize > collateralSats) collateralToSeize = collateralSats;

        // Mark position inactive immediately — clears isActive bit (bit 0) without touching other packed values
        positionData[nftId_] &= ~uint256(1);

        pendingWithdrawals[nftId_] = 0;
        inLiquidation[nftId_] = true;

        (bool successOwner, bytes memory dataOwner) =
            _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(successOwner, "Owner check failed");
        address owner = abi.decode(dataOwner, (address));
        address token = positionToken[nftId_];

        IAuctionHouse(auctionHouse).createAuction(nftId_, token, auctionDebt, collateralToSeize, owner);

        liquidationDetails[nftId_] = LiquidationDetails({
            collateralSats: collateralSats,
            debtStable: liveDebt,
            liquidationPenalty: liqPenalty,
            collateralToLiquidate: collateralToSeize,
            timestamp: block.timestamp,
            isActive: true,
            marketId: marketId,
            liquidationType: LiquidationType.Delinquency
        });

        emit LogDelinquencyTriggered(nftId_, collateralSats, liveDebt, liqPenalty + buyerDiscount, collateralToSeize);
    }

    /// @notice Finalize auction after successful purchase
    function finalizeAuction(uint256 nftId_, uint256 collateralSold_, uint256 debtRepaid_)
        external
        nonReentrant
        whenNotPaused
    {
        if (msg.sender != auctionHouse) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyAuctionHouse);
        }

        address token = positionToken[nftId_];
        bool isLegacy = _isLegacyMarket(positionMarket[nftId_]);

        // AuctionHouse already holds the tokens and has approved VaultManager
        (bool transferSuccess,) = token.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", auctionHouse, address(this), debtRepaid_)
        );
        require(transferSuccess, "Token transfer failed");

        if (isLegacy) {
            // Legacy position - route to old LP without auction interest calculation
            require(_oldLiquidityPool.code.length > 0, "Old LP not set");
            (bool approveSuccess,) =
                token.call(abi.encodeWithSignature("approve(address,uint256)", _oldLiquidityPool, debtRepaid_));
            require(approveSuccess, "Approve failed");

            (bool repaySuccess,) = _oldLiquidityPool.call(
                abi.encodeWithSignature("repay(address,address,uint256)", token, address(this), debtRepaid_)
            );
            require(repaySuccess, "Old LP liquidation repay failed");
        } else {
            // New position: derive current debt from shares × LP.borrowExchangeRate
            // (this automatically includes all interest accrued up to and during the auction)
            uint256 marketId = liquidationDetails[nftId_].marketId;
            // Accrue first so borrowedValue_ matches the rate repayFromLiquidation will burn at,
            // making sharesToBurn == totalBorrowShares and zeroing the borrow side cleanly.
            (bool acc,) = _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", marketId));
            require(acc, "Market accrue failed");
            uint256 borrowedValue_ = _getCurrentDebtFromShares(nftId_);

            (bool approveSuccess,) =
                token.call(abi.encodeWithSignature("approve(address,uint256)", _liquidityPool, debtRepaid_));
            require(approveSuccess, "Approve failed");

            (bool repaySuccess,) = _liquidityPool.call(
                abi.encodeWithSignature(
                    "repayFromLiquidation(uint256,uint256,uint256)", marketId, debtRepaid_, borrowedValue_
                )
            );
            require(repaySuccess, "Liquidity repay failed");

            // Clear borrow shares — full liquidation zeros the position's debt
            positionBorrowShares[nftId_] = 0;

            // Decrement market debt count and finalize dust
            uint256 activeCount = marketActiveDebtCount[marketId];
            if (activeCount > 0) marketActiveDebtCount[marketId] = activeCount - 1;
            // Best-effort (see repay path): a failed finalize must not block liquidation close.
            (bool finalizeSuccess,) =
                _liquidityPool.call(abi.encodeWithSignature("finalizeMarketDust(uint256)", marketId));
            if (!finalizeSuccess) emit LogMarketDustFinalizeDeferred(marketId);
        }

        // Common VM-side cleanup: clear tick positions and update vault totals.
        (, uint256 positionCollateral, uint256 positionPrincipal,, uint256 tickCount) =
            _unpackPositionData(positionData[nftId_]);
        for (uint256 i = 0; i < tickCount; i++) {
            (, int24 tick,, uint256 tickDebt,) = _unpackTickPosition(tickPositions[nftId_][i]);
            if (tickDebt > 0) {
                _updateTickData(tick, -int256(tickDebt));
                tickPositions[nftId_][i] = 0;
            }
        }

        liquidationDetails[nftId_].isActive = false;
        inLiquidation[nftId_] = false;

        if (liquidationDetails[nftId_].liquidationType == LiquidationType.Delinquency) {
            // Keep remaining collateral in positionData (isActive=false, debt=0)
            uint256 collateralSeized = liquidationDetails[nftId_].collateralToLiquidate;
            uint256 remainingCollateral =
                positionCollateral > collateralSeized ? positionCollateral - collateralSeized : 0;
            // Pack remaining collateral with isActive=false (clear bit 0)
            positionData[nftId_] = _packPositionData(remainingCollateral, 0, 0) & ~uint256(1);
            // Only deduct seized collateral from vault totals; remaining stays tracked
            _updateVaultTotals(-int256(collateralSeized), -int256(positionPrincipal));
        } else {
            positionData[nftId_] = _packPositionData(0, 0, 0);
            _updateVaultTotals(-int256(positionCollateral), -int256(positionPrincipal));
        }

        emit LogAuctionFinalized(nftId_, collateralSold_, debtRepaid_);
    }

    /**
     * |
     * |          View Functions           |
     * |__________________________________
     */
    /// @notice Get EIP-712 domain separator
    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("SurgeVaultManager")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    /// @notice Set the extra buyer discount applied on top of liquidation penalty during delinquency seizure (in BPS).
    ///         Capped at 1000 bps (10%) — a large discount drives collateralToSeize to the full-collateral cap,
    ///         leaving the borrower with zero remainder while the buyer pays only debt + liqPenalty.
    function setBuyerDiscount(uint256 discount_) external onlyAdmin {
        require(discount_ <= 1000, "Buyer discount exceeds maximum");
        buyerDiscount = discount_;
        emit LogBuyerDiscountSet(discount_);
    }

    /// @notice Set the LTV buffer (in BPS) required below liquidation LTV to allow credit line extension requests
    function setExtensionLtvBuffer(uint256 buffer_) external onlyAdmin {
        extensionLtvBuffer = buffer_;
        emit LogExtensionLtvBufferSet(buffer_);
    }

    /// @notice Gasless request for a credit line extension — signed by position owner, relayed by anyone.
    ///         Position LTV must be <= (liquidationLTV - extensionLtvBuffer) to be eligible.
    function requestCreditLineExtension(uint256 nftId_, uint256 deadline_, uint8 v, bytes32 r, bytes32 s)
        external
        nonReentrant
        whenNotPaused
    {
        if (block.timestamp > deadline_) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        }

        if (inLiquidation[nftId_]) revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        if (pendingWithdrawals[nftId_] > 0) revert SurgeVaultError(ErrorTypes.VaultManager__InvalidAmount);
        if (pendingExtension[nftId_]) revert SurgeVaultError(ErrorTypes.VaultManager__PendingExtension);

        (bool ownerOk, bytes memory ownerData) =
            _positionNFT.staticcall(abi.encodeWithSignature("ownerOf(uint256)", nftId_));
        require(ownerOk, "Owner check failed");
        address owner = abi.decode(ownerData, (address));

        uint256 nonce = nonces[owner];
        bytes32 structHash = keccak256(abi.encode(EXTEND_CREDIT_LINE_TYPEHASH, nftId_, deadline_, nonce));
        bytes32 digest = keccak256(abi.encodePacked("\u0019\u0001", DOMAIN_SEPARATOR(), structHash));

        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
            revert SurgeVaultError(ErrorTypes.VaultManager__InvalidSignature);
        }

        address signer = ecrecover(digest, v, r, s);
        if (signer == address(0) || signer != owner) {
            revert SurgeVaultError(ErrorTypes.VaultManager__OnlyOwner);
        }

        nonces[owner]++;

        uint256 marketId = positionMarket[nftId_];
        if (!_isLegacyMarket(marketId)) {
            (bool accrueOk,) = _liquidityPool.call(abi.encodeWithSignature("accrueMarketInterest(uint256)", marketId));
            require(accrueOk, "Market accrue failed");
        }
        uint256 liveDebt = _accruePositionInterest(nftId_);
        (, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        uint256 liqThresholdBps;
        if (_isLegacyMarket(marketId)) {
            (, liqThresholdBps,) = this.getLegacyParams();
        } else {
            (bool okThreshold, bytes memory dThreshold) =
                _liquidityPool.staticcall(abi.encodeWithSignature("getMarketLiquidationThreshold(uint256)", marketId));
            require(okThreshold && dThreshold.length > 0, "Failed to get liquidation threshold");
            liqThresholdBps = abi.decode(dThreshold, (uint256));
        }

        uint256 btcPrice = _getOraclePrice();
        uint256 positionCR = _calculateCollateralRatio(collateralSats, liveDebt, btcPrice);
        // currentLtvBps = 1e8 * 1e12 / positionCR  (since CR_bps = 1e8 / ltv_bps and positionCR = CR_bps * 1e12)
        uint256 currentLtvBps = (1e8 * 1e12) / positionCR;

        // Legacy: liqThresholdBps is a CR (e.g. 12000 = 120% CR); convert to equivalent LTV for the LTV comparison.
        // New markets: liqThresholdBps is already an LTV (e.g. 8500 = 85%), use directly.
        uint256 liqLtvBps = _isLegacyMarket(marketId) ? (10000 * 10000) / liqThresholdBps : liqThresholdBps;

        require(currentLtvBps + extensionLtvBuffer <= liqLtvBps, "Position LTV too high to extend");

        pendingExtension[nftId_] = true;
        emit LogCreditLineExtendRequested(nftId_, owner);
    }

    /// @notice Set the global delinquent buffer (Bitcoin blocks) subtracted from positionExitBlock to open the seizure window.
    ///         Must be non-negative (negative values push effectiveExitBlock past exitBlock, disabling seizure).
    ///         Capped at 52416 blocks (~1 year) to prevent buffer >= exitBlock scenarios.
    function setDelinquentBuffer(int256 buffer_) external onlyAdmin {
        require(buffer_ >= 0, "Buffer must be non-negative");
        require(buffer_ <= 52416, "Buffer exceeds maximum");
        delinquentBuffer = buffer_;
        emit LogDelinquentBufferSet(buffer_);
    }

    /// @notice Set or update the exit block for a position, with optional collateral top-up.
    ///         If the position is inactive (delinquent), re-activates it by setting bit 0.
    ///         This is the admin approval path for credit line extension requests.
    /// @param newCollateralSats_ New total collateral in sats. Pass 0 to skip collateral update.
    function setPositionExitBlock(uint256 nftId_, uint256 exitBlock_, uint256 newCollateralSats_)
        external
        onlyAdmin
        whenNotPaused
    {
        require(positionData[nftId_] != 0, "Position not found");
        if (inLiquidation[nftId_]) {
            revert SurgeVaultError(ErrorTypes.VaultManager__PositionInLiquidation);
        }
        require(exitBlock_ > positionExitBlock[nftId_], "Must be greater than current exitBlock");
        positionExitBlock[nftId_] = exitBlock_;

        // Re-activate if position was marked inactive (e.g. delinquent awaiting extension approval)
        bool reactivated = (positionData[nftId_] & 1 == 0);
        if (reactivated) {
            positionData[nftId_] |= 1;
        }

        // Optionally top up collateral in the same transaction
        if (newCollateralSats_ > 0) {
            _addCollateral(nftId_, newCollateralSats_, CollateralUpdateType.ExitBlockUpdate);
        }

        pendingExtension[nftId_] = false;
        emit LogPositionExitBlockUpdated(nftId_, exitBlock_, reactivated);
    }

    /// @notice Get position details
    function getPosition(uint256 nftId_)
        external
        view
        returns (
            bool isActive_,
            uint256 collateralSats_,
            uint256 debtStable_,
            uint256 lastUpdate_,
            uint256 tickCount_,
            uint256 marketId_,
            uint256 exitBlock_,
            uint256 borrowShares_
        )
    {
        (isActive_, collateralSats_, debtStable_, lastUpdate_, tickCount_) = _unpackPositionData(positionData[nftId_]);
        marketId_ = positionMarket[nftId_];
        exitBlock_ = positionExitBlock[nftId_];
        borrowShares_ = positionBorrowShares[nftId_];
    }

    /// @notice Get specific tick position details
    function getTickPosition(uint256 nftId_, uint256 tickIndex_)
        external
        view
        returns (bool isActive_, int24 tick_, uint256 collateralSats_, uint256 debtStable_, uint256 createdAt_)
    {
        return _unpackTickPosition(tickPositions[nftId_][tickIndex_]);
    }

    /// @notice Get current collateral ratio
    function getCollateralRatio(uint256 nftId_) external view returns (uint256 cr_) {
        (bool isActive, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        if (!isActive) return 0;

        uint256 liveDebt;
        uint256 marketId = positionMarket[nftId_];
        if (!_isLegacyMarket(marketId)) {
            uint256 shares = positionBorrowShares[nftId_];
            if (shares > 0) {
                (bool ok, bytes memory data) = _liquidityPool.staticcall(
                    abi.encodeWithSignature("getProjectedBorrowExchangeRate(uint256)", marketId)
                );
                if (ok && data.length >= 32) {
                    liveDebt = (shares * abi.decode(data, (uint256))) / 1e18;
                }
            }
            if (liveDebt == 0) liveDebt = _getCurrentDebtFromShares(nftId_);
        } else {
            liveDebt = _getCurrentDebtFromShares(nftId_);
        }

        if (liveDebt == 0) return type(uint256).max;

        uint256 btcPrice = _getOraclePrice();
        cr_ = _calculateCollateralRatio(collateralSats, liveDebt, btcPrice);
    }

    /// @notice Returns true if market still has at least one active debt position
    function hasActiveDebtInMarket(uint256 marketId_) external view returns (bool) {
        return marketActiveDebtCount[marketId_] > 0;
    }

    /// @notice Get vault parameters
    function getVaultParams() external view returns (uint256 liqPenalty_) {
        return _getVaultParams();
    }

    /// @notice Get legacy vault parameters (from old single-market system)
    function getLegacyParams() external pure returns (uint256 minCR_, uint256 liqThreshold_, uint256 liqPenalty_) {
        minCR_ = 20000; // 200%
        liqThreshold_ = 11111; // 90%
        liqPenalty_ = 500; // 5%
    }

    /// @notice Get total vault stats
    function getTotals() external view returns (uint256 totalCollateral_, uint256 totalDebt_) {
        uint256 vars = vaultVars;
        totalCollateral_ = (vars >> 1) & X64;
        totalDebt_ = (vars >> 65) & X64;
    }

    /// @notice Get token for a position
    function getPositionToken(uint256 nftId_) external view returns (address token_) {
        token_ = positionToken[nftId_];
    }

    /// @notice Get position debt with interest
    function getPositionDebtWithInterest(uint256 nftId_)
        external
        view
        returns (uint256 principal_, uint256 interest_, uint256 total_)
    {
        uint256 packed = positionData[nftId_];
        if (packed == 0) return (0, 0, 0);

        (,, principal_,,) = _unpackPositionData(packed);

        if (!_isLegacyMarket(positionMarket[nftId_])) {
            // Shares-based position: use projected exchange rate for live debt display.
            // getProjectedBorrowExchangeRate is a pure view — no gas, no state change.
            uint256 shares = positionBorrowShares[nftId_];
            if (shares == 0) {
                principal_ = 0;
                interest_ = 0;
                total_ = 0;
            } else {
                uint256 marketId = positionMarket[nftId_];
                (bool ok, bytes memory data) = _liquidityPool.staticcall(
                    abi.encodeWithSignature("getProjectedBorrowExchangeRate(uint256)", marketId)
                );
                if (ok && data.length >= 32) {
                    total_ = (shares * abi.decode(data, (uint256))) / 1e18;
                } else {
                    total_ = _getCurrentDebtFromShares(nftId_);
                }
                interest_ = total_ > principal_ ? total_ - principal_ : 0;
            }
        } else {
            // Legacy position: use old simple-interest formula
            interest_ = _calculatePositionInterest(nftId_);
            total_ = principal_ + interest_;
        }
    }

    /// @notice Get position health
    function getPositionHealth(uint256 nftId_)
        external
        view
        returns (uint256 collateralValue_, uint256 debtValue_, uint256 healthFactor_)
    {
        (bool isActive, uint256 collateralSats,,,) = _unpackPositionData(positionData[nftId_]);

        if (!isActive) return (0, 0, 0);

        debtValue_ = _getDebtWithInterest(nftId_);
        uint256 btcPrice = _getOraclePrice();
        collateralValue_ = (collateralSats * btcPrice) / BTC_PRECISION;

        if (debtValue_ == 0) {
            healthFactor_ = type(uint256).max;
        } else {
            healthFactor_ = (collateralValue_ * BASIS_POINTS) / (debtValue_ * 1e9);
        }
    }

    function getLoanExpiry(uint256 nftId_)
        external
        view
        returns (bool expired_, uint256 expiryTime_, uint256 timeRemaining_)
    {
        expiryTime_ = loanExpiry[nftId_];
        expired_ = block.timestamp > expiryTime_;
        timeRemaining_ = expired_ ? 0 : expiryTime_ - block.timestamp;
    }

    /// @notice Get current admin address
    function getCurrentAdmin() external view returns (address admin_) {
        admin_ = currentAdmin == address(0) ? _admin : currentAdmin;
    }

    /// @notice Get pending admin address
    function getPendingAdmin() external view returns (address pendingAdmin_) {
        pendingAdmin_ = pendingAdmin;
    }

    /// @notice Override to calculate interest using correct marketId from positionMarket mapping.
    ///         New positions (non-legacy) return 0 — debt is derived from borrow shares instead.
    function _calculatePositionInterest(uint256 nftId_) internal view override returns (uint256 interest_) {
        uint256 marketId = positionMarket[nftId_];
        if (marketId != type(uint256).max) return 0; // new positions: no per-position accrual

        // Legacy path: old simple-interest formula
        uint256 packed = positionData[nftId_];
        if (packed == 0) return 0;

        (,, uint256 debtStable, uint256 lastUpdate,) = _unpackPositionData(packed);
        if (debtStable == 0) return 0;

        uint256 timeElapsed = block.timestamp - lastUpdate;
        if (timeElapsed == 0) return 0;

        address token = positionToken[nftId_];
        (bool success, bytes memory data) =
            _oldLiquidityPool.staticcall(abi.encodeWithSignature("getBorrowRate(address)", token));
        if (!success || data.length == 0) return 0;
        uint256 borrowRateBps = abi.decode(data, (uint256));

        interest_ = (debtStable * borrowRateBps * timeElapsed) / (10000 * 365 days);
    }

    /// @notice Active debt position count per market (debtStable > 0 positions)
    mapping(uint256 => uint256) public marketActiveDebtCount;

    /// @notice Pause manager address (can pause and unpause)
    address public pauseManager;

    /// @notice Pending pause manager address for two-step transfer
    address public pendingPauseManager;

    /// @notice Global borrow cap in USDC (6 decimals). 0 = no cap.
    uint256 public positionBorrowCap;

    /// @notice Borrow shares per position (source of truth for debt in new share-based model)
    mapping(uint256 => uint256) public positionBorrowShares;

    /// @notice Bitcoin block number at which the locked BTC can be withdrawn (no-surge exit)
    /// nftId => Bitcoin block number
    mapping(uint256 => uint256) public positionExitBlock;

    /// @notice Global buffer (in Bitcoin blocks) applied as +/- offset to positionExitBlock during health checks
    int256 public delinquentBuffer;

    /// @notice Extra discount (in BPS) given to auction buyer on top of liquidation penalty during delinquency seizure
    uint256 public buyerDiscount;

    /// @notice Minimum LTV buffer (in BPS) below the liquidation LTV required to request a credit line extension
    uint256 public extensionLtvBuffer;

     /// @notice Positions with a pending credit line extension request (nftId => pending)
    mapping(uint256 => bool) public pendingExtension;


    /// @dev Reserved storage gap for future upgrades
    /// Current gap is 30 slots.
    uint256[30] private __gap;

    // ============================================================
    // Shares-based interest helpers (overrides)
    // ============================================================

    /// @dev Returns true if marketId is out of LP range (legacy/unassigned position).
    function _isLegacyMarket(uint256 marketId_) internal view returns (bool) {
        (bool ok, bytes memory data) = _liquidityPool.staticcall(abi.encodeWithSignature("marketCount()"));
        if (!ok || data.length < 32) return true;
        return marketId_ >= abi.decode(data, (uint256));
    }

    /// @notice Returns live debt for a position using borrow shares × LP borrowExchangeRate.
    ///         For legacy positions (marketId out of LP range) falls back to old formula.
    function _getCurrentDebtFromShares(uint256 nftId_) internal view override returns (uint256 debt_) {
        uint256 marketId = positionMarket[nftId_];
        if (_isLegacyMarket(marketId)) {
            // Legacy: use stored debtStable + accrued interest via old formula
            uint256 packed = positionData[nftId_];
            if (packed == 0) return 0;
            (,, uint256 debtStable,,) = _unpackPositionData(packed);
            uint256 interest = _calculatePositionInterest(nftId_);
            return debtStable + interest;
        }
        uint256 shares = positionBorrowShares[nftId_];
        if (shares == 0) return 0;
        (bool ok, bytes memory data) =
            _liquidityPool.staticcall(abi.encodeWithSignature("getMarketBorrowExchangeRate(uint256)", marketId));
        if (!ok || data.length == 0) return 0;
        uint256 rate = abi.decode(data, (uint256));
        debt_ = (shares * rate) / 1e18;
    }

    /// @notice Overrides base accrual:
    ///   - Legacy positions: writes interest to positionData (old behaviour preserved).
    ///   - New positions: only updates the timestamp; returns live shares-based debt.
    function _accruePositionInterest(uint256 nftId_) internal override returns (uint256 newDebt_) {
        uint256 marketId = positionMarket[nftId_];
        if (_isLegacyMarket(marketId)) {
            // Legacy path: write interest to storage (unchanged behaviour)
            return super._accruePositionInterest(nftId_);
        }
        // New path: touch timestamp without inflating debtStable
        uint256 packed = positionData[nftId_];
        (bool isActive, uint256 collateralSats, uint256 debtStable,, uint256 tickCount) = _unpackPositionData(packed);
        positionData[nftId_] = (isActive ? 1 : 0) | (collateralSats << 1) | (debtStable << 65)
            | (block.timestamp << 129) | (tickCount << 193);
        newDebt_ = _getCurrentDebtFromShares(nftId_);
    }
}
